// HOW Platform curriculum data — auto-extracted
var JUZ = [{"w": 1, "tr": "Al-Khaliq", "meaning": "The Creator", "theme": "Creation & beginnings", "story": "Before anything was, there was only Allah. Creation is a continuous act — every moment, existence is being held in being.", "q": "What was created from nothing in your work this week?", "hadithTr": "Actions are judged by intentions", "hadithSrc": "Bukhari 1", "quranSurahs": "Al-Fatihah 1 — Al-Baqarah 2:1–141", "quranTheme": "The covenant — Al-Fatihah establishes the relationship between the servant and Allah; Al-Baqarah opens with the terms of guidance, the qualities of the muttaqeen, and the stories of those who accepted or rejected the covenant.", "quranRef": "Al-Fatihah 1:1 — 'Alif Lam Meem. That is the Book in which there is no doubt, a guidance for the muttaqeen.' (2:1–2)", "quranQuestion": "What does it mean to enter into a relationship with guidance — to accept that a book can orient your whole life?"}, {"w": 2, "tr": "Al-Bari", "meaning": "The Originator of distinct forms", "theme": "Signs & patterns", "story": "Al-Bari gave each thing its own distinct nature — the circle its circularity, the number three its threeness. Distinctness is a divine gift.", "q": "What made the thing you studied this week irreducibly itself?", "hadithTr": "The religion is sincere counsel", "hadithSrc": "Muslim 55", "quranSurahs": "Al-Baqarah 2:142–252", "quranTheme": "The Ummah and its direction — the change of qiblah establishes the Muslim community's distinct identity; this Juz covers the laws of fasting, pilgrimage, marriage, and fighting, and the story of Tālūt and Jālūt as a parable of small but faithful communities overcoming great odds.", "quranRef": "Al-Baqarah 2:142 — 'The foolish among people will say: What has turned them away from their qiblah which they used to face?'", "quranQuestion": "What makes a community distinct — and what responsibilities come with a distinct identity?"}, {"w": 3, "tr": "Al-Musawwir", "meaning": "The Shaper of forms", "theme": "Structure & foundation", "story": "Al-Musawwir is the First Artist — giving each substance its particular face, the appearance that makes it recognisable.", "q": "What form did an abstract idea take this week?", "hadithTr": "Speak good or remain silent", "hadithSrc": "Bukhari 6018", "quranSurahs": "Al-Baqarah 2:253–286 — Aal Imran 3:1–92", "quranTheme": "The living and the dead — Ayat al-Kursi establishes Allah's sovereignty over all creation; Aal Imran opens with the confirmation of previous scriptures and the story of Maryam and Isa, showing that truth was always one even when its expressions differed.", "quranRef": "Al-Baqarah 2:255 — Ayat al-Kursi: 'Allah — there is no deity except Him, the Ever-Living, the Sustainer of existence.'", "quranQuestion": "What does it mean that the same truth was sent to different peoples in different forms — and what does that require of us?"}, {"w": 4, "tr": "Al-Razzaq", "meaning": "The Provider", "theme": "Division & distribution", "story": "Provision is not only food — it is knowledge, companionship, understanding. The scholar who finds the proof they needed: this is rizq.", "q": "What were you provided this week that you could not have produced yourself?", "hadithTr": "None truly believes until he loves for his brother what he loves for himself", "hadithSrc": "Bukhari 13", "quranSurahs": "Aal Imran 3:93–200 — An-Nisa 4:1–23", "quranTheme": "Trial and steadfastness — the Battle of Uhud and its lessons dominate this Juz; defeat is reframed as a test and a purification, and the community is commanded to hold together through difficulty rather than fracture.", "quranRef": "Aal Imran 3:139 — 'Do not lose heart or grieve — you will be superior if you are true believers.'", "quranQuestion": "What is the difference between a defeat that breaks you and a defeat that teaches you?"}, {"w": 5, "tr": "Al-Alim", "meaning": "The All-Knowing", "theme": "Measurement & proportion", "story": "Human knowledge is always partial, always from a position, always incomplete. Only Allah possesses perfect knowledge simultaneously.", "q": "What is the difference between what you know and what is known?", "hadithTr": "Seeking knowledge is an obligation upon every Muslim", "hadithSrc": "Ibn Majah 224", "quranSurahs": "An-Nisa 4:24–147", "quranTheme": "Justice for the vulnerable — An-Nisa concentrates on the rights of orphans, women, the poor, and those oppressed; it establishes that a just community protects those who cannot protect themselves, and that hypocrisy in social dealings is a form of spiritual failure.", "quranRef": "An-Nisa 4:36 — 'Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbour...'", "quranQuestion": "Who is most vulnerable in your community — and what does the Quran say you owe them?"}, {"w": 6, "tr": "Al-Sami", "meaning": "The All-Hearing", "theme": "Knowledge & trust", "story": "Al-Sami is the model of listening as a complete act — hearing not just words but the person behind the words.", "q": "What did you hear this week that you were not listening for?", "hadithTr": "The Muslim is one from whose tongue and hand others are safe", "hadithSrc": "Bukhari 10", "quranSurahs": "An-Nisa 4:148–176 — Al-Ma'idah 5:1–81", "quranTheme": "Integrity of covenant — Al-Ma'idah opens 'O you who believe, fulfil your contracts'; this Juz is about keeping promises to Allah, to other people, and to communities, and the consequences of breaking them across the stories of Bani Israel and the People of the Book.", "quranRef": "Al-Ma'idah 5:1 — 'O you who have believed, fulfil your contracts.'", "quranQuestion": "What contracts do you hold right now — and what would it mean to fulfil each one completely?"}, {"w": 7, "tr": "Al-Basir", "meaning": "The All-Seeing", "theme": "Inquiry & observation", "story": "Ibn al-Haytham showed that vision is reception of light, not emission from the eye. Al-Basir sees by an attribute that has no analogy in creation.", "q": "What did you see this week that you had looked at before but never noticed?", "hadithTr": "Allah is beautiful and loves beauty", "hadithSrc": "Muslim 911", "quranSurahs": "Al-Ma'idah 5:82–120 — Al-An'am 6:1–110", "quranTheme": "Tawheed against idolatry — Al-An'am (revealed all at once, accompanied by seventy thousand angels) is a sustained argument for the oneness of Allah against every form of shirk, using nature, reason, and the stories of the Prophets as evidence.", "quranRef": "Al-An'am 6:1 — 'Praise be to Allah, who created the heavens and the earth and made the darkness and the light — then those who disbelieve equate others with their Lord.'", "quranQuestion": "What do you give your unconditional trust to — and what does that reveal about where your heart actually rests?"}, {"w": 8, "tr": "Al-Muhit", "meaning": "The All-Encompassing", "theme": "Circles & proportion", "story": "Al-Muhit surrounds all existence the way the ocean surrounds all islands — containing, preserving, always present at every shore.", "q": "After studying circles and proportion: what is the relationship between a mathematical limit and the Limitless?", "hadithTr": "The best of you are those who learn and teach", "hadithSrc": "Bukhari 5027", "quranSurahs": "Al-An'am 6:111–165 — Al-A'raf 7:1–87", "quranTheme": "The nature of rejection — Al-A'raf examines why people refuse the truth: not for lack of evidence but for pride, habit, and the comfort of the majority; the stories of the Prophets show that every messenger faced the same resistance from those who preferred the familiar to the true.", "quranRef": "Al-A'raf 7:2 — 'A Book sent down to you — let there be no distress in your heart because of it — that you may warn thereby and a reminder to the believers.'", "quranQuestion": "What would you have to give up to accept something true that you currently resist?"}, {"w": 9, "tr": "Al-Latif", "meaning": "The Subtly Kind", "theme": "Living systems", "story": "Al-Latif appears in the fact that the seed knows which direction is up before it reaches the surface — every provision that arrives before the need was named.", "q": "Where did you notice subtle care in what you studied this week?", "hadithTr": "Allah is gentle and loves gentleness", "hadithSrc": "Bukhari 6927", "quranSurahs": "Al-A'raf 7:88–206 — Al-Anfal 8:1–40", "quranTheme": "Community under pressure — Al-Anfal covers the Battle of Badr: a small, faithful community against an overwhelming force; the Juz explores what holds a community together under existential pressure and what causes it to fragment.", "quranRef": "Al-Anfal 8:2 — 'The believers are only those who, when Allah is mentioned, their hearts tremble...'", "quranQuestion": "What holds your community together when it is under pressure — and what is most likely to fracture it?"}, {"w": 10, "tr": "Al-Halim", "meaning": "The Forbearing", "theme": "Change & time", "story": "Al-Halim does not hasten to punish despite full knowledge of every wrong — forbearance as a complete disposition.", "q": "Where this week did you have the power to respond harshly and chose not to?", "hadithTr": "Whoever does not thank people has not thanked Allah", "hadithSrc": "Abu Dawud 4811", "quranSurahs": "Al-Anfal 8:41 — At-Tawbah 9:92", "quranTheme": "Accountability and repentance — At-Tawbah (the only Surah without Bismillah) is the Quran's harshest address, confronting hypocrisy directly; the Juz establishes that change of heart — tawbah — is always possible, and that Allah's acceptance of it is not conditional on human worthiness.", "quranRef": "At-Tawbah 9:118 — 'And to the three who were left behind... the earth despite its vastness seemed to close in on them, and their own souls seemed to close in on them, and they were certain there is no refuge from Allah except in Him.'", "quranQuestion": "What does it take to admit, publicly and fully, that you were wrong?"}, {"w": 11, "tr": "Al-Azim", "meaning": "The Magnificent", "theme": "Language & transmission", "story": "Azim means great not in size but in weight — the kind of greatness that has gravity, that bends the space around it.", "q": "What this week had a pull on you without being large or loud?", "hadithTr": "Be mindful of Allah wherever you are", "hadithSrc": "Tirmidhi 1987", "quranSurahs": "At-Tawbah 9:93 — Hud 11:5", "quranTheme": "The prophetic pattern — Yunus, Hud, and the beginning of Hud all show the same arc: a prophet sent to a people, the people's resistance, a consequence, and the survival of those who believed; the pattern is not punishment but mercy in disguise.", "quranRef": "Yunus 10:3 — 'Indeed, your Lord is Allah who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter of all things.'", "quranQuestion": "What pattern do you see repeating in the stories of the Prophets — and what does the repetition tell you?"}, {"w": 12, "tr": "Al-Ghafur", "meaning": "The Most Forgiving", "theme": "Order & structure", "story": "To forgive is not just to pardon but to cover and conceal. Al-Ghafur does not merely excuse — He buries.", "q": "What from this week deserves to be covered — learned from and then let go?", "hadithTr": "Silence is wisdom, yet few practise it", "hadithSrc": "Bayhaqi", "quranSurahs": "Hud 11:6 — Yusuf 12:52", "quranTheme": "Patience and divine planning — Surah Yusuf is the Quran's most complete narrative: betrayal, imprisonment, false accusation, slow redemption; it is explicitly called 'the best of stories' and demonstrates that every apparent setback was part of a plan the protagonist could not yet see.", "quranRef": "Yusuf 12:3 — 'We relate to you the best of stories in what We have revealed to you of this Quran, although you were, before it, among the unaware.'", "quranQuestion": "When you are in the middle of a difficulty, how do you hold the possibility that it is part of something you cannot yet see?"}, {"w": 13, "tr": "Al-Hakim", "meaning": "The All-Wise", "theme": "Wisdom & revelation", "story": "Wisdom is different from knowledge. Knowledge is what is; wisdom is what to do with what is. A scholar knows the map; a wise person knows when to fold it.", "q": "What is the difference between knowing something and being wise about it?", "hadithTr": "Whoever travels a path seeking knowledge, Allah makes easy a path to Paradise", "hadithSrc": "Muslim 2699", "quranSurahs": "Yusuf 12:53 — Ibrahim 14:52", "quranTheme": "Wisdom and revelation — Surah Ar-Ra'd (Thunder) establishes that divine signs are everywhere for those who can see them; Ibrahim closes with the prayer of Ibrahim ﷺ for a community of believers and the recognition that wisdom is always a gift, never a possession.", "quranRef": "Ar-Ra'd 13:28 — 'Verily, in the remembrance of Allah do hearts find rest.'", "quranQuestion": "What is the relationship between knowledge and rest — can you know more and be more troubled, or does genuine knowledge bring stillness?"}, {"w": 14, "tr": "Al-Wadud", "meaning": "The Most Loving", "theme": "Balance & equilibrium", "story": "Al-Wadud is the love that gives without expecting return, that continues regardless of response. Love as a source, not a response to lovability.", "q": "When this week did you give something without expecting return?", "hadithTr": "The giving hand is better than the receiving hand", "hadithSrc": "Bukhari 1429", "quranSurahs": "Al-Hijr 15 — An-Nahl 16:128", "quranTheme": "Divine generosity and ingratitude — An-Nahl (The Bee) catalogs the gifts of Allah in creation — cattle, bees, rivers, ships, the night and day — and contrasts this overwhelming generosity with human forgetfulness and ingratitude.", "quranRef": "An-Nahl 16:18 — 'And if you tried to count the blessings of Allah, you could not enumerate them.'", "quranQuestion": "What have you been given that you have stopped noticing — and what would change if you noticed it again?"}, {"w": 15, "tr": "Al-Qawiyy", "meaning": "The All-Powerful", "theme": "Communication & clarity", "story": "Strength is not overpowering others — the strong person controls themselves when angry. Al-Qawiyy is strength that is also perfect restraint.", "q": "Where this week did you use strength well — and where did strength use you?", "hadithTr": "Strength is controlling yourself when angry", "hadithSrc": "Bukhari 6114", "quranSurahs": "Al-Isra 17 — Al-Kahf 18:74", "quranTheme": "Knowledge and its limits — Al-Isra contains the night journey of the Prophet ﷺ; Al-Kahf presents four stories (the sleepers, the two gardens, Musa and Khidr, Dhul-Qarnayn) each of which demonstrates that human knowledge is partial and that certainty without humility is dangerous.", "quranRef": "Al-Kahf 18:66 — 'Musa said to him: May I follow you so that you may teach me from what you have been taught of sound judgement?'", "quranQuestion": "What would you be willing to follow without understanding, trusting that the meaning would become clear?"}, {"w": 16, "tr": "Al-Waliyy", "meaning": "The Protecting Friend", "theme": "Cycles & repetition", "story": "Al-Waliyy is both guardian and intimate friend — the protector who is also the closest companion.", "q": "Who protected you this week without your asking?", "hadithTr": "Permission is three times", "hadithSrc": "Bukhari 6245", "quranSurahs": "Al-Kahf 18:75 — Ta-Ha 20:135", "quranTheme": "Prophetic perseverance — Maryam, Ibrahim, Musa (in Ta-Ha), and Idris are all presented as models of patience under rejection; Ta-Ha reveals the story of Musa ﷺ as a story of divine preparation: every difficulty was equipping him for the task ahead.", "quranRef": "Ta-Ha 20:1–2 — 'Ta-Ha. We have not sent down the Quran to you to cause you distress.'", "quranQuestion": "What difficulty in your life might be preparing you for something you have not yet been asked to do?"}, {"w": 17, "tr": "Al-Karim", "meaning": "The Most Generous", "theme": "Islamic scholarship", "story": "Al-Karim gives what is not asked, more than is needed, without waiting to be thanked. He gives the breath you will use to praise Him.", "q": "What knowledge did you receive this week from someone who will never know you existed?", "hadithTr": "The most beloved to me are those with the best character", "hadithSrc": "Tirmidhi 2018", "quranSurahs": "Al-Anbiya 21 — Al-Hajj 22:78", "quranTheme": "The Prophets as a single community — Al-Anbiya presents eighteen Prophets in succession, showing that they all shared one message, one trial, and one rescue; Al-Hajj opens with the terror and majesty of the Day of Judgement and closes with the command to strive in the way of Allah as He truly deserves.", "quranRef": "Al-Anbiya 21:92 — 'Indeed this, your religion, is one religion, and I am your Lord, so worship Me.'", "quranQuestion": "What unites all the Prophets — and what does it mean to belong to the same tradition they established?"}, {"w": 18, "tr": "Al-Raqib", "meaning": "The Watchful", "theme": "Precision & accuracy", "story": "Al-Raqib watches not to catch but to witness — every act, every intention, every thought that precedes an act.", "q": "What did you do this week that you would have done differently if you remembered you were being witnessed?", "hadithTr": "The best of people are those most beneficial to people", "hadithSrc": "Al-Mu'jam Al-Awsat", "quranSurahs": "Al-Mu'minun 23 — Al-Furqan 25:20", "quranTheme": "The character of the believer — Al-Mu'minun opens with the famous description of the successful believers: humble in prayer, avoiding vain speech, giving zakat, guarding their chastity, keeping their trusts; the Juz asks what it actually looks like to live as a Muslim in the texture of daily life.", "quranRef": "Al-Mu'minun 23:1–2 — 'Certainly the believers have succeeded — those who are humble in their prayer.'", "quranQuestion": "What would have to change in your daily life for your character to match the description of the muttaqeen in Al-Mu'minun?"}, {"w": 19, "tr": "Al-Wasi", "meaning": "The All-Encompassing", "theme": "Civil War & Reconstruction", "story": "Al-Wasi is spatial and qualitative vastness together — the mercy that can accommodate every situation. Wherever you turn, there is the Face of Allah.", "q": "Where this week did you encounter something larger than your frameworks could contain?", "hadithTr": "The believer is the mirror of the believer", "hadithSrc": "Abu Dawud 4918", "quranSurahs": "Al-Furqan 25:21 — An-Naml 27:55", "quranTheme": "Signs and the people who see them — Ash-Shu'ara presents ten Prophets and their peoples, each time the same pattern; An-Naml (The Ant) includes the stories of Musa, Sulayman, and the hoopoe bird, showing that signs are everywhere in creation for those with eyes that can read them.", "quranRef": "An-Naml 27:40 — 'Said one who had knowledge of the Scripture: I will bring it to you before your glance returns to you.'", "quranQuestion": "What signs in the natural world do you walk past without reading — and what would it take to become someone who notices them?"}, {"w": 20, "tr": "Al-Muqit", "meaning": "The Nourisher", "theme": "Force & motion", "story": "Al-Muqit provides specifically what each thing needs to be itself fully — the precise nourishment for each created nature.", "q": "What did you receive this week that enabled you to do what you were trying to do?", "hadithTr": "Allah loves that when you do a deed, you do it with excellence", "hadithSrc": "Bayhaqi", "quranSurahs": "An-Naml 27:56 — Al-Ankabut 29:45", "quranTheme": "Trust and the test of migration — Al-Qasas covers Musa ﷺ from birth to prophethood; Al-Ankabut (The Spider) opens by stating that believers will necessarily be tested and that those who say 'I believe' without being tested are like a spider's web — the most fragile of structures.", "quranRef": "Al-Ankabut 29:2 — 'Do people think that they will be left alone because they say: We believe — and not be tried?'", "quranQuestion": "What is your faith built on — and what would reveal whether it is a spider's web or a stone foundation?"}, {"w": 21, "tr": "Al-Hasib", "meaning": "The Reckoner", "theme": "Heritage & legacy", "story": "Al-Hasib knows the weight of every atom, the count of every breath. Mathematics is humanity's attempt to participate in divine reckoning.", "q": "What did you count or measure this week that revealed something the looking had missed?", "hadithTr": "Whoever has land should cultivate it", "hadithSrc": "Bukhari 2340", "quranSurahs": "Al-Ankabut 29:46 — Al-Ahzab 33:30", "quranTheme": "Community and the Prophet ﷺ — Ar-Rum (The Romans) opens with a prediction of Byzantine victory as a sign to believers that apparent defeat is never final; Al-Ahzab covers the Battle of the Trench and the role of the Prophet ﷺ as the 'beautiful model' whose character the community is asked to embody.", "quranRef": "Al-Ahzab 33:21 — 'There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day.'", "quranQuestion": "What specific quality of the Prophet ﷺ do you most want to embody — and what would change in you if you did?"}, {"w": 22, "tr": "Al-Muqaddir", "meaning": "The Determiner of measure", "theme": "Transatlantic slave trade", "story": "To decree something is to measure it — to give it exactly the dimensions it will have. Al-Muqaddir's decrees are acts of precise measurement.", "q": "In your work this week: what determined the precise measure that made the system work?", "hadithTr": "No harm shall be inflicted or reciprocated", "hadithSrc": "Ibn Majah 2340", "quranSurahs": "Al-Ahzab 33:31 — Ya-Sin 36:27", "quranTheme": "Revelation and resurrection — Ya-Sin (often called the heart of the Quran) presents the Quran's argument for resurrection through the analogy of dead earth revived by rain; Saba and Fatir establish that divine gratitude is the proper response to divine generosity.", "quranRef": "Ya-Sin 36:77 — 'Does man not consider that We created him from a semen-drop — then at once he is a clear adversary?'", "quranQuestion": "What would change in how you live if you were certain — not just believed — that you will be raised and questioned?"}, {"w": 23, "tr": "Al-Mubdi", "meaning": "The Originator of beginnings", "theme": "Justice & reckoning", "story": "Al-Mubdi begins processes that develop according to their own nature. The first word revealed — Iqra, Read — began something with no precedent.", "q": "What did you begin this week that had no template?", "hadithTr": "No soul will die until it has completed its provision", "hadithSrc": "Ibn Hibban", "quranSurahs": "Ya-Sin 36:28 — Az-Zumar 39:31", "quranTheme": "Sincerity and its opposite — As-Saffat presents the Prophets and the people of Paradise and Hell as a contrast; Az-Zumar (revealed in Makkah) is a sustained call for ikhlas — sincerity — arguing that everything done for display rather than for Allah collapses at the moment of truth.", "quranRef": "Az-Zumar 39:2–3 — 'So worship Allah, sincere to Him in religion. Unquestionably, for Allah is the pure religion.'", "quranQuestion": "What do you do for Allah that you also do for the approval of others — and how would you separate the two?"}, {"w": 24, "tr": "Al-Muid", "meaning": "The Restorer", "theme": "Complexity & emergence", "story": "Nothing is truly lost — it is waiting to be restored. Every time a student rediscovers a forgotten truth, the Restorer is at work.", "q": "What understanding did you rediscover this week — something forgotten, now returned?", "hadithTr": "Righteousness is good character", "hadithSrc": "Muslim 2553", "quranSurahs": "Az-Zumar 39:32 — Fussilat 41:46", "quranTheme": "The Quran as a healing — Ghafir (The Forgiver) and Fussilat present the Quran not merely as a book of law but as a healing: for doubt, for arrogance, for the hardened heart; the Juz repeatedly offers forgiveness to those who turn back, even from the greatest distance.", "quranRef": "Fussilat 41:44 — 'Say: It is for those who believe a guidance and a healing. And those who do not believe — in their ears is a deafness...'", "quranQuestion": "What in you most needs healing right now — and what would it look like to bring that to the Quran?"}, {"w": 25, "tr": "Al-Muhyi", "meaning": "The Giver of life", "theme": "Memory & transmission", "story": "Al-Muhyi gives life not only to bodies but to hearts — through knowledge, through remembrance. A halaqa that revives a dead question is an act of Al-Muhyi.", "q": "What came alive in you this week that had been dormant?", "hadithTr": "Among what continues for a believer after death is knowledge he taught", "hadithSrc": "Ibn Majah 242", "quranSurahs": "Fussilat 41:47 — Al-Jathiyah 45:37", "quranTheme": "Gratitude and accountability — Ash-Shura emphasises consultation and mutual counsel in the community; Az-Zukhruf reminds that every comfort of this world is a test of gratitude; Al-Jathiyah (Crouching) presents the scene of every nation crouching before Allah awaiting their record.", "quranRef": "Az-Zukhruf 43:32 — 'Is it they who apportion the mercy of your Lord? We have apportioned among them their livelihood in worldly life.'", "quranQuestion": "What is your relationship with the comforts you have been given — do they make you grateful, or do they make you forget?"}, {"w": 26, "tr": "Al-Shahid", "meaning": "The Witness", "theme": "Evidence & proof", "story": "Al-Shahid is the ultimate Witness — not one who watches from outside but one whose witnessing is part of the reality of what is witnessed.", "q": "What bore witness to your effort this week — and what would it testify about you?", "hadithTr": "Whoever's Islam is good, everything about him becomes good", "hadithSrc": "Ahmad", "quranSurahs": "Al-Ahqaf 46 — Adh-Dhariyat 51:30", "quranTheme": "The believer's distinction — Al-Fath (Victory) is revealed after Hudaybiyyah, reframing apparent defeat as a divine opening; Al-Hujurat establishes the ethics of community — no mockery, no suspicion, no backbiting; the Juz closes with Ad-Dhariyat's meditation on divine provision for those who trust.", "quranRef": "Al-Fath 48:1 — 'Indeed, We have given you a clear conquest.'", "quranQuestion": "What apparent defeat in your life might be, from a wider view, the beginning of an opening?"}, {"w": 27, "tr": "Al-Haqq", "meaning": "The Truth", "theme": "Reflection & self-knowledge", "story": "Al-Haqq is not merely accurate information but the ground of all accuracy — the reality against which all claims are measured.", "q": "What were you most confident about this week — and how do you know you were right?", "hadithTr": "Perhaps one who carries knowledge conveys it to one more knowledgeable", "hadithSrc": "Tirmidhi 2656", "quranSurahs": "Adh-Dhariyat 51:31 — Al-Hadid 57:29", "quranTheme": "The world and what lies beyond it — At-Tur, An-Najm, Al-Qamar, and Ar-Rahman present creation as testimony: everything points to something beyond itself; Ar-Rahman's recurring refrain 'Which of the favours of your Lord will you deny?' addresses both humans and jinn.", "quranRef": "Ar-Rahman 55:13 — 'So which of the favours of your Lord will you deny?'", "quranQuestion": "If you listed the favours of your Lord that you cannot deny — what would be on the list, and what would be hardest to name?"}, {"w": 28, "tr": "Al-Badi", "meaning": "The Incomparable Originator", "theme": "New beginnings", "story": "Al-Badi does not create from a template — every act of creation is genuinely new. The universe is not a copy of anything. It is the original.", "q": "What did you create this week that did not exist before?", "hadithTr": "Allah created creation, and kinship stood up seeking refuge from severance", "hadithSrc": "Bukhari 5987", "quranSurahs": "Al-Mujadilah 58 — At-Tahrim 66:12", "quranTheme": "Relationships and their obligations — Al-Mujadilah opens with a woman arguing her case before Allah about an unjust divorce formula; Al-Mumtahanah addresses relationships with those outside the faith; Al-Munafiqun confronts hypocrisy in the community; the Juz is intimate, interpersonal, and practical.", "quranRef": "Al-Mujadilah 58:1 — 'Certainly has Allah heard the speech of the one who argues with you about her husband and directs her complaint to Allah.'", "quranQuestion": "What relationship in your life deserves more honesty than it is currently receiving?"}, {"w": 29, "tr": "Al-Sabur", "meaning": "The Patient", "theme": "Completion & approach", "story": "Al-Sabur watches every moment with perfect patience — not because nothing matters, but because everything will arrive at its proper time.", "q": "What did you have to wait for this week — and what did the waiting teach you?", "hadithTr": "O Allah, there is no life but the life of the Hereafter", "hadithSrc": "Bukhari 2834", "quranSurahs": "Al-Mulk 67 — Al-Mursalat 77:50", "quranTheme": "Divine sovereignty and human smallness — Al-Mulk meditates on creation as evidence of Allah's dominion; Al-Qalam (The Pen) is the second revelation, establishing that knowledge, recorded and transmitted, is sacred; Al-Ma'arij, Al-Jinn, Al-Muzzammil, and Al-Muddaththir all address the Prophet ﷺ directly at moments of trial.", "quranRef": "Al-Mulk 67:1 — 'Blessed is He in whose hand is dominion, and He is over all things competent.'", "quranQuestion": "What does it change about how you live when you remember that dominion belongs entirely to someone other than you?"}, {"w": 30, "tr": "Al-Awwal · Al-Akhir", "meaning": "The First and the Last", "theme": "Return & renewal", "story": "First and Last are not positions on a timeline — they are the boundaries within which all of time exists.", "q": "What was the first question you carried this year — and what question do you carry forward?", "hadithTr": "Every son of Adam makes mistakes; the best are those who repent", "hadithSrc": "Tirmidhi 2499", "quranSurahs": "An-Naba 78 — An-Nas 114", "quranTheme": "Return and accountability — Juz 'Amma (the final Juz, the most memorised) is dominated by short Makkan Surahs revealed to a small and persecuted community; they return repeatedly to two themes: the reality of the Day of Judgement and the perfection of Allah's creation as evidence for the truth — the first and last word of the Quran's argument.", "quranRef": "An-Naba 78:1–3 — 'About what are they asking one another? About the great news — that over which they are in disagreement.'", "quranQuestion": "What is the great news — and what would change in you if you truly believed it?"}];
(function(){
  var arabicNames = ["الخَالِق","البَارِئ","المُصَوِّر","الرَزَّاق","العَلِيم","السَّمِيع","البَصِير","المُحِيط","اللَّطِيف","الحَلِيم","العَظِيم","الغَفُور","الحَكِيم","الوَدُود","القَوِيّ","الوَلِيّ","الكَرِيم","الرَقِيب","الوَاسِع","المُقِيت","الحَسِيب","المُقَدِّر","المُبدِئ","المُعِيد","المُحيِي","الشَّهِيد","الحَقّ","البَدِيع","الصَّبُور","الأوَّل الآخِر"];
  JUZ.forEach(function(j,i){ j.arabic = arabicNames[i]; });
})();

var HOW_CURR = {"5": {"1": {"math": "Place value to 1,000,000. Connection to Al-Idrisi map distances.", "sci": "Earth structure and layers. Earth as a system.", "ela": "Al-Idrisi geography and what a scholar description tells us about how they see the world.", "writing": "Descriptive writing: describe a place as if for someone who has never seen it.", "ss": "Who was Al-Idrisi? The Islamic Golden Age.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi drew the whole world from knowledge he collected piece by piece. How do you build a picture of something you cannot see all at once?", "studio": null, "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A map that is incomplete is more useful than a map that is wrong."}, "2": {"math": "Numerical patterns and sequences. Fibonacci through Islamic mathematicians.", "sci": "Plant structures and patterns in nature. Mathematics in biology.", "ela": "Poetry of observation: Islamic poets who wrote about the natural world as signs.", "writing": "Scientific observation journal: describe one natural object in precise mathematical terms.", "ss": "The concept of ayat — signs in Islamic thought.", "scholar": "Al-Biruni", "openingQ": "Al-Biruni found the same patterns in crystals, planets, and languages. Why do you think the same patterns keep appearing?", "studio": null, "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is a language, not a discovery — humans invented it."}, "3": {"math": "Multi-digit multiplication — Egyptian and Islamic methods. Which algorithm is most efficient?", "sci": "Forces and structures — compression and tension in arches and bridges.", "ela": "Argument structure — claim, evidence, reasoning. Ibn Rushd commentary.", "writing": "Write a structured argument for a position you actually hold.", "ss": "The House of Wisdom (Bayt al-Hikmah) — what it was, who worked there.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd said a good argument is like a good building — everything has to support everything else. What does that mean?", "studio": {"name": "Civil and water engineering", "type": "launch", "detail": "Building and testing simple arch models. Why does an arch hold weight without mortar?"}, "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "A strong argument is more powerful than a strong building."}, "4": {"math": "Division with remainders. Fraction as division. Islamic inheritance mathematics.", "sci": "Ecosystems — producers, consumers, decomposers.", "ela": "Primary source: Al-Khwarizmi introduction — why he wrote it, who it was for.", "writing": "Explain a mathematical concept to a younger student using only words and diagrams.", "ss": "Islamic inheritance law — the background to Al-Khwarizmi algebra.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Khwarizmi wrote his algebra book so that ordinary people could solve problems of inheritance and trade. Why did he think mathematics should belong to everyone?", "studio": null, "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Fair distribution is more important than efficient distribution."}, "5": {"math": "Fractions — adding and subtracting with unlike denominators. Al-Uqlidisi decimal fractions (952 CE).", "sci": "Measurement in science — precision, accuracy, and error.", "ela": "Biography: Al-Uqlidisi — why his work on decimal fractions was revolutionary.", "writing": "Science writing: report a measurement with full documentation of method and error sources.", "ss": "The translation movement — Hunayn ibn Ishaq and how knowledge moved across civilisations.", "scholar": "Al-Kashi", "openingQ": "Al-Kashi spent years calculating pi to 16 decimal places. Why would anyone spend years on a calculation that was already good enough?", "studio": {"name": "Algebra atelier", "type": "launch", "detail": "Al-Uqlidisi decimal system. Using base-10 blocks to explore how decimals represent fractions."}, "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "Approximate knowledge is better than no knowledge."}, "6": {"math": "Fraction multiplication — Islamic cross-multiplication. Al-Hassaar approach.", "sci": "Scientific method — when is one experiment enough?", "ela": "Ibn Khaldun on the nature of knowledge — how societies accumulate and lose knowledge.", "writing": "Epistemic autobiography: what do you know, and how do you know it?", "ss": "Primary source analysis: a 9th-century Islamic text. How do historians evaluate sources?", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun said that most history is wrong because historians copy each other without checking. How would you check whether something written a thousand years ago is true?", "studio": null, "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "You cannot trust knowledge you have not verified yourself."}, "7": {"math": "Division of fractions. Why does dividing by a fraction larger than 1 make the result smaller?", "sci": "Ibn al-Haytham method — the first systematic experimental method. The camera obscura.", "ela": "Excerpt from Kitab al-Manazir: how does Ibn al-Haytham structure an argument from observation?", "writing": "Observation-to-argument: three observations, one claim, one written argument.", "ss": "Ibn al-Haytham — his life, his imprisonment, his method.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham spent years in a dark room testing how light worked. What does it take to observe something so carefully that you change what everyone believes?", "studio": {"name": "Observatory and optics", "type": "launch", "detail": "The camera obscura — building a pinhole camera from a shoebox. Why is the image inverted?"}, "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Careful observation is more valuable than clever theory."}, "8": {"math": "Circumference and area of circles. Pi as a ratio. Al-Kashi calculation of pi to 16 decimal places.", "sci": "Circular orbits — Earth orbit. Al-Battani measurement of the solar year.", "ela": "Biography: Al-Battani — what he measured, how, what his measurements corrected.", "writing": "Mathematical narrative: explain the relationship between circumference and diameter.", "ss": "Islamic astronomy and the calendar — why accuracy mattered for prayer times, Ramadan, Hajj.", "scholar": "Al-Battani", "openingQ": "Pi is the same for every circle on Earth, on Mars, and in every galaxy. What does it mean that a number can be true everywhere?", "studio": {"name": "Observatory and optics", "type": "reinforce", "detail": "Measuring circular objects and calculating pi. Comparing methods to Al-Battani approach."}, "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Pi is evidence that the universe was designed by a mathematician."}, "9": {"math": "Rates and ratios — unit rates. Speed as distance per unit time.", "sci": "Ecosystems as systems — inputs, outputs, feedback loops. Homeostasis.", "ela": "Ibn Sina Canon of Medicine — the body as a system, how disease disrupts balance.", "writing": "Systems explanation: choose one system and explain how it maintains balance.", "ss": "Islamic medicine and hospitals — the Bimaristan system. The world first public hospitals.", "scholar": "Ibn Sina", "openingQ": "Ibn Sina described the body as a system where everything connects. What happens to a system when one part stops working?", "studio": {"name": "Pharmacopoeia", "type": "launch", "detail": "Planting chamomile, mint, lavender. Documenting each plant following Al-Razi clinical method."}, "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "A living system cannot be fully understood by studying its parts."}, "10": {"math": "Decimal operations. Al-Kashi decimal arithmetic.", "sci": "Rates of change in nature — population growth, plant growth, temperature change.", "ela": "Al-Biruni on measuring Earth circumference — evaluating his method.", "writing": "Process writing: document a change observed over multiple measurements.", "ss": "Al-Biruni — the most extraordinary scholar of the Islamic Golden Age.", "scholar": "Al-Masudi", "openingQ": "Al-Masudi travelled for 30 years to understand how peoples and landscapes change. What do you think stays constant while everything around it transforms?", "studio": null, "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Change is more fundamental than permanence."}, "11": {"math": "Introduction to variables. The word algebra comes from Al-Khwarizmi title.", "sci": "Scientific naming — taxonomy. Islamic science contribution to naming.", "ela": "Hunayn ibn Ishaq on translation — his method. Translating words vs translating meaning.", "writing": "Explain a concept from mathematics in the language of your family heritage.", "ss": "Hunayn ibn Ishaq — his school of translators, his method.", "scholar": "Hunayn ibn Ishaq", "openingQ": "Hunayn ibn Ishaq said a good translation requires you to understand the idea so completely that you can express it in a different language as if you had thought of it yourself. What do you think is hardest about that?", "studio": null, "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "Translation always loses something essential."}, "12": {"math": "Order of operations. Why do we need rules about which operation to do first?", "sci": "Classification in biology — taxonomy. Ibn Sina contribution.", "ela": "Al-Jahiz Book of Animals — the first systematic Arabic zoology.", "writing": "Classification essay: choose a category and create a system with clear criteria.", "ss": "The Golden Age at its height — 10th-century Islamic world from Cordoba to Samarkand.", "scholar": "Al-Jahiz", "openingQ": "Al-Jahiz wrote that every animal has a place in nature, and when something takes more than its share, the order breaks. What examples can you think of?", "studio": {"name": "Pharmacopoeia", "type": "reinforce", "detail": "Classifying herbs. Clinical documentation entry for chamomile following Al-Razi method."}, "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Natural order exists independent of human understanding."}, "13": {"math": "Introduction to algebra — writing and evaluating expressions. Al-Khwarizmi problem.", "sci": "Evidence-based reasoning in science and Islamic scholarship.", "ela": "Al-Ghazali on knowledge and wisdom — Ihya Ulum al-Din.", "writing": "Philosophical dialogue: two characters debate whether mathematics is discovered or invented.", "ss": "Al-Ghazali — theologian, philosopher, jurist, Sufi. The integration of knowledge and wisdom.", "scholar": "Al-Ghazali", "openingQ": "Al-Ghazali walked away from the most prestigious job in Baghdad to go in search of something more important than being right. What do you think he was looking for?", "studio": null, "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Wisdom cannot be taught — it can only be discovered."}, "14": {"math": "Solving one-step equations. Balance model.", "sci": "Chemical reactions and balance — conservation of mass. Jabir ibn Hayyan and chemistry.", "ela": "Jabir ibn Hayyan — alchemist, chemist, scholar. His laboratory methods.", "writing": "Lab report in the tradition of Jabir: hypothesis, procedure, results, conclusion.", "ss": "Islamic alchemy and the birth of chemistry — who first made chemistry scientific?", "scholar": "Jabir ibn Hayyan", "openingQ": "Jabir ibn Hayyan gave his discoveries away freely — he wrote down his methods so that anyone could use them. What does it mean to give knowledge?", "studio": {"name": "Pharmacopoeia", "type": "reinforce", "detail": "Extraction experiment: water infusion vs oil extraction of chamomile. Concentration calculations."}, "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Perfect balance is possible in human systems."}, "15": {"math": "Introduction to coordinate plane. Al-Biruni use of coordinate systems for mapping.", "sci": "Scientific communication — what makes a scientific paper trustworthy?", "ela": "A difficult scientific text. Reading strategies for dense expository text.", "writing": "Revision workshop: take a previous piece and revise it for clarity.", "ss": "The ijaza system — the Islamic tradition of scholarly certification.", "scholar": "Ibn al-Nafis", "openingQ": "Ibn al-Nafis proved the blood circulates through the lungs — something everyone believed was impossible. How do you convince people of something true when they are certain it is false?", "studio": null, "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Clarity is always more important than precision."}, "16": {"math": "Data analysis — mean, median, mode, range. Al-Biruni use of repeated measurements.", "sci": "Cycles in nature — seasons, lunar phases, tides.", "ela": "Poetry of cycles — poems about the seasons in Arabic and Persian tradition.", "writing": "Data report: collect data over several days. Analyse and report.", "ss": "The Islamic calendar — lunar vs solar, the significance for Islamic practice.", "scholar": "Al-Tusi", "openingQ": "Al-Tusi showed that a straight line can be produced by two circles going around each other. What other things that seem simple turn out to be cycles underneath?", "studio": null, "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "All complex systems are ultimately cyclical."}, "17": {"math": "Introduction to geometry — points, lines, planes, angles. Euclid Elements in the Islamic tradition.", "sci": "Light and optics — how light travels. Ibn al-Haytham theory of vision.", "ela": "Qadi Iyad Shifa Sharif — the Prophet way of sitting with scholars.", "writing": "The scholar letter: a 9th-century scholar reporting a discovery to their teacher.", "ss": "The Shifa Sharif — who Qadi Iyad was, what the Shifa is, why it matters.", "scholar": "Ibn Battuta", "openingQ": "Ibn Battuta received hospitality and knowledge from strangers across 44 countries. He gave his whole life to writing it all down so others could learn from people they would never meet. What does that kind of generosity look like?", "studio": {"name": "Observatory and optics", "type": "capstone", "detail": "Building a working camera obscura. Calculating image size using similar triangles."}, "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The greatest scholars are those who gave away their knowledge freely."}, "18": {"math": "Measurement and precision. Al-Kashi motivation for calculating pi to 16 decimal places.", "sci": "Precision in astronomy — small errors produce large prediction errors over time.", "ela": "A historical account of a navigational error caused by imprecise calculation.", "writing": "Precision analysis: take a calculation and evaluate its precision.", "ss": "Navigation and Islamic scholarship — celestial navigation, the astrolabe, facing Mecca.", "scholar": "Al-Kashi", "openingQ": "Al-Kashi checked his calculations of pi again and again because he knew a small error in astronomy becomes a large error over time. What in your own life gets worse when you are not precise?", "studio": null, "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Precision is more important than speed."}, "19": {"math": "Percentages — what does 13% of a population mean? Reading statistics in historical context.", "sci": "Population ecology — how do populations change?", "ela": "Primary source: Frederick Douglass on literacy, freedom, and power.", "writing": "Argument: was Reconstruction a success or a failure? Use specific evidence.", "ss": "The US Civil War and Reconstruction. The 13th, 14th, 15th Amendments.", "scholar": "Ibn Majid", "openingQ": "Ibn Majid navigated by stars across oceans he had never seen. What does it feel like to commit to a direction when you cannot yet see the destination?", "studio": null, "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Exploration always does more good than harm."}, "20": {"math": "Introduction to proportional relationships. Constant of proportionality and its physical meaning.", "sci": "Newton laws of motion. Force, mass, acceleration. Islamic engineers understanding of mechanical advantage.", "ela": "Al-Jazari Book of Knowledge of Ingenious Mechanical Devices.", "writing": "Technical description: choose one of Al-Jazari devices and explain how it works.", "ss": "Al-Jazari — engineer, inventor, author. How patronage shaped science.", "scholar": "Al-Jazari", "openingQ": "Al-Jazari built a clock powered by water that told not just the time but the movements of the sun and moon. What does it mean to build something that does the thinking for you?", "studio": {"name": "Civil and water engineering", "type": "reinforce", "detail": "Building and testing lever and pulley systems. Calculating mechanical advantage from Al-Jazari specifications."}, "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Tools extend human capability without changing human nature."}, "21": {"math": "Volume of rectangular prisms. Connection to Islamic architecture — calculating materials for domes.", "sci": "Architecture and physics — how do domes stay up?", "ela": "Reading about the Great Mosque of Cordoba — what was built and what it tells us.", "writing": "Heritage essay: choose something from the Islamic Golden Age that you use today.", "ss": "Cordoba at its height — the most sophisticated city in 10th-century Europe.", "scholar": "Ibn Battuta", "openingQ": "Ibn Battuta recorded everything he saw across three continents so that people who would never travel could know the world. What would be lost if he had not written it down?", "studio": {"name": "Algebra atelier", "type": "reinforce", "detail": "Constructing geometric tessellations using compass and straightedge."}, "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The purpose of heritage is to free us from the past, not bind us to it."}, "22": {"math": "Ratios and rates in economic history — how the economics of the slave trade worked.", "sci": "Human biology and the false science of race — what is race, biologically?", "ela": "Primary source: Olaudah Equiano narrative — what a firsthand account of the Middle Passage tells us.", "writing": "Historical synthesis: how can the same civilisation produce both Al-Battani and the slave trade?", "ss": "The Transatlantic slave trade — scope, mechanism, and human cost. Islamic scholarly positions on slavery.", "scholar": "Al-Maqrizi", "openingQ": "Al-Maqrizi studied what happened when rulers debased the currency and the poor suffered first. How do numbers and justice connect?", "studio": null, "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Every injustice has a measurable, documentable cause."}, "23": {"math": "Percentages and financial literacy — profit, loss, and the Islamic prohibition on riba.", "sci": "Environmental consequences — how does economic activity affect ecosystems?", "ela": "Ibn Khaldun on the rise and fall of civilisations — asabiyya.", "writing": "Economic analysis: calculate the cost and profit of a trade. Then ask: is it just?", "ss": "Islamic economics — riba prohibition, zakat as redistribution, the waqf system.", "scholar": "Fatima al-Fihri", "openingQ": "Fatima al-Fihri used her inheritance to build a university when no such thing existed. What do you think she was most afraid of?", "studio": null, "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "Every beginning requires destroying something that came before."}, "24": {"math": "Introduction to statistical thinking — what does a distribution look like?", "sci": "Complex systems — why do flocks of birds move together without a leader?", "ela": "Al-Biruni on complexity — understanding cultures by studying many elements.", "writing": "Systems analysis: explain the simple rules that produce complex behaviour.", "ss": "The decline of the Islamic Golden Age — what happened, why, and what was preserved.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun described how civilisations collapse and then are rebuilt — not the same, but carrying something from what came before. What survives a collapse?", "studio": null, "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "Complex systems cannot be controlled, only understood."}, "25": {"math": "Review and extension: connecting concepts across the year.", "sci": "DNA as information storage — the cell memory. Connecting to Islamic tradition of memorisation.", "ela": "The oral tradition in Islam — how the Quran was memorised before it was written.", "writing": "Year review: a letter to next year Grade 5 class.", "ss": "The Islamic tradition of isnad — chain of transmission.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham's method of experiment was so powerful that it was still being taught 900 years later. How does a way of thinking stay alive across centuries?", "studio": {"name": "Pharmacopoeia", "type": "capstone", "detail": "Complete clinical documentation of three herbs. Present following Al-Razi format."}, "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The best way to learn something is to teach it."}, "26": {"math": "Introduction to formal proof in geometry. Euclid method.", "sci": "Scientific certainty — what scientists mean when they say something is proven.", "ela": "Euclid Elements — first definitions and propositions.", "writing": "Proof paragraph: choose a simple mathematical claim and write a complete proof in words.", "ss": "Greek mathematics in the Islamic world — how Euclid and Archimedes were preserved.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Khwarizmi showed that every algebraic statement can be tested — both sides of the equation must balance. What does it mean for a statement to be a claim that can be checked?", "studio": null, "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "Evidence is always more convincing than argument."}, "27": {"math": "Mathematical connections across the year — fraction, proportion, rate, and ratio as one idea.", "sci": "Scientific process review — what questions remain open?", "ela": "Reflective reading: revisiting the first piece of writing from the year.", "writing": "Year synthesis: the most important thing you understood this year.", "ss": "Year synthesis — what thread runs through the history studied?", "scholar": "Al-Farabi", "openingQ": "Al-Farabi said that logic is the tool for separating what is actually true from what only seems true. How do you know when you have found real truth rather than convincing yourself?", "studio": null, "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Self-knowledge is impossible without knowledge of others."}, "28": {"math": "Preview of Grade 6 mathematics — ratios and proportional relationships.", "sci": "Preview of Grade 6 science — earth systems.", "ela": "Reading: a text that will be studied in Grade 6.", "writing": "Letter forward: write a letter to your Grade 6 self.", "ss": "Preview of Grade 6 history — the ancient world and Islamic origins.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's second great map combined Arab, African, and Greek knowledge into something that had never existed. How do you make something new from things that already exist?", "studio": null, "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Truly new things are rare — most creativity is recombination."}, "29": {"math": "Portfolio reflection — selecting three pieces of mathematical work that show growth.", "sci": "Science portfolio reflection.", "ela": "Literary reflection — what text from this year stayed with you?", "writing": "Final portfolio: assemble your best work with an introduction.", "ss": "Final history reflection.", "scholar": "Al-Biruni", "openingQ": "Al-Biruni spent years learning Sanskrit so he could translate Indian mathematics. Why do some things worth doing take years?", "studio": null, "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "The hardest part of any project is finishing it."}, "30": {"math": "Capstone problem — multi-step connecting five concepts from the year.", "sci": "Capstone observation — a phenomenon connecting three scientific ideas.", "ela": "Year-end reading synthesising the year themes.", "writing": "Year-end reflection: what did you learn about yourself as a learner?", "ss": "Year-end synthesis: create a timeline of the year historical learning.", "scholar": "Al-Battani", "openingQ": "Al-Battani measured the solar year — the time it takes for everything to return to where it began. What returns at the end of a year of learning?", "studio": null, "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The end of one thing is always the beginning of another."}}, "7": {"8": {"math": "Circumference and area of circles. Pi to 16 decimal places — Al-Kashi and Al-Battani's work.", "sci": "Evolution evidence — fossil record, anatomy, and molecular biology.", "ela": "Evolution — reading the story of the Galapagos finches.", "writing": "Comparative essay: how is the story of the Galapagos finches a story about observation?", "ss": "Evolution and human origins — where did Homo sapiens come from?", "scholar": "Al-Battani", "openingQ": "Why is pi the same for every circle everywhere — and what does that tell us about the universe?", "studio": {"name": "Observatory and optics", "type": "reinforce", "detail": "Building the astrolabe. The circle geometry required. Calculating altitude of the sun."}, "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Mathematics is discovered, not invented."}, "11": {"math": "Sampling — can a small group represent a large one? How Ibn Khaldun used populations.", "sci": "Ecology — population dynamics. How do populations grow and stabilise?", "ela": "Ecology — reading about the collapse of the cod fishery in Newfoundland.", "writing": "Case study analysis: what caused the collapse of the Newfoundland cod fishery?", "ss": "Overfishing — a global history of ecological mismanagement.", "scholar": "Hunayn ibn Ishaq", "openingQ": "What is lost and what is gained when knowledge moves from one language to another?", "studio": {"name": "Philosophy and translation", "type": "launch", "detail": "Translation workshop: an original Arabic scientific text alongside its English translation."}, "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "The Islamic translation movement was the single most important event in the history of ideas."}, "14": {"math": "Scale factor — enlarging and reducing figures while maintaining proportion.", "sci": "Chemical reactions in living systems — enzymes and catalysts.", "ela": "Biochemistry — a text about enzymes as locks and keys.", "writing": "Metaphor analysis: is the lock-and-key model of enzymes helpful or misleading?", "ss": "Fermentation — how biochemistry gave us bread, beer, and cheese.", "scholar": "Jabir ibn Hayyan", "openingQ": "When you give something without expecting return — what does that change about the exchange?", "studio": null, "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Chemistry is the most fundamental of the sciences."}, "17": {"math": "Percent problems — percent increase, percent decrease, original amount.", "sci": "Islamic contributions to medicine — Ibn Sina, Ibn al-Nafis, Al-Zahrawi.", "ela": "Islamic medicine — Al-Zahrawi's surgical instruments and their use.", "writing": "Historical analysis: what do Al-Zahrawi's surgical instruments tell us about Islamic medicine?", "ss": "Islamic medicine — Al-Zahrawi, Ibn Sina, Al-Razi.", "scholar": "Ibn Battuta", "openingQ": "What knowledge did you receive this week from someone who will never know you existed?", "studio": {"name": "Observatory and optics", "type": "capstone", "detail": "Building a working camera obscura. Calculating image dimensions using similar triangles."}, "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "Ibn Battuta's Rihla is the most important document of the medieval Islamic world."}, "19": {"math": "Cross-sections of three-dimensional figures. What shapes can be sliced from a cube?", "sci": "Human population growth — exponential growth and its limits.", "ela": "Population ecology — a text about what happened to reindeer on St. Matthew Island.", "writing": "Mathematical modelling essay: explain the reindeer population collapse of St. Matthew Island.", "ss": "Population and resources — Malthus, birth rates, and demographic transition.", "scholar": "Ibn Majid", "openingQ": "Where this week did you encounter something larger than your frameworks could contain?", "studio": null, "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "The Islamic navigational tradition was indispensable to the European Age of Exploration."}, "1": {"math": "Scale drawings and maps — ratios in the real world. Al-Idrisi's scale on the Tabula Rogeriana.", "scholar": "Al-Idrisi", "openingQ": "What does it mean to create something that did not exist before — and how do you know it is true?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "You cannot understand something you have not made yourself.", "sci": "Cell theory — how we know all life is made of cells. Al-Idrisi's systematic observation.", "ela": "Cell theory — reading about the scientists who built it. What did each one contribute?", "writing": "Scientific biography: write a profile of one contributor to cell theory.", "ss": "The cell and civilisation — why biology is a political subject."}, "2": {"math": "Proportional relationships — identifying, representing, comparing.", "scholar": "Al-Biruni", "openingQ": "Why do the same mathematical patterns appear in nature, in music, and in the structure of language?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematical patterns prove that the universe was designed.", "sci": "Cell structure — organelles and their functions. Patterns in cell architecture.", "ela": "DNA — the story of Watson, Crick, Franklin, and what actually happened.", "writing": "Argument: Rosalind Franklin should have shared the Nobel Prize. Argue for or against.", "ss": "DNA and identity — what genetics tells us about human equality."}, "3": {"math": "Multi-step ratio and proportion problems. Solving complex distribution problems.", "scholar": "Ibn Rushd", "openingQ": "What makes a structure strong — in a building, in an argument, in a community?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "The best structures are the simplest ones.", "sci": "Cell processes — diffusion, osmosis, and active transport.", "ela": "Reading a biology textbook passage — what makes this kind of writing different?", "writing": "Textbook analysis: what assumptions are embedded in a biology textbook passage?", "ss": "Cell biology and history — what we learned from disease."}, "4": {"math": "Adding and subtracting integers. Rules and the number line. Fair distribution of positives and negatives.", "scholar": "Al-Khwarizmi", "openingQ": "Is fair always equal — and can mathematics tell the difference?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Mathematics can solve any problem about fairness.", "sci": "Photosynthesis and cellular respiration — energy in and energy out.", "ela": "Photosynthesis as a miracle — a literary text about a leaf in sunlight.", "writing": "Literary science writing: write about photosynthesis as if it were miraculous.", "ss": "Photosynthesis and agriculture — the biological foundation of civilisation."}, "5": {"math": "Multiplying and dividing integers. Why negative × negative = positive.", "scholar": "Al-Kashi", "openingQ": "What is the difference between an approximation and the truth — and does it always matter?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "The search for perfect precision always produces more understanding than stopping at good enough.", "sci": "DNA — the molecule of heredity. How information is stored and copied.", "ela": "The genome — reading about the Human Genome Project and what it found.", "writing": "Research reflection: what did the Human Genome Project fail to predict?", "ss": "The genome and privacy — who owns your DNA?"}, "6": {"math": "Operations with rational numbers — fractions, decimals, and integers together.", "scholar": "Ibn Khaldun", "openingQ": "How do you know when to trust what you read — and what would a world with no reliable knowledge look like?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "A world with no reliable knowledge would be more equal than the world we live in.", "sci": "Genetics — dominant and recessive traits. Ibn Khaldun's observations on inheritance.", "ela": "Genetics — Gregor Mendel's own description of his pea experiments.", "writing": "Primary source analysis: what makes Mendel's paper remarkable for its time?", "ss": "Genetics and race — what biology actually says."}, "7": {"math": "Solving two-step equations. Undoing operations in reverse order.", "scholar": "Ibn al-Haytham", "openingQ": "What is the difference between seeing and observing — and why does the difference matter?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "The scientific method is the only reliable path to truth.", "sci": "Natural selection — variation, selection, and adaptation over generations.", "ela": "Darwin on natural selection — an adapted excerpt from On the Origin of Species.", "writing": "Close reading: analyse Darwin's argument structure in your excerpt.", "ss": "Darwin and Islam — how Muslims have responded to evolutionary theory."}, "9": {"math": "Introduction to probability — theoretical vs experimental probability.", "scholar": "Ibn Sina", "openingQ": "What makes a living system different from a very complicated machine?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "Life is irreducibly different from chemistry.", "sci": "Body systems — how do the circulatory, respiratory, and digestive systems work together?", "ela": "Ibn Sina and the body — the Canon of Medicine on how systems interact.", "writing": "Comparative analysis: compare Ibn Sina's model of the body to modern systems biology.", "ss": "Ibn Sina's Canon of Medicine — the history of the most influential medical book."}, "10": {"math": "Compound events — probability of two things both happening.", "scholar": "Al-Masudi", "openingQ": "How do you measure change — and what stays constant while everything else transforms?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Everything in the universe is either changing or decaying — nothing is stable.", "sci": "The immune system — how the body identifies and destroys pathogens.", "ela": "The immune system — reading about how vaccines work.", "writing": "Argument: should vaccines be mandatory? Use biological evidence.", "ss": "Vaccines and public health — the history of immunisation."}, "12": {"math": "Introduction to geometry — angles in parallel lines and transversals.", "scholar": "Al-Jahiz", "openingQ": "What is the natural order of things — and what happens when that order is disturbed?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Human beings are part of nature's order, not separate from it.", "sci": "Food webs and energy pyramids — why does feeding at a higher level require more land?", "ela": "Food web collapse — reading about what happened to the Aral Sea.", "writing": "Environmental argument: who is responsible for the destruction of the Aral Sea?", "ss": "The Aral Sea — the worst man-made environmental disaster in history."}, "13": {"math": "Triangle properties — angle sum, triangle inequality. Why do all triangles have 180°?", "scholar": "Al-Ghazali", "openingQ": "What is the difference between knowing something and being wise about it?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Knowledge without wisdom is more dangerous than ignorance.", "sci": "Scientific argument — evaluating claims about health and medicine. Ibn Sina's approach.", "ela": "Ibn al-Nafis on the lungs — his original claim, translated.", "writing": "Primary source analysis: what is Ibn al-Nafis proving, and how?", "ss": "Ibn al-Nafis — the discovery that proved Galen wrong."}, "15": {"math": "Introduction to surface area of three-dimensional figures.", "scholar": "Ibn al-Nafis", "openingQ": "How do you communicate something you know is true when everyone around you believes something different?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "It is a scientist's duty to communicate their findings to anyone who might be affected by them.", "sci": "Communicating science — reading a scientific abstract and identifying claims.", "ela": "Reading a scientific paper abstract — identifying claim, evidence, and significance.", "writing": "Research paper evaluation: identify the claim, evidence, and significance.", "ss": "Scientific journals — who gets to publish and who gets to read?"}, "16": {"math": "Volume of prisms and cylinders.", "scholar": "Al-Tusi", "openingQ": "What cycles do you depend on that you never notice — and what would happen if they stopped?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Cycles in nature are more fundamental than straight-line change.", "sci": "Cycles in ecosystems — carbon, nitrogen, and water as cycles.", "ela": "The nitrogen cycle — reading about how nitrogen moves through all living systems.", "writing": "Ecological essay: explain the nitrogen cycle and its disruption by humans.", "ss": "The nitrogen cycle and the Green Revolution — benefits and consequences."}, "18": {"math": "Using percent — tax, tip, discount, simple interest. Al-Kashi's computational precision.", "scholar": "Al-Kashi", "openingQ": "What did you do this week that you would have done differently if you had been fully paying attention?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "The culture of precision in Islamic scholarship was the most important factor in its success.", "sci": "Experimental precision in biology — why sample size matters.", "ela": "Sample size — a text about why the Pepsi Challenge experiment was flawed.", "writing": "Statistical argument: what was wrong with the Pepsi Challenge experiment?", "ss": "Sample size and democracy — how surveys shape elections."}, "20": {"math": "Introduction to slope — rise over run. What does the steepness of a line represent?", "scholar": "Al-Jazari", "openingQ": "What did you receive this week that enabled you to do what you were trying to do?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Al-Jazari's Book of Mechanical Devices was the most important engineering text before the Industrial Revolution.", "sci": "Forces in biological systems — muscles, levers, and the skeleton.", "ela": "Reading about the skeleton as a lever system — mechanics in the human body.", "writing": "Biomechanics essay: the human arm as a lever — third class, advantage and disadvantage.", "ss": "Biomechanics and sport — how biology enables human performance."}, "21": {"math": "Proportional relationships vs non-proportional. How do you tell them apart?", "scholar": "Ibn Battuta", "openingQ": "What did you count or measure this week that revealed something the looking alone had missed?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "What we choose to preserve reveals more about us than what we choose to create.", "sci": "Earth's biodiversity — how many species exist and what threatens them?", "ela": "The sixth mass extinction — reading about what we are losing.", "writing": "Conservation argument: how do we decide which species to save when we cannot save all?", "ss": "The sixth mass extinction — a history of what humans have already eliminated."}, "22": {"math": "Solving inequalities — when the answer is a range of values.", "scholar": "Al-Maqrizi", "openingQ": "In your work this week — what determined the precise measure that made the system work?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Economic inequality always produces moral inequality.", "sci": "Human health and environment — what environmental factors affect health?", "ela": "Health and environment — a text about lead in drinking water in Flint, Michigan.", "writing": "Investigative writing: what happened in Flint, Michigan and who was responsible?", "ss": "Flint, Michigan — environmental justice and the politics of water."}, "23": {"math": "Introduction to statistics — analysing two data sets and comparing distributions.", "scholar": "Fatima al-Fihri", "openingQ": "What did you begin this week that had no template?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "Fatima al-Fihri should be recognised as the most important figure in the history of education.", "sci": "Reproduction and development — from cell division to organism.", "ela": "Reproduction — reading about why sexual reproduction increases variation.", "writing": "Evolutionary argument: why does sexual reproduction increase variation?", "ss": "Sexual reproduction and genetic diversity — why variation matters."}, "24": {"math": "Graphing proportional and non-proportional relationships.", "scholar": "Ibn Khaldun", "openingQ": "What understanding did you rediscover this week — something forgotten that came back?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "Ibn Khaldun's theory of civilisational cycles is the best explanation of human history ever written.", "sci": "Ecosystems under stress — what happens when temperature rises 2°C?", "ela": "Climate and ecosystems — reading about coral bleaching.", "writing": "Climate essay: explain coral bleaching — cause, mechanism, consequence.", "ss": "Coral reefs and climate — what we are losing and why."}, "25": {"math": "Reviewing algebra — equations, inequalities, and graphing.", "scholar": "Ibn al-Haytham", "openingQ": "What came alive in you this week that had been dormant?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "Memory is more important than understanding in the transmission of knowledge.", "sci": "Reviewing genetics — connecting DNA, genes, traits, and inheritance.", "ela": "DNA evidence for evolution — a text about how molecular biology confirmed Darwin.", "writing": "Synthesis essay: how does molecular biology confirm Darwin's theory?", "ss": "Molecular evidence for evolution — how genetics confirmed Darwin."}, "26": {"math": "Geometric constructions — using compass and straightedge as formal proof tools.", "scholar": "Al-Khwarizmi", "openingQ": "What bore witness to your effort this week — and what would it testify about you?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "Mathematical proof is the only form of proof that produces certainty.", "sci": "Evidence in biology — how do we know evolution happened?", "ela": "How scientists changed their minds — the story of H. pylori and stomach ulcers.", "writing": "Scientific history: how did Barry Marshall prove that ulcers were caused by bacteria?", "ss": "H. pylori — the story of a discovery that changed medicine and medicine's culture."}, "27": {"math": "Connecting proportional reasoning across all contexts studied this year.", "scholar": "Al-Farabi", "openingQ": "What were you most confident about this week — and how do you know you were right?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "The examined life — knowing yourself — is more valuable than any external knowledge.", "sci": "Open questions in biology — what scientists are currently investigating.", "ela": "The unanswered questions in biology — what scientists are currently working on.", "writing": "Research proposal: write a question you would like biology to answer.", "ss": "Open questions in biology — the frontier of life science."}, "28": {"math": "Introduction to Grade 8 — functions and transformations.", "scholar": "Al-Idrisi", "openingQ": "What did you create this week that did not exist before?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Human creativity can produce something genuinely new — not just recombination.", "sci": "Preview of Grade 8 — physical science and chemistry.", "ela": "Preview of Grade 8 physical science.", "writing": "Preview essay: what is the difference between biology and chemistry?", "ss": "Preview of Grade 8 physical science."}, "29": {"math": "Extended capstone investigation — a real-world proportional modelling problem.", "scholar": "Al-Biruni", "openingQ": "What did you have to wait for this week — and what did the waiting teach you?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Patience is the most undervalued intellectual virtue.", "sci": "Extended biology investigation — results presented and peer reviewed.", "ela": "Reading a peer-reviewed article — what makes it different from other kinds of writing?", "writing": "Peer review: evaluate a partner's research paper for clarity and evidence.", "ss": "Scientific publication — the peer review system and its weaknesses."}, "30": {"math": "Capstone: using proportional reasoning, algebra, and geometry together.", "scholar": "Al-Battani", "openingQ": "What was the first question you carried into this year — and what question do you carry forward?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "A year of learning that raises more questions than it answers has failed.", "sci": "Capstone: a biological investigation connecting cells, genetics, and ecology.", "ela": "A synthesis text — connecting cells, genetics, evolution, and ecology.", "writing": "Capstone essay: connect cells, genetics, evolution, and ecology in one argument.", "ss": "Biology and civilisation — how the life sciences shape human history."}}, "11": {"7": {"math": "Properties of logarithms — product, quotient, power rules. Al-Kashi's computation shortcuts.", "sci": "Simple harmonic motion — pendulums, springs, and oscillation. Ibn al-Haytham's study of pendulums.", "ela": "Simple harmonic motion — reading about how a pendulum keeps time.", "writing": "History essay: why did the pendulum clock transform European civilisation?", "ss": "The pendulum and time — how a swinging weight changed European history.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham said: do not trust any result until you have tested it yourself. What would it cost you to apply that principle to everything you believe?", "studio": null, "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Ibn al-Haytham's experimental method is the most important intellectual invention in human history."}, "8": {"math": "Circular functions — radian measure, unit circle. Al-Battani's contributions to circular trigonometry.", "sci": "Circular motion and centripetal acceleration. Al-Battani's orbital calculations.", "ela": "Al-Battani and circular motion — reading about his trigonometric approach to orbits.", "writing": "Comparative analysis: Al-Battani and Newton on circular motion — compare their approaches.", "ss": "Islamic astronomy and circular motion — Al-Battani's contribution.", "scholar": "Al-Battani", "openingQ": "Al-Battani used circles to map the heavens. Al-Muhit surrounds all existence. Is the circle a mathematical fact, a physical reality, or a spiritual symbol — or all three at once?", "studio": null, "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "The unreasonable effectiveness of mathematics in describing the physical world requires explanation."}, "13": {"math": "Solving trigonometric equations — Al-Ghazali's approach to wisdom: systematic elimination.", "sci": "Electromagnetic induction — Faraday's law and generators.", "ela": "Electromagnetic induction — reading Faraday's diary entry the day he discovered it.", "writing": "Primary source analysis: close reading of Faraday's diary entry on electromagnetic induction.", "ss": "Electromagnetic induction — how Faraday created the modern world.", "scholar": "Al-Ghazali", "openingQ": "Al-Hakim is the all-wise. Al-Ghazali argued that Islamic scholars had confused knowledge with wisdom. What is the difference, and can a person have one without the other?", "studio": null, "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Al-Ghazali's critique of philosophy was itself philosophical — therefore his critique failed."}, "17": {"math": "Introduction to derivatives — the rate of change at a point.", "sci": "Special relativity — time dilation, length contraction, E = mc².", "ela": "Special relativity — reading Einstein's 1905 paper, the introduction.", "writing": "Primary source analysis: close reading of Einstein's 1905 introduction to special relativity.", "ss": "Einstein and the 20th century — what relativity changed.", "scholar": "Ibn Battuta", "openingQ": "Al-Karim gives before being asked. The Islamic scholarly tradition flows through isnad chains — named people giving named people what was given to them. What do you owe to people you have never met?", "studio": null, "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The Islamic scholarly tradition was more advanced than European scholarship in every field until at least 1400 CE."}, "1": {"math": "Functions revisited — composition, inverses, transformations. Al-Idrisi's map projections as function transformations.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's map was wrong in places and still the most accurate of its time. When is a flawed creation better than no creation?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A flawed creation that exists is worth more than a perfect creation that does not.", "sci": "Classical mechanics revisited — kinematics and the mathematics of motion.", "ela": "Newton's Principia — the opening definitions. What is mass? What is force?", "writing": "Primary source analysis: close reading of Newton's first definitions.", "ss": "Classical mechanics and the industrial world."}, "2": {"math": "Polynomial functions — graphs, end behaviour, zeros, and multiplicities.", "scholar": "Al-Biruni", "openingQ": "Is a pattern a property of the world, or a property of the mind that perceives it?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is discovered, not invented — its truths exist independent of human minds.", "sci": "Forces and Newton's laws at depth — friction, tension, and normal force.", "ela": "Reading about the history of classical mechanics — from Aristotle's error to Newton's correction.", "writing": "History of ideas: how did Aristotle's physics survive 2000 years before Newton corrected it?", "ss": "From Aristotle to Newton — two thousand years of being wrong."}, "3": {"math": "Polynomial long division and synthetic division. Structural foundations.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd believed reason and revelation share a foundation. What holds your own beliefs together?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "Reason and revelation cannot contradict each other — when they appear to, one of them is wrong.", "sci": "Work, energy, and power — conservation of energy in mechanical systems.", "ela": "Conservation laws — reading Noether's theorem and why symmetry implies conservation.", "writing": "Philosophy of physics: what is Noether's theorem and why is it profound?", "ss": "Symmetry and conservation — the deepest principle in physics."}, "4": {"math": "Rational functions — domain, asymptotes, holes. Al-Khwarizmi's algebraic fractions.", "scholar": "Al-Khwarizmi", "openingQ": "Islamic inheritance law gives daughters half what sons receive. Al-Khwarizmi built algebra to calculate it precisely. What does precision in an unjust system produce?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Precision in an unjust system makes the injustice worse, not better.", "sci": "Momentum and collisions — conservation of momentum. Al-Khwarizmi's principle of conservation.", "ela": "Momentum — reading about the physics of car crashes.", "writing": "Applied physics essay: explain the physics of a car crash.", "ss": "Crash physics — how physics saves lives in car design."}, "5": {"math": "Exponential functions — properties, graphing, transformations. Al-Kashi's computations with powers.", "scholar": "Al-Kashi", "openingQ": "All scientific measurement contains error. Does that mean science only produces approximations, never truth?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "All scientific measurement is approximation — therefore science never achieves truth, only usefulness.", "sci": "Rotational motion — torque, angular velocity, and moment of inertia.", "ela": "Angular momentum — reading about why a spinning gyroscope does not fall.", "writing": "Conceptual essay: why does a spinning gyroscope not fall?", "ss": "Gyroscopes and navigation — from ships to spacecraft."}, "6": {"math": "Logarithmic functions — inverses of exponentials. The scale of very large and very small.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun invented the scientific study of history. What assumptions do you have to make before you can trust any source at all?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "All historical sources are biased — therefore historical truth is impossible.", "sci": "Gravitational field — Newton's law of gravitation and orbital mechanics.", "ela": "Gravitational waves — reading about LIGO and the first detection.", "writing": "Science journalism: write a newspaper article about gravitational wave detection.", "ss": "Gravitational waves — the greatest scientific achievement of the 21st century so far."}, "9": {"math": "Trigonometric functions — sine, cosine, tangent as functions of real numbers.", "scholar": "Ibn Sina", "openingQ": "Al-Latif is the subtly kind — care that arrives before it is asked for. Is there a parallel between divine providence and the self-regulating systems of living organisms?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "There is no fundamental difference between a living organism and a very complicated machine.", "sci": "Fluid mechanics — pressure, buoyancy, and Bernoulli's equation.", "ela": "Fluid mechanics — reading about how planes fly. Is it Bernoulli or Newton?", "writing": "Debate essay: is the Bernoulli or the Newton explanation of flight more accurate?", "ss": "The physics of flight — how something heavier than air stays up."}, "10": {"math": "Graphs of trigonometric functions — period, amplitude, phase shift.", "scholar": "Al-Masudi", "openingQ": "Al-Halim is the forbearing — unchanged by provocation. In a world where everything changes, what is the value of constancy?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Al-Halim's forbearance in the face of change is the highest possible response to existence.", "sci": "Thermal physics — ideal gas laws and kinetic theory.", "ela": "Ideal gas law — reading about what a mole of gas actually looks like.", "writing": "Conceptual essay: explain the ideal gas law using molecular kinetic theory.", "ss": "The steam engine and industrial civilisation."}, "11": {"math": "Trigonometric identities — Pythagorean, sum and difference formulas.", "scholar": "Hunayn ibn Ishaq", "openingQ": "The Quran is untranslatable — its meaning depends on its Arabic. Hunayn translated Greek science into Arabic and saved it. What is the relationship between language and truth?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "A translation that changes the meaning to be truer to the target language is more faithful than one that preserves the words.", "sci": "Thermodynamics — the four laws and entropy as a measure of disorder.", "ela": "Entropy — reading Feynman on why time has a direction.", "writing": "Philosophy of physics: why does entropy give time a direction?", "ss": "Entropy and the arrow of time."}, "12": {"math": "Inverse trigonometric functions — when does sin(x) = 0.5?", "scholar": "Al-Jahiz", "openingQ": "Al-Ghafur covers and conceals wrongdoing. In ecology, a disturbed system tries to restore equilibrium. Is the desire for order a property of nature, or of mind?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Al-Jahiz's proto-evolutionary ideas were more advanced than the Islamic scholarly tradition gave him credit for.", "sci": "Wave mechanics — superposition, interference, and standing waves.", "ela": "Wave interference — reading about double-slit experiment and what it proved.", "writing": "Conceptual essay: what does the double-slit experiment prove about the nature of light?", "ss": "The double-slit experiment — the most profound result in physics."}, "14": {"math": "Introduction to sequences and series — arithmetic and geometric. Convergence and divergence.", "scholar": "Jabir ibn Hayyan", "openingQ": "Al-Wadud is love that gives without requiring lovability in return. Jabir built chemistry on sharing method. Is generosity in knowledge the same as generosity in love?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Jabir ibn Hayyan's systematic experimentation made him the true founder of modern science — not Galileo or Newton.", "sci": "Maxwell's equations — the unification of electricity, magnetism, and light.", "ela": "Maxwell's equations — reading about the greatest theoretical achievement of the 19th century.", "writing": "History of science: why did Maxwell's equations represent the greatest theoretical achievement of the 19th century?", "ss": "Maxwell's equations and the unification of physics."}, "15": {"math": "Sigma notation and summation formulas.", "scholar": "Ibn al-Nafis", "openingQ": "Al-Qawiyy is strength — but the Prophet ﷺ said the strongest person is not the one who wins fights but the one who controls themselves when angry. What is the strongest form of communication?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Ibn al-Nafis was morally obliged to publish his discovery of pulmonary circulation even at the risk of his life.", "sci": "Optics — refraction, lenses, and optical instruments. Ibn al-Haytham's full legacy.", "ela": "Ibn al-Haytham's optics and Newton's optics — reading both accounts of light.", "writing": "Comparative analysis: how did Ibn al-Haytham and Newton each understand light?", "ss": "Optics from Ibn al-Haytham to lasers."}, "16": {"math": "Introduction to limits — what does a function approach?", "scholar": "Al-Tusi", "openingQ": "Al-Waliyy is the protecting friend — the guardian who sustains cycles of care invisibly. Is it possible to understand a system from the inside, while you are sustained by it?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Al-Tusi's mathematical model was more important than Copernicus's heliocentric theory.", "sci": "Modern physics introduction — the failure of classical mechanics.", "ela": "The Michelson-Morley experiment — reading about the failure that led to relativity.", "writing": "Scientific history: why did the Michelson-Morley experiment matter?", "ss": "The Michelson-Morley experiment and the end of the ether."}, "18": {"math": "Derivatives of polynomial functions. Al-Kashi's iterative methods anticipate numerical differentiation.", "scholar": "Al-Kashi", "openingQ": "Al-Raqib watches every act and every intention. Precision is a form of attention. What is the relationship between being watched and doing careful work?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Al-Kashi's contributions to mathematics were as significant as Al-Khwarizmi's, and the neglect of his legacy is itself a form of injustice.", "sci": "Quantum mechanics — wave-particle duality and the uncertainty principle.", "ela": "Quantum mechanics — reading Heisenberg's uncertainty principle, adapted.", "writing": "Conceptual essay: explain the uncertainty principle to someone who finds it absurd.", "ss": "Quantum mechanics and the philosophy of knowledge."}, "19": {"math": "Applications of derivatives — velocity, acceleration, optimisation.", "scholar": "Ibn Majid", "openingQ": "Al-Wasi is spacious beyond all measure. Every expanding understanding requires letting go of the frame that used to contain it. What do you have to give up in order to understand something genuinely new?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Ibn Majid's guidance of Vasco da Gama was an act that damaged the Islamic world more than any Mongol invasion.", "sci": "Nuclear physics — binding energy and nuclear reactions.", "ela": "Nuclear physics — reading about the Trinity test and what the scientists felt.", "writing": "Ethics essay: should scientists who built the atomic bomb bear moral responsibility for its use?", "ss": "The Manhattan Project — science, war, and responsibility."}, "20": {"math": "Introduction to integrals — area under a curve as accumulated change.", "scholar": "Al-Jazari", "openingQ": "Al-Muqit provides the precise nourishment each thing needs to be itself fully. Is a tool that extends your capability also extending your nature — or replacing part of it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "A machine that automates a decision is fundamentally different from a machine that automates a physical task.", "sci": "Particle physics — the Standard Model and fundamental forces.", "ela": "The Standard Model — reading a description of the particle zoo.", "writing": "Explanatory essay: explain the Standard Model to an intelligent non-physicist.", "ss": "The Standard Model — the deepest description of matter we have."}, "21": {"math": "Introduction to matrices — representing systems of equations as matrices.", "scholar": "Ibn Battuta", "openingQ": "Al-Hasib is the reckoner — every atom accounted for. Heritage is what we choose to count. What gets lost from history when we do not measure it carefully?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The destruction of the Abbasid library by the Mongols was the single greatest loss in intellectual history.", "sci": "Astrophysics — the lifecycle of stars and nucleosynthesis.", "ela": "Stellar nucleosynthesis — reading about how carbon was made inside a star.", "writing": "Astronomy essay: how was carbon made inside a star?", "ss": "Stellar nucleosynthesis — we are stardust."}, "22": {"math": "Matrix operations and the determinant.", "scholar": "Al-Maqrizi", "openingQ": "Al-Muqaddir decrees exact measures. Al-Maqrizi documented exact economic injustice. Is measurement in the service of justice the same as measurement in the service of efficiency?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Al-Maqrizi's economic analysis of the Mamluk crisis is more important to read today than any modern economics textbook.", "sci": "Cosmology — the Big Bang, expansion of the universe, and dark energy.", "ela": "The Big Bang — reading about the cosmic microwave background and what it proves.", "writing": "Cosmology essay: what does the cosmic microwave background prove?", "ss": "The Big Bang and cosmology — how we know how the universe began."}, "23": {"math": "Introduction to probability — counting principles, permutations, combinations.", "scholar": "Fatima al-Fihri", "openingQ": "Al-Mubdi originates without model or precedent. Fatima al-Fihri began al-Qarawiyyin — the oldest continuously operating university — 1200 years ago. What does it take to create an institution rather than just a building?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "The university system — which began at al-Qarawiyyin — has done more harm than good to human knowledge.", "sci": "Physics of climate — greenhouse effect as a radiation physics problem.", "ela": "Climate physics — reading about the greenhouse effect as an infrared radiation problem.", "writing": "Climate physics essay: explain the greenhouse effect as an infrared radiation physics problem.", "ss": "Climate physics — the physics that drives climate change."}, "24": {"math": "Binomial theorem and Pascal's triangle. The mathematics of expansion.", "scholar": "Ibn Khaldun", "openingQ": "Al-Muid is the restorer — nothing truly lost, only waiting to be brought back. Is restoration the same as creation, or something different?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "The Islamic Golden Age ended because its social complexity exceeded its institutional capacity — and the same is true of every fallen civilisation.", "sci": "Complex systems in physics — turbulence, chaos, and emergence.", "ela": "Chaos theory — reading Lorenz on the butterfly effect.", "writing": "Complexity essay: explain the butterfly effect and its implications for prediction.", "ss": "Chaos and complexity — the limits of prediction."}, "25": {"math": "Statistics — normal distribution and z-scores.", "scholar": "Ibn al-Haytham", "openingQ": "Al-Muhyi gives life not only to bodies but to hearts — through knowledge, through remembrance. What is the difference between information and living knowledge?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The Islamic tradition of oral transmission — memorisation before understanding — produced better scholars than the modern tradition of written analysis.", "sci": "Reviewing classical mechanics — from kinematics to thermodynamics.", "ela": "Review — the physics concept that most changed how you see the world.", "writing": "Year synthesis: the physics concept that most changed how you see the world.", "ss": "Review — the physics that most changed your understanding of reality."}, "26": {"math": "Hypothesis testing and confidence intervals — evidence and proof in statistics.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Shahid witnesses not from outside but from within the reality of what is witnessed. What is the difference between evidence and witness?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "The standard of evidence in Islamic jurisprudence is stricter than the standard of evidence in modern science.", "sci": "Evidence for special relativity — experimental confirmation.", "ela": "Evidence for special relativity — reading about the muon experiment.", "writing": "Scientific argument: the evidence for special relativity is overwhelming. Construct the case.", "ss": "Special relativity — the experimental evidence."}, "27": {"math": "Connecting all functions — polynomial, exponential, trigonometric, and logarithmic.", "scholar": "Al-Farabi", "openingQ": "Al-Haqq is not merely accurate but the ground of all accuracy. Al-Farabi built logic as a ladder toward truth. At what point does the ladder become unnecessary?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Al-Farabi's classification of the sciences is more useful as a map of knowledge than any modern academic curriculum.", "sci": "Open questions in physics — dark matter, quantum gravity, and the unified theory.", "ela": "Open questions — reading about dark matter, dark energy, and quantum gravity.", "writing": "Research proposal: write a full physics research proposal.", "ss": "The future of physics — what we do not yet know."}, "28": {"math": "Introduction to calculus concepts — limits, derivatives, and the fundamental theorem.", "scholar": "Al-Idrisi", "openingQ": "Al-Badi creates without precedent — the universe is not a copy of anything. Is human creativity ever genuinely original, or always recombination?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Al-Idrisi's cartography was the last moment of genuinely original Islamic geographic thinking — everything after was commentary.", "sci": "Preview of Grade 12 — environmental and applied science.", "ela": "Preview of Grade 12 environmental science.", "writing": "Preview essay: what is environmental science and why does it require physics?", "ss": "Preview of Grade 12 environmental science."}, "29": {"math": "Extended investigation — modelling a real phenomenon with a trigonometric or exponential function.", "scholar": "Al-Biruni", "openingQ": "Al-Sabur is patient not because nothing matters, but because everything will arrive at its proper time. What is the difference between patience and passivity?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Al-Biruni's patient, lifelong accumulation of knowledge was a more valuable contribution to human understanding than any single discovery.", "sci": "Extended physics investigation — experimental design, data, and uncertainty analysis.", "ela": "Reading a physics paper — what does the uncertainty section tell you?", "writing": "Uncertainty analysis: evaluate the error analysis in a physics paper.", "ss": "Physics and society — how physics shapes the modern world."}, "30": {"math": "Capstone: connecting functions, rates of change, and accumulated change.", "scholar": "Al-Battani", "openingQ": "Al-Awwal and Al-Akhir — the first and the last, the boundaries within which all time exists. What question about existence do you carry that no year of learning will fully answer?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The question you cannot answer is more valuable than all the questions you can.", "sci": "Capstone: a physics investigation connecting mechanics, waves, and modern physics.", "ela": "Capstone — a text connecting classical mechanics, thermodynamics, and quantum physics.", "writing": "Capstone essay: connect classical mechanics, thermodynamics, and quantum physics.", "ss": "Physics and the human condition — what the universe tells us about ourselves."}}, "0": {"1": {"math": "Counting objects 1–10. Counting is the first act of knowing a thing — Al-Idrisi counted every route.", "scholar": "Al-Idrisi", "openingQ": "When you make something — a drawing, a tower, a story — where did it come from?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "Making a mess is the beginning of making something good.", "sci": "Observing the world around us — using our five senses to notice what is there.", "ela": "Listening to a story about maps and journeys. What did the traveller see?", "writing": "Drawing a picture of somewhere you have been and labelling what you see.", "ss": "Who made maps first? People have always needed to know where they are."}, "2": {"math": "Sorting and classifying objects by shape, color, size. Finding what belongs together.", "scholar": "Al-Biruni", "openingQ": "What is a pattern? Can you find one in the classroom right now?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Patterns in nature are more beautiful than patterns people make.", "sci": "Sorting living and non-living things. What makes something alive?", "ela": "Finding patterns in picture books — what repeats? What changes?", "writing": "Drawing and labelling a pattern you find in the classroom.", "ss": "Signs everywhere — people across history have noticed patterns in the world."}, "3": {"math": "Comparing groups: more, fewer, the same. Using one-to-one correspondence.", "scholar": "Ibn Rushd", "openingQ": "What makes something strong enough not to fall down?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "The tallest tower is always the best tower.", "sci": "Pushes and pulls — things move when a force acts on them.", "ela": "Listening to a story about building something. What did they make?", "writing": "Drawing the tallest structure you can build and writing its name.", "ss": "Building together — how communities make things that no one person could make alone."}, "4": {"math": "Sharing equally — splitting a group of objects between two people fairly.", "scholar": "Al-Khwarizmi", "openingQ": "If you had eight dates and three friends, how would you share them so it feels fair?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Sharing equally is always the fairest way to share.", "sci": "Where do plants and animals get food? Sunlight, soil, water, and other animals.", "ela": "A story about sharing fairly. Was it fair? How do you know?", "writing": "Drawing a picture of sharing something with a friend.", "ss": "Sharing food — how families and communities make sure everyone has enough."}, "5": {"math": "Counting to 20. Understanding that the order of counting always stays the same.", "scholar": "Al-Kashi", "openingQ": "What is the difference between nearly right and exactly right? Does it always matter?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "Close enough is good enough.", "sci": "Measuring with our senses — hot/cold, heavy/light, rough/smooth.", "ela": "Learning new words for size — big, bigger, biggest. Tall, taller, tallest.", "writing": "Writing the numbers 1 to 10 in order, as carefully as you can.", "ss": "Counting and measuring — people have always needed to know how much."}, "6": {"math": "Addition as joining groups. How many altogether?", "scholar": "Ibn Khaldun", "openingQ": "How do you know when someone is telling the truth?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "You should only believe what you have seen yourself.", "sci": "Asking questions — what is a question, and how do scientists try to answer?", "ela": "Asking questions about a book. What do you want to know?", "writing": "Drawing and writing one question you have about something you do not understand.", "ss": "Asking questions — curiosity is what drives discovery."}, "7": {"math": "Subtraction as taking away. How many are left?", "scholar": "Ibn al-Haytham", "openingQ": "What is the difference between looking at something and really seeing it?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Seeing is believing.", "sci": "Using our eyes to observe carefully — looking for details others miss.", "ela": "Describing what you see in a picture — using careful words.", "writing": "Drawing what you see when you look out the window — as many details as you can.", "ss": "Looking carefully — scientists and artists both pay close attention."}, "8": {"math": "Shapes — circles, squares, triangles, rectangles. Al-Battani watched circular paths of stars.", "scholar": "Al-Battani", "openingQ": "A circle is the same shape no matter how big it is. Why do you think that is?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Circles are the most perfect shape.", "sci": "The sky — sun, moon, and stars. The sky changes in patterns.", "ela": "A poem about the moon and stars. What does the poet notice?", "writing": "Drawing the moon and writing the word moon in English and Arabic: قمر", "ss": "The sky belongs to everyone — all peoples have watched the same stars."}, "9": {"math": "Measuring length by counting units. Which is longer, shorter, the same?", "scholar": "Ibn Sina", "openingQ": "A plant knows which way is up before it reaches the soil. How does it know?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "A living thing knows more about itself than any scientist does.", "sci": "Plants need water, light, and air to grow. What happens if one is missing?", "ela": "A story about a plant that needs something to grow. What does it need?", "writing": "Drawing a plant and writing what it needs: water, light, soil.", "ss": "Plants and people — every culture depends on plants for food and medicine."}, "10": {"math": "Counting to 100 by 1s and 10s. Patterns in counting.", "scholar": "Al-Masudi", "openingQ": "What is something in your life that is always changing? What is something that always stays the same?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Change is always good.", "sci": "Weather changes — sunny, cloudy, windy, rainy. Weather patterns over time.", "ela": "Talking about yesterday, today, and tomorrow. Words for time.", "writing": "Drawing today's weather and writing one word for it.", "ss": "Seasons and celebrations — how communities mark the passing of time."}, "11": {"math": "Teen numbers — 11 is ten and one more. Understanding the structure of our number system.", "scholar": "Hunayn ibn Ishaq", "openingQ": "If you translated a book from Arabic to English, would it still be the same book?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "Translation always loses something important.", "sci": "Animals and their young — how do animals grow and change?", "ela": "A story where animals talk. What are they communicating?", "writing": "Drawing an animal and writing what sound it makes.", "ss": "Animal families — what humans and animals share."}, "12": {"math": "Ordinal numbers — first, second, third. Order and position.", "scholar": "Al-Jahiz", "openingQ": "What happens when you take something out of its place — a rock from a garden, an animal from its home?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Animals should be allowed to live wherever they want.", "sci": "Putting things in order — big to small, heavy to light, fast to slow.", "ela": "Sorting words — which words go together? Big and huge. Small and tiny.", "writing": "Writing the names of things in order from smallest to biggest.", "ss": "Putting things in order — organising knowledge is an ancient human activity."}, "13": {"math": "Introduction to addition and subtraction word problems. Stories with numbers.", "scholar": "Al-Ghazali", "openingQ": "What is the difference between knowing the answer and understanding why it is true?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "It is better to be kind than to be right.", "sci": "What is the same? What is different? Comparing objects.", "ela": "Listening to a problem story. What was the problem? How was it solved?", "writing": "Drawing a problem and drawing the solution.", "ss": "Problems and solutions — how communities have always solved shared problems."}, "14": {"math": "Equal groups — if everyone gets the same, how many total?", "scholar": "Jabir ibn Hayyan", "openingQ": "Have you ever given something away and felt richer for giving it?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Giving something away always makes you happier than keeping it.", "sci": "Mixing materials — what happens when you mix water and soil? Sand and water?", "ela": "A story about making something together. What did each person bring?", "writing": "Drawing two things mixed together — what do they make?", "ss": "Making new things — what happens when people mix and try."}, "15": {"math": "Describing position — above, below, beside, between, next to.", "scholar": "Ibn al-Nafis", "openingQ": "How would you tell someone something important if they did not speak your language?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "The best way to change someone's mind is to tell them the truth clearly.", "sci": "Communicating observations — how do you tell someone what you noticed?", "ela": "Describing where things are — on top, underneath, beside, between.", "writing": "Drawing a map of the classroom and labelling where things are.", "ss": "Telling others — communication is what makes community possible."}, "16": {"math": "Repeating patterns — AB, ABC, AABB. What comes next?", "scholar": "Al-Tusi", "openingQ": "What cycles do you depend on every day without thinking about them?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "If something keeps happening in the same pattern, it will always keep happening.", "sci": "Day and night — what causes the pattern?", "ela": "A song with a repeating pattern. What comes next?", "writing": "Drawing the same pattern three times and writing what comes next.", "ss": "Day and night around the world — how different peoples understand the sky."}, "17": {"math": "Numbers 0–20 — writing, reading, representing. The symbols we use for numbers.", "scholar": "Ibn Battuta", "openingQ": "Has someone you have never met ever taught you something?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "It is better to see something yourself than to read about it.", "sci": "Different kinds of animals — what do they all have in common?", "ela": "Reading the names of numbers. What does each symbol mean?", "writing": "Writing your name, the date, and the name of one thing you love.", "ss": "Animals in different cultures — how communities relate to the animals around them."}, "18": {"math": "Careful counting — counting each object exactly once. Precision.", "scholar": "Al-Kashi", "openingQ": "Have you ever done something carelessly and wished you had paid more attention?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Doing something slowly and carefully is always better than doing it quickly.", "sci": "Looking carefully — observing the same thing multiple times.", "ela": "Looking closely at a picture — what did you notice after five minutes?", "writing": "Drawing the same object from two different angles.", "ss": "Doing careful work — precision has always been valued."}, "19": {"math": "Comparing numbers to 10 — greater than, less than, equal to.", "scholar": "Ibn Majid", "openingQ": "Have you ever arrived somewhere and found it was much bigger than you imagined?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Exploring new places is always worth the danger.", "sci": "Maps of our classroom and school — where things are.", "ela": "Comparing two versions of the same story. What is different?", "writing": "Drawing your neighbourhood and labelling three things in it.", "ss": "Knowing your place — every community has a geography."}, "20": {"math": "Addition and subtraction to 10. Fluency with small numbers.", "scholar": "Al-Jazari", "openingQ": "What is the most useful tool you own? What does it let you do that you could not do without it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Tools are better than muscles for getting work done.", "sci": "Simple machines — ramps, levers. Which makes the job easier?", "ela": "A story about pushing and pulling. What moved? Why?", "writing": "Drawing a lever — a seesaw with two different weights.", "ss": "Tools make work easier — humans have always made tools."}, "21": {"math": "Shapes in the world — finding circles, squares, and triangles around us.", "scholar": "Ibn Battuta", "openingQ": "What is something from long ago that you still use every day?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "It is more important to remember what happened than to understand why it happened.", "sci": "Leaves, bark, seeds — nature materials and where they come from.", "ela": "Hearing about a place far away. What was it like?", "writing": "Drawing a leaf and writing five words that describe it.", "ss": "The natural world as teacher — what humans have learned from nature."}, "22": {"math": "Measuring and comparing weight — heavier, lighter, the same.", "scholar": "Al-Maqrizi", "openingQ": "Is it possible to be fair with numbers? Can mathematics be just?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "It is always wrong to take more than your fair share.", "sci": "Same and different — comparing two animals or two plants.", "ela": "A story about two animals. How are they alike? How are they different?", "writing": "Drawing two animals and writing one way they are the same.", "ss": "Same and different — respecting difference is a human value."}, "23": {"math": "Making 10 — all the ways to make 10 with two numbers.", "scholar": "Fatima al-Fihri", "openingQ": "What is the hardest thing about beginning something you have never done before?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "It is harder to start something than to finish it.", "sci": "Starting something new — planting a seed and watching what happens.", "ela": "A story about starting something new. How did it feel at the beginning?", "writing": "Drawing a seed and the plant it will become.", "ss": "Starting something new — communities are founded by people who began."}, "24": {"math": "Introduction to data — sorting objects and counting each group.", "scholar": "Ibn Khaldun", "openingQ": "Have you ever understood something, forgotten it, and then understood it again? Did it feel different the second time?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "When something breaks, it is usually better to make something new than to fix the old one.", "sci": "Why do birds flock? Why do ants follow each other?", "ela": "Listening to a story about a community. How did the people work together?", "writing": "Drawing a group working together and writing what each person did.", "ss": "Why people work together — the reason for community."}, "25": {"math": "Review: all the ways to add and subtract to 10.", "scholar": "Ibn al-Haytham", "openingQ": "Who taught you something this year that you will teach someone else someday?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The best way to learn something is to teach it.", "sci": "What have we learned about living things this year?", "ela": "Retelling a story from earlier in the year. What do you remember?", "writing": "Drawing your favourite moment from a story this year.", "ss": "Remembering — every culture values memory and passing knowledge on."}, "26": {"math": "Writing number sentences — 3 + 2 = 5.", "scholar": "Al-Khwarizmi", "openingQ": "How do you prove something is true? What counts as proof?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "A picture proves something better than words.", "sci": "Testing an idea — does the heavier rock fall faster?", "ela": "Writing our names and the names of things we know.", "writing": "Writing your name on the front of your portfolio.", "ss": "Writing and drawing — humans have always recorded what matters."}, "27": {"math": "Connecting counting, adding, and subtracting as one idea.", "scholar": "Al-Farabi", "openingQ": "What is something you were certain about at the beginning of the year that you are less certain about now?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "It is better to know you do not know something than to think you know when you do not.", "sci": "Questions we still have — what do we not yet understand?", "ela": "Connecting two stories from this year — what did both of them teach?", "writing": "Drawing a picture of something you understand now that you did not before.", "ss": "What we have learned — the joy of understanding something new."}, "28": {"math": "Numbers beyond 20 — counting and writing to 30.", "scholar": "Al-Idrisi", "openingQ": "Can you make something that is completely new — something that is not made of anything you have seen before?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Truly new things are impossible — everything is made from something that already exists.", "sci": "The world outside — observing changes in the season.", "ela": "A new story about a big number. What does one thousand mean?", "writing": "Drawing what you think numbers bigger than 20 look like.", "ss": "Big numbers — what it feels like to encounter something larger than before."}, "29": {"math": "Completing unfinished patterns and sequences.", "scholar": "Al-Biruni", "openingQ": "What is something you started this year that you are still working on?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "The hardest part of any project is starting it.", "sci": "Finishing our plant investigation — what happened over the year?", "ela": "Finishing a story that stops halfway. What happens next?", "writing": "Drawing what comes at the end of an unfinished story.", "ss": "Finishing — the importance of completing what we begin."}, "30": {"math": "Capstone: counting, sorting, adding, and subtracting — what mathematics can we do now?", "scholar": "Al-Battani", "openingQ": "What did you know at the beginning of this year that you did not know before?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The end of one year of school is the same as the beginning of the next.", "sci": "Capstone: what do we observe in our world that we could not explain at the beginning of the year?", "ela": "Listening to all the books from this year. Which was your favourite?", "writing": "Drawing everything you can remember learning this year.", "ss": "Everything together — celebrating a year of growing."}}, "1": {"1": {"math": "Counting and writing numbers to 120. Place value: tens and ones.", "scholar": "Al-Idrisi", "openingQ": "When you make something — a drawing, a tower, a story — where did it come from?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "Making a mess is the beginning of making something good.", "sci": "Earth materials — rocks, soil, water. Where does soil come from?", "ela": "Informational text about maps — what do maps show us that photographs cannot?", "writing": "Writing three sentences about a place you know well.", "ss": "Al-Idrisi — the great Islamic geographer. He mapped the world."}, "2": {"math": "Patterns in addition facts. Doubles, near-doubles, and number patterns.", "scholar": "Al-Biruni", "openingQ": "What is a pattern? Can you find one in the classroom right now?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Patterns in nature are more beautiful than patterns people make.", "sci": "Properties of materials — colour, texture, hardness, magnetism.", "ela": "A poem about patterns in nature. What does the poet notice?", "writing": "Drawing and writing about a pattern you found outside.", "ss": "Patterns in nature have been noticed by people everywhere throughout history."}, "3": {"math": "Two-digit addition without regrouping. Decomposing numbers by place value.", "scholar": "Ibn Rushd", "openingQ": "What makes something strong enough not to fall down?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "The tallest tower is always the best tower.", "sci": "Sound — pushing air with vibration. How is sound made and transmitted?", "ela": "A picture book about building a bridge. What made it hard?", "writing": "Writing the steps for building something: First… Then… Finally…", "ss": "The first engineers — humans have always built structures."}, "4": {"math": "Equal shares — halves and quarters. Dividing shapes and groups fairly.", "scholar": "Al-Khwarizmi", "openingQ": "If you had eight dates and three friends, how would you share them so it feels fair?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Sharing equally is always the fairest way to share.", "sci": "Plants and animals in ecosystems — who eats what?", "ela": "A story about a family sharing food. How did they decide who got how much?", "writing": "Writing about a time you shared something. Was it fair?", "ss": "How communities share food — markets, gifts, and fairness."}, "5": {"math": "Comparing two-digit numbers using place value. Greater than, less than, equal.", "scholar": "Al-Kashi", "openingQ": "What is the difference between nearly right and exactly right? Does it always matter?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "Close enough is good enough.", "sci": "Measuring in science — using rulers and balances.", "ela": "Comparing two texts about the same animal — which tells us more?", "writing": "Writing three describing words for your favourite animal.", "ss": "Measurement in ancient civilisations — cubits, paces, and the first standard units."}, "6": {"math": "Addition and subtraction facts to 20. Building fluency.", "scholar": "Ibn Khaldun", "openingQ": "How do you know when someone is telling the truth?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "You should only believe what you have seen yourself.", "sci": "Investigation — planning a simple test and predicting what will happen.", "ela": "An informational text about asking questions. How do scientists begin?", "writing": "Writing one question you have about science and one idea about the answer.", "ss": "The first questions — what drove the earliest scientists?"}, "7": {"math": "Measuring length with non-standard units. What makes a good measurement?", "scholar": "Ibn al-Haytham", "openingQ": "What is the difference between looking at something and really seeing it?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Seeing is believing.", "sci": "Light — what materials let light through? What block it?", "ela": "A biography of a scientist who looked carefully. What did they discover?", "writing": "Writing what you see when you look at something for five minutes.", "ss": "Light and darkness — how different cultures have understood the sun."}, "8": {"math": "Introduction to geometry — circles, triangles, rectangles, squares, and their attributes.", "scholar": "Al-Battani", "openingQ": "A circle is the same shape no matter how big it is. Why do you think that is?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Circles are the most perfect shape.", "sci": "Patterns in the sky — sun moves across the sky. Moon changes shape.", "ela": "A poem about the moon. What does the poet see? What do you see?", "writing": "Writing a poem with two lines that describe the moon.", "ss": "The Islamic calendar — why the moon matters for Muslim communities."}, "9": {"math": "Skip counting by 2s, 5s, and 10s. Patterns in counting.", "scholar": "Ibn Sina", "openingQ": "A plant knows which way is up before it reaches the soil. How does it know?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "A living thing knows more about itself than any scientist does.", "sci": "What do living things need? Plants, animals, and humans.", "ela": "A story about a seed growing into a tree. What does it need at each stage?", "writing": "Writing what a plant needs — and what happens if it does not get it.", "ss": "Gardens and agriculture — how farming changed human civilisation."}, "10": {"math": "Introduction to telling time — hours and half hours.", "scholar": "Al-Masudi", "openingQ": "What is something in your life that is always changing? What is something that always stays the same?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Change is always good.", "sci": "Seasons — how does our environment change throughout the year?", "ela": "Reading about seasons — how does your town change across the year?", "writing": "Writing three sentences about how your classroom changes across the year.", "ss": "Seasons around the world — how geography shapes daily life."}, "11": {"math": "Two-digit subtraction without regrouping. Using place value to subtract.", "scholar": "Hunayn ibn Ishaq", "openingQ": "If you translated a book from Arabic to English, would it still be the same book?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "Translation always loses something important.", "sci": "Animal communication — how do animals tell each other things?", "ela": "A story where a character learns to communicate without words.", "writing": "Writing a short story where an animal needs to communicate something important.", "ss": "Animal communication across cultures — what humans have learned from animals."}, "12": {"math": "Organising data into categories and counting. Simple bar graphs.", "scholar": "Al-Jahiz", "openingQ": "What happens when you take something out of its place — a rock from a garden, an animal from its home?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Animals should be allowed to live wherever they want.", "sci": "Classifying objects — hard/soft, rough/smooth, floats/sinks.", "ela": "An informational text about sorting — how do libraries organise books?", "writing": "Writing a list of things sorted into two categories. Explain your rule.", "ss": "Libraries and archives — how communities organise their knowledge."}, "13": {"math": "Problem solving with addition and subtraction. Writing number sentences.", "scholar": "Al-Ghazali", "openingQ": "What is the difference between knowing the answer and understanding why it is true?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "It is better to be kind than to be right.", "sci": "Problem solving — if your plant is dying, how do you figure out why?", "ela": "A mystery story — how does the character figure out what happened?", "writing": "Writing about a problem and how it was solved.", "ss": "Community problem-solving — how people historically solved shared challenges."}, "14": {"math": "Equal groups — the beginning of multiplication thinking.", "scholar": "Jabir ibn Hayyan", "openingQ": "Have you ever given something away and felt richer for giving it?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Giving something away always makes you happier than keeping it.", "sci": "Materials and their uses — what material is best for each job?", "ela": "A craft text — instructions for making something. Following steps.", "writing": "Writing instructions for making something — with numbered steps.", "ss": "Markets and trade — how communities have exchanged goods and ideas."}, "15": {"math": "Graphing on a line — ordering numbers on a number line.", "scholar": "Ibn al-Nafis", "openingQ": "How would you tell someone something important if they did not speak your language?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "The best way to change someone's mind is to tell them the truth clearly.", "sci": "Telling others what you found — writing and drawing observations.", "ela": "A letter from a character to a friend. What is a letter for?", "writing": "Writing a letter to a scientist asking one question.", "ss": "Writing systems — how different cultures developed literacy."}, "16": {"math": "Patterns — growing and repeating. What is the rule?", "scholar": "Al-Tusi", "openingQ": "What cycles do you depend on every day without thinking about them?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "If something keeps happening in the same pattern, it will always keep happening.", "sci": "The moon's pattern — waxing and waning over the month.", "ela": "A poem with a repeating refrain. What changes? What stays the same?", "writing": "Writing a poem with a repeating line — something that keeps coming back.", "ss": "The moon in Islamic tradition — the lunar calendar and Ramadan."}, "17": {"math": "Review: all addition and subtraction strategies learned this year.", "scholar": "Ibn Battuta", "openingQ": "Has someone you have never met ever taught you something?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "It is better to see something yourself than to read about it.", "sci": "Different habitats — desert, forest, ocean. Who lives where?", "ela": "An informational text about different animals around the world.", "writing": "Writing five sentences about an animal that lives somewhere very different from here.", "ss": "Habitats and peoples — how environments shape culture."}, "18": {"math": "Measuring carefully with rulers. The importance of starting at zero.", "scholar": "Al-Kashi", "openingQ": "Have you ever done something carelessly and wished you had paid more attention?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Doing something slowly and carefully is always better than doing it quickly.", "sci": "Repeating a test — why do scientists test the same thing more than once?", "ela": "A story about a character who keeps trying. Why do they not give up?", "writing": "Writing about a time you tried something more than once before it worked.", "ss": "Careful workers in history — artisans, scribes, and craftspeople."}, "19": {"math": "Two-digit addition with regrouping. Why we carry the ten.", "scholar": "Ibn Majid", "openingQ": "Have you ever arrived somewhere and found it was much bigger than you imagined?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Exploring new places is always worth the danger.", "sci": "Our local environment — what plants and animals live here?", "ela": "Reading about our local community — who lives here?", "writing": "Writing three things about your community that you are proud of.", "ss": "Our community — who lives here and what is its history?"}, "20": {"math": "Adding three numbers. Does the order matter?", "scholar": "Al-Jazari", "openingQ": "What is the most useful tool you own? What does it let you do that you could not do without it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Tools are better than muscles for getting work done.", "sci": "Pushes and pulls on objects — force and distance.", "ela": "A picture book about a machine that helps people.", "writing": "Writing about a machine that helps people and how it works.", "ss": "Simple machines in history — the wheel, the lever, the ramp."}, "21": {"math": "Telling time to the nearest half hour and quarter hour.", "scholar": "Ibn Battuta", "openingQ": "What is something from long ago that you still use every day?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "It is more important to remember what happened than to understand why it happened.", "sci": "Earth from above — aerial photographs and what they show.", "ela": "A text about a place the student has never been. Imagining from words.", "writing": "Writing about somewhere you have never been, using only what you read.", "ss": "Fossils and ancient peoples — how our ancestors understood the past."}, "22": {"math": "Comparing and ordering lengths. Measuring the same thing two ways.", "scholar": "Al-Maqrizi", "openingQ": "Is it possible to be fair with numbers? Can mathematics be just?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "It is always wrong to take more than your fair share.", "sci": "How are these two things the same? How are they different?", "ela": "A story where two characters are the same in some ways and different in others.", "writing": "Writing two paragraphs — one about how two things are alike, one about how they differ.", "ss": "Protecting nature — how different cultures have valued the environment."}, "23": {"math": "Introduction to fractions — halves and quarters of shapes and groups.", "scholar": "Fatima al-Fihri", "openingQ": "What is the hardest thing about beginning something you have never done before?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "It is harder to start something than to finish it.", "sci": "Starting something new — a new investigation designed by students.", "ela": "An informational text about a tree from seed to forest.", "writing": "Writing the life cycle of a butterfly in four steps.", "ss": "Life cycles in nature and in human life — birth, growth, change."}, "24": {"math": "Complex addition and subtraction word problems.", "scholar": "Ibn Khaldun", "openingQ": "Have you ever understood something, forgotten it, and then understood it again? Did it feel different the second time?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "When something breaks, it is usually better to make something new than to fix the old one.", "sci": "Birds in a murmuration — how do they move together?", "ela": "A story about a community working together to solve a problem.", "writing": "Writing about how the people in a story worked together.", "ss": "Community cooperation — how communities accomplish large goals."}, "25": {"math": "Reviewing the year — connecting all addition and subtraction concepts.", "scholar": "Ibn al-Haytham", "openingQ": "Who taught you something this year that you will teach someone else someday?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The best way to learn something is to teach it.", "sci": "Reviewing living things — connecting plants, animals, and habitats.", "ela": "Rereading a favourite book from this year. What do you notice now?", "writing": "Writing a review of a book read this year — would you recommend it?", "ss": "Favourite stories — the stories a culture chooses to tell reveal its values."}, "26": {"math": "Geometry — three-dimensional shapes. Cubes, cylinders, cones, spheres.", "scholar": "Al-Khwarizmi", "openingQ": "How do you prove something is true? What counts as proof?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "A picture proves something better than words.", "sci": "Can I prove it? Gathering evidence for a claim.", "ela": "A text with diagrams — what does the diagram add to the words?", "writing": "Writing two sentences and drawing a diagram that explains the same idea.", "ss": "Writing and recording — the importance of written history."}, "27": {"math": "Connecting addition and subtraction as inverse operations.", "scholar": "Al-Farabi", "openingQ": "What is something you were certain about at the beginning of the year that you are less certain about now?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "It is better to know you do not know something than to think you know when you do not.", "sci": "What questions remain? Things we observed but could not explain.", "ela": "A story that connects to science and to the student's own life.", "writing": "Writing about a story from science and a story from reading — what do they share?", "ss": "Stories and science — both are ways of understanding the world."}, "28": {"math": "Counting, writing, and representing numbers to 150.", "scholar": "Al-Idrisi", "openingQ": "Can you make something that is completely new — something that is not made of anything you have seen before?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Truly new things are impossible — everything is made from something that already exists.", "sci": "Preview of Grade 2 — matter and materials.", "ela": "Reading a text with unfamiliar words — strategies for figuring them out.", "writing": "Writing three questions you have about something you will study next year.", "ss": "What comes next — preview of the next year's history."}, "29": {"math": "Completing number sequences and patterns — what is missing?", "scholar": "Al-Biruni", "openingQ": "What is something you started this year that you are still working on?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "The hardest part of any project is starting it.", "sci": "Completing our investigation and recording results.", "ela": "Reading a text written by a student. What makes student writing strong?", "writing": "Reading a classmate's writing and writing one thing you noticed.", "ss": "Learning from each other — how communities share knowledge."}, "30": {"math": "Capstone: what can we count, measure, and calculate?", "scholar": "Al-Battani", "openingQ": "What did you know at the beginning of this year that you did not know before?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The end of one year of school is the same as the beginning of the next.", "sci": "Capstone: three things we observed and can now explain.", "ela": "A celebration text — stories of what was learned this year.", "writing": "Writing three things you learned this year that surprised you.", "ss": "Celebrating a year of learning — what we know now that we did not before."}}, "2": {"1": {"math": "Place value to 1000. Hundreds, tens, and ones. Al-Idrisi's distances on maps were in the thousands.", "scholar": "Al-Idrisi", "openingQ": "When you make something — a drawing, a tower, a story — where did it come from?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "Making a mess is the beginning of making something good.", "sci": "States of matter — solid, liquid, gas. What determines which state?", "ela": "An informational text about rocks and soil — what are they made of?", "writing": "Descriptive paragraph: describe a rock as if explaining it to someone who cannot see it.", "ss": "The Islamic Golden Age — when Baghdad was the centre of the world."}, "2": {"math": "Addition patterns — even and odd numbers. Patterns in the hundreds chart.", "scholar": "Al-Biruni", "openingQ": "What is a pattern? Can you find one in the classroom right now?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Patterns in nature are more beautiful than patterns people make.", "sci": "Properties of materials — what patterns help us identify materials?", "ela": "A poem about animal patterns — stripes, spots, and camouflage.", "writing": "Observation journal: draw and describe a natural pattern over three days.", "ss": "Al-Biruni — the scholar who saw patterns in everything."}, "3": {"math": "Three-digit addition with regrouping. The structure of carrying.", "scholar": "Ibn Rushd", "openingQ": "What makes something strong enough not to fall down?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "The tallest tower is always the best tower.", "sci": "Structures in nature — how do plants support themselves against wind and gravity?", "ela": "A story about someone who built something and it fell down. What did they learn?", "writing": "Procedural writing: write step-by-step instructions for making a paper bridge.", "ss": "Ibn Rushd — the philosopher who built arguments like structures."}, "4": {"math": "Introduction to multiplication — equal groups and repeated addition. Fair distribution.", "scholar": "Al-Khwarizmi", "openingQ": "If you had eight dates and three friends, how would you share them so it feels fair?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Sharing equally is always the fairest way to share.", "sci": "Food chains and food webs — following energy through an ecosystem.", "ela": "An informational text about food chains — who eats whom?", "writing": "Informational paragraph: explain one food chain from sun to predator.", "ss": "Al-Khwarizmi and the invention of algebra — why it changed the world."}, "5": {"math": "Comparing and ordering three-digit numbers. What makes one number larger than another?", "scholar": "Al-Kashi", "openingQ": "What is the difference between nearly right and exactly right? Does it always matter?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "Close enough is good enough.", "sci": "Measuring matter — mass, volume, length. Why we use standard units.", "ela": "Reading a science report — what makes a report trustworthy?", "writing": "Science writing: write a prediction before an experiment and compare to what happened.", "ss": "Measurement in the ancient world — how precision developed."}, "6": {"math": "Three-digit subtraction with regrouping. Borrowing across place values.", "scholar": "Ibn Khaldun", "openingQ": "How do you know when someone is telling the truth?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "You should only believe what you have seen yourself.", "sci": "Testing materials — which absorbs the most water? Designing the test.", "ela": "A biography of a scientist. What questions drove their work?", "writing": "Question and investigation: write your question, how you will test it, and what you found.", "ss": "The scientific method — when it was invented and by whom."}, "7": {"math": "Measuring length in inches and feet. Choosing appropriate units.", "scholar": "Ibn al-Haytham", "openingQ": "What is the difference between looking at something and really seeing it?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Seeing is believing.", "sci": "Observation skills — looking at the same rock for five minutes.", "ela": "An excerpt about light — can you see in the dark? What do you need?", "writing": "Observation report: describe what happens when light shines through different materials.", "ss": "Ibn al-Haytham — how he proved the eye receives light."}, "8": {"math": "Introduction to shapes and their attributes — sides, corners, faces, edges.", "scholar": "Al-Battani", "openingQ": "A circle is the same shape no matter how big it is. Why do you think that is?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Circles are the most perfect shape.", "sci": "Patterns in the sky — sunrise and sunset times change across the year.", "ela": "A poem about the sky at night — what has been noticed across cultures?", "writing": "Poem: write a poem about the moon using five sensory details.", "ss": "Islamic astronomy — why accurate star charts mattered."}, "9": {"math": "Telling time to the nearest five minutes. AM and PM.", "scholar": "Ibn Sina", "openingQ": "A plant knows which way is up before it reaches the soil. How does it know?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "A living thing knows more about itself than any scientist does.", "sci": "Plants as living systems — roots, stems, leaves, flowers each have a function.", "ela": "An informational text about what plants need — with diagrams.", "writing": "Explanation: explain what a plant needs in a way a three-year-old would understand.", "ss": "Ibn Sina — the child who became the greatest doctor of his age."}, "10": {"math": "Measurement — measuring and estimating in standard units.", "scholar": "Al-Masudi", "openingQ": "What is something in your life that is always changing? What is something that always stays the same?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Change is always good.", "sci": "Slow and fast changes — erosion versus earthquake.", "ela": "Reading about seasons in different countries. Is winter everywhere the same?", "writing": "Comparison: write about one way your environment is the same as another and one way it is different.", "ss": "Al-Masudi — the scholar who studied how the world changes."}, "11": {"math": "Introduction to fractions — halves, thirds, quarters of shapes.", "scholar": "Hunayn ibn Ishaq", "openingQ": "If you translated a book from Arabic to English, would it still be the same book?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "Translation always loses something important.", "sci": "How animals communicate — sounds, colours, movements.", "ela": "A text about animal communication — how do bees tell each other where flowers are?", "writing": "Narrative: tell the story of a bee finding a flower from the bee's perspective.", "ss": "The translation movement — how knowledge moved between civilisations."}, "12": {"math": "Organising data in bar graphs and picture graphs. Reading and interpreting.", "scholar": "Al-Jahiz", "openingQ": "What happens when you take something out of its place — a rock from a garden, an animal from its home?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Animals should be allowed to live wherever they want.", "sci": "Classifying living things — Ibn Sina's approach to organising the natural world.", "ela": "An informational text about classification — how do scientists sort things?", "writing": "Classification writing: create your own classification system for classroom objects and explain it.", "ss": "Al-Jahiz — the naturalist who wrote about animals with joy."}, "13": {"math": "Word problems with two steps. Addition and subtraction combined.", "scholar": "Al-Ghazali", "openingQ": "What is the difference between knowing the answer and understanding why it is true?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "It is better to be kind than to be right.", "sci": "Science and evidence — how do we know the Earth is round?", "ela": "A mystery — the character must figure out what is causing a problem.", "writing": "Mystery: write a short mystery where the detective solves a problem using clues.", "ss": "Al-Ghazali — the philosopher who chose faith over fame."}, "14": {"math": "Arrays — rows and columns. The connection to multiplication.", "scholar": "Jabir ibn Hayyan", "openingQ": "Have you ever given something away and felt richer for giving it?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Giving something away always makes you happier than keeping it.", "sci": "Mixing and separating materials — reversible and irreversible changes.", "ela": "A story about a character who mixes two things and is surprised by the result.", "writing": "Cause and effect: write what happens when you mix baking soda and vinegar.", "ss": "Jabir ibn Hayyan — the founder of chemistry."}, "15": {"math": "Number lines — placing numbers, finding differences.", "scholar": "Ibn al-Nafis", "openingQ": "How would you tell someone something important if they did not speak your language?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "The best way to change someone's mind is to tell them the truth clearly.", "sci": "Communicating science — what makes a diagram helpful?", "ela": "Reading a letter written by a child to a scientist. What did the child ask?", "writing": "Letter: write a letter to a scientist explaining an experiment you did.", "ss": "Scholars and patrons — who paid for Islamic science?"}, "16": {"math": "Skip counting — 2s, 3s, 4s, 5s, 10s. Building toward multiplication tables.", "scholar": "Al-Tusi", "openingQ": "What cycles do you depend on every day without thinking about them?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "If something keeps happening in the same pattern, it will always keep happening.", "sci": "Moon phases as a cycle — predicting the next phase.", "ela": "A poem about the moon across different cultures. How have people understood it?", "writing": "Poetry: write a poem about a cycle — day and night, seasons, the water cycle.", "ss": "The Islamic calendar — how Muslims track time."}, "17": {"math": "Introduction to multiplication facts — 2s and 5s.", "scholar": "Ibn Battuta", "openingQ": "Has someone you have never met ever taught you something?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "It is better to see something yourself than to read about it.", "sci": "Habitats and adaptations — how does the arctic fox survive the cold?", "ela": "An informational text about habitats. What makes a habitat right for an animal?", "writing": "Informational: write three facts about a habitat you researched.", "ss": "Ibn Battuta — the greatest traveller in medieval history."}, "18": {"math": "Measuring with precision — why the same object measured twice should give the same answer.", "scholar": "Al-Kashi", "openingQ": "Have you ever done something carelessly and wished you had paid more attention?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Doing something slowly and carefully is always better than doing it quickly.", "sci": "Measurement precision — using the right tool for the right measurement.", "ela": "A story about measuring — why the character keeps getting different answers.", "writing": "Reflection: write about a time you measured something and it did not work — what did you change?", "ss": "Precision in Islamic scholarship — the culture of exactness."}, "19": {"math": "Introduction to money — counting coins and notes.", "scholar": "Ibn Majid", "openingQ": "Have you ever arrived somewhere and found it was much bigger than you imagined?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Exploring new places is always worth the danger.", "sci": "Maps and environments — what can a map of an ecosystem tell us?", "ela": "A text about a local community's history. Where did people come from?", "writing": "Community writing: write about one person or place in your community that matters.", "ss": "Islamic trade routes — how goods and knowledge travelled."}, "20": {"math": "Introduction to multiplication facts — 10s and 1s.", "scholar": "Al-Jazari", "openingQ": "What is the most useful tool you own? What does it let you do that you could not do without it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Tools are better than muscles for getting work done.", "sci": "Balanced and unbalanced forces — why does a book stay still on a table?", "ela": "An informational text about how a simple machine makes work easier.", "writing": "Technical: write how a lever or ramp makes work easier.", "ss": "Al-Jazari — the engineer who built thinking machines."}, "21": {"math": "Volume and capacity — comparing containers by how much they hold.", "scholar": "Ibn Battuta", "openingQ": "What is something from long ago that you still use every day?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "It is more important to remember what happened than to understand why it happened.", "sci": "Fossils — what do they tell us about the past?", "ela": "Reading about fossils — what can a bone tell us about an animal that lived millions of years ago?", "writing": "Historical: write about what a fossil tells us about the past.", "ss": "Cordoba — the most advanced city in medieval Europe."}, "22": {"math": "Addition and subtraction in context — word problems with money.", "scholar": "Al-Maqrizi", "openingQ": "Is it possible to be fair with numbers? Can mathematics be just?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "It is always wrong to take more than your fair share.", "sci": "Human impact on environments — what happens when a habitat is destroyed?", "ela": "A text about what happens when one species disappears from a habitat.", "writing": "Argument: write whether people should be allowed to keep animals from wild habitats as pets.", "ss": "The Silk Road — the trade route that connected East and West."}, "23": {"math": "Fractions in context — sharing equally, parts of groups.", "scholar": "Fatima al-Fihri", "openingQ": "What is the hardest thing about beginning something you have never done before?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "It is harder to start something than to finish it.", "sci": "Introduction to life cycles — egg to adult in different animals.", "ela": "A story about a caterpillar becoming a butterfly — more than just the facts.", "writing": "Narrative: tell the story of a caterpillar becoming a butterfly from its own perspective.", "ss": "Fatima al-Fihri — the woman who built the world's first university."}, "24": {"math": "Introduction to data analysis — what does a graph tell us?", "scholar": "Ibn Khaldun", "openingQ": "Have you ever understood something, forgotten it, and then understood it again? Did it feel different the second time?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "When something breaks, it is usually better to make something new than to fix the old one.", "sci": "Systems — what happens when one part of a food web changes?", "ela": "An informational text about migration — why do birds fly thousands of miles?", "writing": "Explanation: explain why birds migrate, step by step.", "ss": "The Mongol invasion — what was destroyed and what survived."}, "25": {"math": "Reviewing and connecting all multiplication concepts.", "scholar": "Ibn al-Haytham", "openingQ": "Who taught you something this year that you will teach someone else someday?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The best way to learn something is to teach it.", "sci": "Reviewing matter — solid, liquid, gas and the changes between them.", "ela": "Rereading our favourite informational text — what did we miss the first time?", "writing": "Revision: take a piece from earlier this year and make it better.", "ss": "The oral tradition — how knowledge was passed before writing."}, "26": {"math": "Geometry — symmetry. Lines of symmetry in shapes and patterns.", "scholar": "Al-Khwarizmi", "openingQ": "How do you prove something is true? What counts as proof?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "A picture proves something better than words.", "sci": "Scientific proof — what evidence would change your mind?", "ela": "A text with evidence — how does the author prove their point?", "writing": "Evidence writing: write a claim and two pieces of evidence that support it.", "ss": "Greek mathematics in the Islamic world — how Euclid was preserved."}, "27": {"math": "Connecting addition, subtraction, and multiplication as related operations.", "scholar": "Al-Farabi", "openingQ": "What is something you were certain about at the beginning of the year that you are less certain about now?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "It is better to know you do not know something than to think you know when you do not.", "sci": "Open questions — what in nature do we still not understand?", "ela": "Two texts on the same topic — which is more convincing? Why?", "writing": "Comparison: two texts on the same topic — which was more convincing and why?", "ss": "The threads — what connects all the scholars we studied this year?"}, "28": {"math": "Numbers beyond 1000 — introduction to four-digit numbers.", "scholar": "Al-Idrisi", "openingQ": "Can you make something that is completely new — something that is not made of anything you have seen before?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Truly new things are impossible — everything is made from something that already exists.", "sci": "Preview of Grade 3 — forces, energy, and weather.", "ela": "An informational text about something we will study next year.", "writing": "Preview writing: three questions you have about something you will study next year.", "ss": "What comes next — the history that follows the Islamic Golden Age."}, "29": {"math": "Patterns and sequences — completing and extending.", "scholar": "Al-Biruni", "openingQ": "What is something you started this year that you are still working on?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "The hardest part of any project is starting it.", "sci": "Completing and presenting our investigation.", "ela": "Reading student writing — what makes a piece of writing shine?", "writing": "Feedback: write two things you liked in a partner's writing and one suggestion.", "ss": "Stories of scholars — which scholar's life was most like your own?"}, "30": {"math": "Capstone: what mathematics can we do with numbers to 1000?", "scholar": "Al-Battani", "openingQ": "What did you know at the beginning of this year that you did not know before?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The end of one year of school is the same as the beginning of the next.", "sci": "Capstone: a phenomenon in nature that we can now explain end to end.", "ela": "A text about a year of learning — the journey from not knowing to knowing.", "writing": "Reflection: write about the most important thing you learned about writing this year.", "ss": "The full arc — from Al-Idrisi to Ibn Khaldun — a world of scholarship."}}, "3": {"1": {"math": "Place value to 10,000. Reading, writing, and representing large numbers.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi drew the whole world from knowledge he collected piece by piece. How do you build a picture of something you cannot see all at once?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A map that is incomplete is more useful than a map that is wrong.", "sci": "Earth systems — atmosphere, hydrosphere, lithosphere, biosphere.", "ela": "Introduction to the Islamic Golden Age — what was happening in Baghdad in 800 CE?", "writing": "Biographical paragraph: write a paragraph about Al-Idrisi's greatest achievement.", "ss": "Pre-Islamic Arabia — the world before the Prophet ﷺ."}, "2": {"math": "Multiplication patterns — the commutative property. Times tables as patterns.", "scholar": "Al-Biruni", "openingQ": "Al-Biruni found the same patterns in crystals, planets, and languages. Why do you think the same patterns keep appearing?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is a language, not a discovery — humans invented it.", "sci": "Traits in organisms — what features do all members of a species share?", "ela": "A biography of Al-Biruni — what patterns did he see everywhere he looked?", "writing": "Observation journal: document a natural pattern across five days.", "ss": "The revelation and the first community — Makkah and Madinah."}, "3": {"math": "Multiplication by single digits. Strategies: arrays, area models, repeated addition.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd said a good argument is like a good building — everything has to support everything else. What does that mean?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "A strong argument is more powerful than a strong building.", "sci": "Forces — balanced and unbalanced. What makes things stay still or move?", "ela": "Reading Ibn Rushd on argument — what makes a reason good?", "writing": "Structured argument: write an argument for a position using claim, evidence, reasoning.", "ss": "The early caliphate — Abu Bakr, Umar, Uthman, Ali."}, "4": {"math": "Division as equal sharing and equal grouping. The relationship between multiplication and division.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Khwarizmi wrote his algebra book so that ordinary people could solve problems of inheritance and trade. Why did he think mathematics should belong to everyone?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Fair distribution is more important than efficient distribution.", "sci": "Food chains, webs, and the flow of energy in ecosystems.", "ela": "Adapted excerpt from Al-Khwarizmi introduction — who did he write for and why?", "writing": "Explanation: explain Al-Khwarizmi's innovation to someone who has never heard of algebra.", "ss": "The Umayyad dynasty — expanding the Islamic world."}, "5": {"math": "Fractions — unit fractions and the idea of the whole. What does ¼ really mean?", "scholar": "Al-Kashi", "openingQ": "Al-Kashi spent years calculating pi to 16 decimal places. Why would anyone spend years on a calculation that was already good enough?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "Approximate knowledge is better than no knowledge.", "sci": "Scientific measurement — accuracy, precision, and calibration.", "ela": "A text about measurement — what did scholars use before standardised units?", "writing": "Science report: conduct a simple measurement and report the method, result, and error.", "ss": "The Abbasid revolution — Baghdad and the new centre of the world."}, "6": {"math": "Multiplication and division facts to 100. Strategies for fluency.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun said that most history is wrong because historians copy each other without checking. How would you check whether something written a thousand years ago is true?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "You cannot trust knowledge you have not verified yourself.", "sci": "Testing hypotheses — designing a fair test with one variable.", "ela": "An informational text on the scientific method — who invented it and when?", "writing": "Scientific procedure: design and write up a simple investigation.", "ss": "The House of Wisdom — the greatest library ever built."}, "7": {"math": "Area — counting square units. Length × width for rectangles.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham spent years in a dark room testing how light worked. What does it take to observe something so carefully that you change what everyone believes?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Careful observation is more valuable than clever theory.", "sci": "Ibn al-Haytham and the scientific method — observation, hypothesis, experiment.", "ela": "Biography of Ibn al-Haytham — imprisoned and how he used the time.", "writing": "Observation-to-argument: three observations that support one conclusion.", "ss": "The translation movement — how Greek knowledge became Islamic knowledge."}, "8": {"math": "Introduction to perimeter and area of simple shapes. Al-Battani's measurements of circular arcs.", "scholar": "Al-Battani", "openingQ": "Pi is the same for every circle on Earth, on Mars, and in every galaxy. What does it mean that a number can be true everywhere?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Pi is evidence that the universe was designed by a mathematician.", "sci": "Earth's rotation and orbit — day, night, and the year.", "ela": "A text about Al-Battani's measurements — why did accuracy matter for the Islamic calendar?", "writing": "Mathematical narrative: tell the story of why the Islamic calendar mattered to Al-Battani.", "ss": "Al-Mamun and the scholars — a caliph who loved science."}, "9": {"math": "Fractions on a number line. What fraction is halfway between 0 and 1?", "scholar": "Ibn Sina", "openingQ": "Ibn Sina described the body as a system where everything connects. What happens to a system when one part stops working?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "A living system cannot be fully understood by studying its parts.", "sci": "Interdependence in ecosystems — what happens when a species is removed?", "ela": "Ibn Sina as a child — he memorised the Quran at 10 and was a doctor at 16.", "writing": "Systems explanation: explain how the human body keeps a constant temperature.", "ss": "Ibn Sina — the greatest doctor of the medieval world."}, "10": {"math": "Telling time — elapsed time. How long did something take?", "scholar": "Al-Masudi", "openingQ": "Al-Masudi travelled for 30 years to understand how peoples and landscapes change. What do you think stays constant while everything around it transforms?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Change is more fundamental than permanence.", "sci": "Weather patterns — data over time. Is this winter warmer than last?", "ela": "Al-Masudi — the greatest traveller before Ibn Battuta.", "writing": "Process writing: document how something changed across repeated observations.", "ss": "Al-Masudi — the historian who travelled to understand."}, "11": {"math": "Introduction to multiplication with multiples of 10. Place value in multiplication.", "scholar": "Hunayn ibn Ishaq", "openingQ": "Hunayn ibn Ishaq said a good translation requires you to understand the idea so completely that you can express it in a different language as if you had thought of it yourself. What do you think is hardest about that?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "Translation always loses something essential.", "sci": "How plants and animals disperse — seeds that fly, animals that migrate.", "ela": "The translation movement — how Arabic became the language of science.", "writing": "Translation exercise: take a passage from science and rewrite it for a younger student.", "ss": "Hunayn ibn Ishaq — the translator who saved Greek medicine."}, "12": {"math": "Organising and interpreting data — frequency tables and pictographs.", "scholar": "Al-Jahiz", "openingQ": "Al-Jahiz wrote that every animal has a place in nature, and when something takes more than its share, the order breaks. What examples can you think of?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Natural order exists independent of human understanding.", "sci": "Classification of living things — kingdoms and their distinguishing features.", "ela": "Al-Jahiz — the scholar who wrote about animals with curiosity and humour.", "writing": "Classification essay: create a classification system for animals in your local environment.", "ss": "Al-Jahiz — the naturalist and the Book of Animals."}, "13": {"math": "Problem solving — two-step word problems using all four operations.", "scholar": "Al-Ghazali", "openingQ": "Al-Ghazali walked away from the most prestigious job in Baghdad to go in search of something more important than being right. What do you think he was looking for?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Wisdom cannot be taught — it can only be discovered.", "sci": "Evidence in science — how do we know dinosaurs existed?", "ela": "Al-Ghazali — the scholar who left fame to seek truth.", "writing": "Philosophical response: is there a difference between what you know and what you believe?", "ss": "Al-Ghazali — the Revival of the Religious Sciences."}, "14": {"math": "Introduction to equivalent fractions — ½ = 2/4 = 4/8.", "scholar": "Jabir ibn Hayyan", "openingQ": "Jabir ibn Hayyan gave his discoveries away freely — he wrote down his methods so that anyone could use them. What does it mean to give knowledge?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Perfect balance is possible in human systems.", "sci": "Chemical and physical changes — Jabir ibn Hayyan and the beginning of chemistry.", "ela": "Jabir ibn Hayyan — why he kept experimenting when others only theorised.", "writing": "Lab report: conduct and write up a simple chemistry investigation.", "ss": "Jabir ibn Hayyan — the first chemist."}, "15": {"math": "Coordinate grids — locating and describing positions.", "scholar": "Ibn al-Nafis", "openingQ": "Ibn al-Nafis proved the blood circulates through the lungs — something everyone believed was impossible. How do you convince people of something true when they are certain it is false?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Clarity is always more important than precision.", "sci": "Communicating scientific findings — what makes a graph misleading?", "ela": "Reading a scientific text and identifying its structure — what comes first?", "writing": "Revision: take your best piece from this year and improve it.", "ss": "The Islamic hospital — the Bimaristan system."}, "16": {"math": "Patterns in multiplication tables — what repeating patterns can you find?", "scholar": "Al-Tusi", "openingQ": "Al-Tusi showed that a straight line can be produced by two circles going around each other. What other things that seem simple turn out to be cycles underneath?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "All complex systems are ultimately cyclical.", "sci": "Moon, sun, and tidal cycles — the ocean's response to the moon.", "ela": "A poem about cycles in nature — comparing Arabic and English poetry.", "writing": "Data report: collect temperature data for a week and write an analysis.", "ss": "The Islamic calendar — Hijri and Gregorian."}, "17": {"math": "Introduction to two-digit multiplication. The area model.", "scholar": "Ibn Battuta", "openingQ": "Ibn Battuta received hospitality and knowledge from strangers across 44 countries. He gave his whole life to writing it all down so others could learn from people they would never meet. What does that kind of generosity look like?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The greatest scholars are those who gave away their knowledge freely.", "sci": "Adaptations — how the camel survives the desert.", "ela": "Ibn Battuta's Rihla — the opening page. Where was he going and why?", "writing": "Scholar letter: write as a 9th-century scholar reporting a discovery to your teacher.", "ss": "Ibn Battuta — 30 countries, one lifetime."}, "18": {"math": "Measurement — measuring area by counting and by calculation. Comparing methods.", "scholar": "Al-Kashi", "openingQ": "Al-Kashi checked his calculations of pi again and again because he knew a small error in astronomy becomes a large error over time. What in your own life gets worse when you are not precise?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Precision is more important than speed.", "sci": "Repeated measurement — why does a careful scientist measure the same thing five times?", "ela": "A text about precision — the difference between close and exact.", "writing": "Precision analysis: choose a calculation and evaluate its precision.", "ss": "Islamic astronomy — precision, prayer, and the calendar."}, "19": {"math": "Introduction to decimals — tenths as fractions and as decimal notation.", "scholar": "Ibn Majid", "openingQ": "Ibn Majid navigated by stars across oceans he had never seen. What does it feel like to commit to a direction when you cannot yet see the destination?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Exploration always does more good than harm.", "sci": "Biomes — climate zones and the life they support.", "ela": "An informational text about the geography of the Islamic world.", "writing": "Geographical writing: describe a biome in detail using research.", "ss": "Islamic geography — Al-Idrisi and the world map."}, "20": {"math": "Force problems — if you push 3 boxes 4 times, how many pushes total?", "scholar": "Al-Jazari", "openingQ": "Al-Jazari built a clock powered by water that told not just the time but the movements of the sun and moon. What does it mean to build something that does the thinking for you?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Tools extend human capability without changing human nature.", "sci": "Simple machines — levers, pulleys, inclined planes. Al-Jazari's engineering.", "ela": "Al-Jazari's inventions — reading a description of a water clock.", "writing": "Technical description: explain how one of Al-Jazari's devices works.", "ss": "Al-Jazari — machines that think."}, "21": {"math": "Introduction to geometry — quadrilaterals and their properties.", "scholar": "Ibn Battuta", "openingQ": "Ibn Battuta recorded everything he saw across three continents so that people who would never travel could know the world. What would be lost if he had not written it down?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The purpose of heritage is to free us from the past, not bind us to it.", "sci": "Fossil record — what patterns in ancient life tell us about evolution.", "ela": "The Great Mosque of Cordoba — what does architecture tell us about a civilisation?", "writing": "Heritage essay: describe the architectural achievement that most impresses you.", "ss": "Cordoba — the jewel of Islamic Europe."}, "22": {"math": "Fractions as division — 3 ÷ 4 = ¾. Connecting division and fractions.", "scholar": "Al-Maqrizi", "openingQ": "Al-Maqrizi studied what happened when rulers debased the currency and the poor suffered first. How do numbers and justice connect?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Every injustice has a measurable, documentable cause.", "sci": "Pollution and ecosystems — the measurable effect of human activity.", "ela": "A text about trade routes — the Silk Road and the spice trade.", "writing": "Trade route description: write about a journey along the Silk Road.", "ss": "Trade and the Silk Road."}, "23": {"math": "Introduction to negative numbers — temperature below zero.", "scholar": "Fatima al-Fihri", "openingQ": "Fatima al-Fihri used her inheritance to build a university when no such thing existed. What do you think she was most afraid of?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "Every beginning requires destroying something that came before.", "sci": "Life cycles and metamorphosis — complete and incomplete transformation.", "ela": "Fatima al-Fihri — how she used her inheritance to change the world.", "writing": "Founding story: write the story of Fatima al-Fihri from her own perspective.", "ss": "Fatima al-Fihri — the founder of the first university."}, "24": {"math": "Data collection and representation — designing a survey and displaying results.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun described how civilisations collapse and then are rebuilt — not the same, but carrying something from what came before. What survives a collapse?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "Complex systems cannot be controlled, only understood.", "sci": "Complex systems — why is it hard to predict the weather more than a week ahead?", "ela": "Reading about the Mongol invasion — what was destroyed and what survived?", "writing": "Systems analysis: explain what caused the decline of the Islamic Golden Age.", "ss": "The Mongols and what survived."}, "25": {"math": "Reviewing multiplication and division — connecting all strategies.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham's method of experiment was so powerful that it was still being taught 900 years later. How does a way of thinking stay alive across centuries?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The best way to learn something is to teach it.", "sci": "Inheritance and variation — why do children look like their parents but not exactly?", "ela": "The oral tradition — how knowledge was passed down before books.", "writing": "Year review letter: write a letter to next year's class.", "ss": "The oral tradition and the isnad."}, "26": {"math": "Geometry — perimeter and area of composite shapes.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Khwarizmi showed that every algebraic statement can be tested — both sides of the equation must balance. What does it mean for a statement to be a claim that can be checked?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "Evidence is always more convincing than argument.", "sci": "Scientific certainty and uncertainty — what does '95% confident' mean?", "ela": "An adapted excerpt from Euclid — what does a definition in mathematics look like?", "writing": "Proof paragraph: write a mathematical claim and prove it in words.", "ss": "Euclid and Islam — how Greek mathematics was preserved."}, "27": {"math": "Mathematical connections — how fractions, division, and ratios are one idea.", "scholar": "Al-Farabi", "openingQ": "Al-Farabi said that logic is the tool for separating what is actually true from what only seems true. How do you know when you have found real truth rather than convincing yourself?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Self-knowledge is impossible without knowledge of others.", "sci": "Open questions in science — what do scientists currently not understand?", "ela": "Revisiting our first text from this year — what do we understand now that we did not then?", "writing": "Year synthesis: what one idea connects everything you studied this year?", "ss": "The Golden Age in three words — what were they?"}, "28": {"math": "Introduction to Grade 4 concepts — larger numbers and multi-step problems.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's second great map combined Arab, African, and Greek knowledge into something that had never existed. How do you make something new from things that already exist?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Truly new things are rare — most creativity is recombination.", "sci": "Preview of Grade 4 — energy transfer and Earth's history.", "ela": "Reading a text about what comes next in history.", "writing": "Forward letter: write a letter to your Grade 4 self.", "ss": "The Ottoman Empire — what came after."}, "29": {"math": "Completing and extending mathematical sequences and patterns.", "scholar": "Al-Biruni", "openingQ": "Al-Biruni spent years learning Sanskrit so he could translate Indian mathematics. Why do some things worth doing take years?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "The hardest part of any project is finishing it.", "sci": "Completing our long-term experiment and analysing the data.", "ela": "Reading student writing — what makes description vivid?", "writing": "Portfolio assembly: select your three best pieces and write an introduction.", "ss": "Scholars as heroes — the lives we studied."}, "30": {"math": "Capstone: a multi-step problem using multiplication, division, fractions, and measurement.", "scholar": "Al-Battani", "openingQ": "Al-Battani measured the solar year — the time it takes for everything to return to where it began. What returns at the end of a year of learning?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The end of one thing is always the beginning of another.", "sci": "Capstone: a multi-step scientific investigation connecting three concepts.", "ela": "A text synthesising everything learned — the Golden Age as a whole.", "writing": "Year-end reflection: the most important thing you understood this year.", "ss": "The Golden Age as a whole — beginning to end."}}, "4": {"1": {"math": "Place value to 1,000,000. Reading, writing, representing. Al-Idrisi's map coordinates.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi drew the whole world from knowledge he collected piece by piece. How do you build a picture of something you cannot see all at once?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A map that is incomplete is more useful than a map that is wrong.", "sci": "Earth's history — reading rock layers. What do sedimentary rocks tell us?", "ela": "Al-Idrisi's world — reading his description of what he saw from his maps.", "writing": "Descriptive essay: describe a place from Al-Idrisi's map in vivid detail.", "ss": "The ancient world before Islam — Egypt, Persia, Byzantium, and the Arabian Peninsula."}, "2": {"math": "Factors and multiples — finding all factors of a number. Prime and composite numbers.", "scholar": "Al-Biruni", "openingQ": "Al-Biruni found the same patterns in crystals, planets, and languages. Why do you think the same patterns keep appearing?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is a language, not a discovery — humans invented it.", "sci": "Energy — what forms does it take and what patterns govern its transfer?", "ela": "Mathematics and nature — a text about the Fibonacci sequence and where it appears.", "writing": "Pattern analysis: write about a mathematical pattern you have found in nature.", "ss": "The Prophet ﷺ — his life and the founding of the Muslim community."}, "3": {"math": "Multi-digit multiplication — standard algorithm and alternative methods.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd said a good argument is like a good building — everything has to support everything else. What does that mean?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "A strong argument is more powerful than a strong building.", "sci": "Waves — sound and light as waves. Structure of a wave.", "ela": "Ibn Rushd's method — how he read Aristotle and improved on him.", "writing": "Philosophical dialogue: two characters debate whether reason and faith conflict.", "ss": "The early caliphate — the four rightly-guided caliphs."}, "4": {"math": "Long division — dividing by single and two-digit divisors. Remainders and their meaning.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Khwarizmi wrote his algebra book so that ordinary people could solve problems of inheritance and trade. Why did he think mathematics should belong to everyone?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Fair distribution is more important than efficient distribution.", "sci": "Energy in food webs — where does the energy in a lion come from?", "ela": "Al-Khwarizmi on algebra — the original problem that led to the book.", "writing": "Mathematical explanation: explain division using Al-Khwarizmi's model.", "ss": "The expansion of the Islamic world — Spain to Central Asia."}, "5": {"math": "Fraction equivalence — generating equivalent fractions. Why ½ = 4/8.", "scholar": "Al-Kashi", "openingQ": "Al-Kashi spent years calculating pi to 16 decimal places. Why would anyone spend years on a calculation that was already good enough?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "Approximate knowledge is better than no knowledge.", "sci": "Measurement and data — mean and range in a scientific investigation.", "ela": "A text about Al-Kashi — calculating pi and why he bothered.", "writing": "Precision essay: why does Al-Kashi's calculation of pi matter?", "ss": "The Abbasid Golden Age — Baghdad at the centre of the world."}, "6": {"math": "Adding and subtracting fractions with like denominators.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun said that most history is wrong because historians copy each other without checking. How would you check whether something written a thousand years ago is true?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "You cannot trust knowledge you have not verified yourself.", "sci": "Designing investigations — controlled experiments and variables.", "ela": "Ibn Khaldun on knowledge — how communities preserve what they know.", "writing": "Epistemic reflection: write about what you know and how you know it.", "ss": "The House of Wisdom — who worked there, what they produced."}, "7": {"math": "Multiplying fractions by whole numbers. What does 3 × ¼ mean?", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham spent years in a dark room testing how light worked. What does it take to observe something so carefully that you change what everyone believes?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Careful observation is more valuable than clever theory.", "sci": "Ibn al-Haytham optics — how does a lens bend light? Investigation with a magnifying glass.", "ela": "Ibn al-Haytham's experiment — reading the original experiment, adapted.", "writing": "Scientific argument: write Ibn al-Haytham's case that vision is reception, not emission.", "ss": "Ibn al-Haytham — the man who invented science."}, "8": {"math": "Introduction to decimals — tenths and hundredths. Connecting fractions and decimals.", "scholar": "Al-Battani", "openingQ": "Pi is the same for every circle on Earth, on Mars, and in every galaxy. What does it mean that a number can be true everywhere?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Pi is evidence that the universe was designed by a mathematician.", "sci": "Earth's movement — seasons caused by axial tilt, not distance from sun.", "ela": "Al-Battani's observations — a first-person account of measuring the stars.", "writing": "Historical narrative: the night Al-Battani made his most important measurement.", "ss": "Al-Battani — the astronomer who refined the calendar."}, "9": {"math": "Comparing fractions with different numerators and denominators.", "scholar": "Ibn Sina", "openingQ": "Ibn Sina described the body as a system where everything connects. What happens to a system when one part stops working?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "A living system cannot be fully understood by studying its parts.", "sci": "Living systems — how do organ systems in the human body work together?", "ela": "Ibn Sina on medicine — the Canon of Medicine, introduction, adapted.", "writing": "Systems essay: explain how Ibn Sina would describe a healthy and an unhealthy body.", "ss": "Ibn Sina — the Canon of Medicine."}, "10": {"math": "Decimal addition and subtraction. Why we line up the decimal point.", "scholar": "Al-Masudi", "openingQ": "Al-Masudi travelled for 30 years to understand how peoples and landscapes change. What do you think stays constant while everything around it transforms?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Change is more fundamental than permanence.", "sci": "Rocks and minerals — how do rocks change over time? The rock cycle.", "ela": "Al-Biruni's journey to India — what he went to find out and what he discovered.", "writing": "Travel writing: write a page of Al-Biruni's journal in India.", "ss": "Al-Biruni — the most curious scholar of the Golden Age."}, "11": {"math": "Introduction to variables and expressions — using a letter for an unknown.", "scholar": "Hunayn ibn Ishaq", "openingQ": "Hunayn ibn Ishaq said a good translation requires you to understand the idea so completely that you can express it in a different language as if you had thought of it yourself. What do you think is hardest about that?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "Translation always loses something essential.", "sci": "Information transfer — how do electrical signals carry information?", "ela": "Hunayn ibn Ishaq — the translation that saved Galen for the world.", "writing": "Translation reflection: what is the most important thing Hunayn ibn Ishaq preserved?", "ss": "Hunayn ibn Ishaq — the master translator."}, "12": {"math": "Angles — measuring with a protractor. Right, acute, obtuse angles.", "scholar": "Al-Jahiz", "openingQ": "Al-Jahiz wrote that every animal has a place in nature, and when something takes more than its share, the order breaks. What examples can you think of?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Natural order exists independent of human understanding.", "sci": "Classification extended — the Linnaean system and its Islamic predecessors.", "ela": "Al-Jahiz on animals — reading a passage from the Book of Animals.", "writing": "Natural history: write an entry for Al-Jahiz's Book of Animals for an animal you know.", "ss": "Al-Jahiz — the first naturalist."}, "13": {"math": "Lines of symmetry and geometric patterns. The mathematics of Islamic geometric art.", "scholar": "Al-Ghazali", "openingQ": "Al-Ghazali walked away from the most prestigious job in Baghdad to go in search of something more important than being right. What do you think he was looking for?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Wisdom cannot be taught — it can only be discovered.", "sci": "Scientific argument — claim, evidence, and reasoning.", "ela": "Al-Ghazali on wisdom — the difference between knowledge and action.", "writing": "Wisdom essay: write about the difference between knowing and being wise.", "ss": "Al-Ghazali — faith, philosophy, and the inner life."}, "14": {"math": "Area and perimeter — finding both for the same shape. Which changes, which stays?", "scholar": "Jabir ibn Hayyan", "openingQ": "Jabir ibn Hayyan gave his discoveries away freely — he wrote down his methods so that anyone could use them. What does it mean to give knowledge?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Perfect balance is possible in human systems.", "sci": "Chemical reactions — evidence that a reaction has occurred.", "ela": "Jabir ibn Hayyan's laboratory — what his notes looked like.", "writing": "Chemistry lab report: design, conduct, and write up an investigation.", "ss": "Jabir ibn Hayyan — from alchemy to chemistry."}, "15": {"math": "Coordinate plane — plotting points in the first quadrant.", "scholar": "Ibn al-Nafis", "openingQ": "Ibn al-Nafis proved the blood circulates through the lungs — something everyone believed was impossible. How do you convince people of something true when they are certain it is false?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Clarity is always more important than precision.", "sci": "Communicating with models — when is a model useful and when is it misleading?", "ela": "A scientific abstract — reading the introduction, methods, and conclusion.", "writing": "Revision workshop: revise a previous piece for precision and clarity.", "ss": "Islamic medicine and the Bimaristan."}, "16": {"math": "Patterns and sequences — arithmetic sequences and their rules.", "scholar": "Al-Tusi", "openingQ": "Al-Tusi showed that a straight line can be produced by two circles going around each other. What other things that seem simple turn out to be cycles underneath?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "All complex systems are ultimately cyclical.", "sci": "The water cycle — evaporation, condensation, precipitation, collection.", "ela": "A poem by Rumi about cycles and return.", "writing": "Poem: write a poem in the tradition of Rumi — an image that becomes a question.", "ss": "Islamic time — the calendar, prayer times, and astronomy."}, "17": {"math": "Review of multiplication and division — connecting strategies.", "scholar": "Ibn Battuta", "openingQ": "Ibn Battuta received hospitality and knowledge from strangers across 44 countries. He gave his whole life to writing it all down so others could learn from people they would never meet. What does that kind of generosity look like?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The greatest scholars are those who gave away their knowledge freely.", "sci": "Ibn Sina on the body — the Canon of Medicine and its approach to systems.", "ela": "Ibn Battuta's encounter with the Sultan of Mali — what surprised him?", "writing": "Scholar portrait: write a profile of Ibn Battuta.", "ss": "Ibn Battuta — the greatest journey of the medieval world."}, "18": {"math": "Multi-step word problems — reading carefully and identifying what to calculate.", "scholar": "Al-Kashi", "openingQ": "Al-Kashi checked his calculations of pi again and again because he knew a small error in astronomy becomes a large error over time. What in your own life gets worse when you are not precise?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Precision is more important than speed.", "sci": "Measurement in astronomy — how do we know how far away a star is?", "ela": "Al-Kashi's method — a page of his calculation, simplified.", "writing": "Precision analysis: write about why precision matters in a specific field.", "ss": "Islamic precision — the culture of exact knowledge."}, "19": {"math": "Introduction to ratio thinking — for every 3 of these, there are 4 of those.", "scholar": "Ibn Majid", "openingQ": "Ibn Majid navigated by stars across oceans he had never seen. What does it feel like to commit to a direction when you cannot yet see the destination?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Exploration always does more good than harm.", "sci": "Human population and resources — how much land does it take to feed one person?", "ela": "The geography of the Islamic world at its peak.", "writing": "Geographical description: write a detailed description of a biome.", "ss": "Islamic trade — the Silk Road, the Indian Ocean routes."}, "20": {"math": "Introduction to force and distance — how levers and pulleys multiply force.", "scholar": "Al-Jazari", "openingQ": "Al-Jazari built a clock powered by water that told not just the time but the movements of the sun and moon. What does it mean to build something that does the thinking for you?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Tools extend human capability without changing human nature.", "sci": "Force and motion — Newton's laws in everyday situations.", "ela": "Al-Jazari's Book of Mechanical Devices — the introduction.", "writing": "Technical writing: explain one of Al-Jazari's inventions in detail.", "ss": "Al-Jazari — the engineer of the medieval world."}, "21": {"math": "Data analysis — mean, median, mode with small data sets.", "scholar": "Ibn Battuta", "openingQ": "Ibn Battuta recorded everything he saw across three continents so that people who would never travel could know the world. What would be lost if he had not written it down?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The purpose of heritage is to free us from the past, not bind us to it.", "sci": "Geologic time — how old is the Earth, and how do we know?", "ela": "The Islamic Golden Age across the world — from Timbuktu to Samarkand.", "writing": "Heritage essay: the Islamic contribution to your field of greatest interest.", "ss": "Islamic architecture — the mosque as a statement of values."}, "22": {"math": "Introduction to percentages — what does 50% of a number mean?", "scholar": "Al-Maqrizi", "openingQ": "Al-Maqrizi studied what happened when rulers debased the currency and the poor suffered first. How do numbers and justice connect?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Every injustice has a measurable, documentable cause.", "sci": "Human-caused environmental change — greenhouse gases and temperature.", "ela": "A primary source on trade — a merchant's letter from the Cairo Geniza.", "writing": "Primary source analysis: write an analysis of a merchant letter from the Cairo Geniza.", "ss": "African kingdoms and the Islamic world — Mali, Timbuktu, and Mansa Musa."}, "23": {"math": "Fractions, decimals, and percentages as three representations of the same idea.", "scholar": "Fatima al-Fihri", "openingQ": "Fatima al-Fihri used her inheritance to build a university when no such thing existed. What do you think she was most afraid of?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "Every beginning requires destroying something that came before.", "sci": "Inheritance — how are traits passed from parents to offspring?", "ela": "Fatima al-Fihri's legacy — what al-Qarawiyyin meant for Islamic scholarship.", "writing": "Founding argument: should Fatima al-Fihri be considered the founder of the university?", "ss": "Fatima al-Fihri and the birth of the university."}, "24": {"math": "Introduction to probability — likely, unlikely, impossible, certain.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun described how civilisations collapse and then are rebuilt — not the same, but carrying something from what came before. What survives a collapse?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "Complex systems cannot be controlled, only understood.", "sci": "Cause and effect in complex systems — trophic cascades.", "ela": "Complexity — a text on how cities grow without being designed.", "writing": "Complexity analysis: explain how cities grow without anyone designing them.", "ss": "The Mongol invasion and the end of the Golden Age."}, "25": {"math": "Reviewing the year — fractions, decimals, measurement, geometry.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham's method of experiment was so powerful that it was still being taught 900 years later. How does a way of thinking stay alive across centuries?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The best way to learn something is to teach it.", "sci": "Reviewing energy — connecting electrical, thermal, light, and kinetic energy.", "ela": "The isnad — how Muslims verified knowledge through chains of transmission.", "writing": "Isnad reflection: write your own isnad — who taught you what you know?", "ss": "How knowledge survived — the isnad, manuscripts, and libraries."}, "26": {"math": "Geometry — classifying triangles and quadrilaterals by their properties.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Khwarizmi showed that every algebraic statement can be tested — both sides of the equation must balance. What does it mean for a statement to be a claim that can be checked?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "Evidence is always more convincing than argument.", "sci": "Evidence for evolution — the fossil record, anatomy, and DNA.", "ela": "Euclid's proofs — reading the first three propositions.", "writing": "Mathematical proof: choose a simple theorem and write a complete proof.", "ss": "The Islamic transmission to Europe — how the Renaissance began."}, "27": {"math": "Connecting operations — multiplication as repeated addition, fractions as division.", "scholar": "Al-Farabi", "openingQ": "Al-Farabi said that logic is the tool for separating what is actually true from what only seems true. How do you know when you have found real truth rather than convincing yourself?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Self-knowledge is impossible without knowledge of others.", "sci": "Unanswered questions — the scientific frontier in your lifetime.", "ela": "Reflection — the scholar's journey in miniature. How did each scholar grow?", "writing": "Year synthesis: the scholar who most changed your thinking this year.", "ss": "The full arc of Islamic civilisation."}, "28": {"math": "Introduction to Grade 5 concepts — multi-digit decimal operations.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's second great map combined Arab, African, and Greek knowledge into something that had never existed. How do you make something new from things that already exist?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Truly new things are rare — most creativity is recombination.", "sci": "Preview of Grade 5 — Earth systems and life sciences.", "ela": "Reading a text that previews Grade 5 historical content.", "writing": "Forward letter: write a letter to your Grade 5 self.", "ss": "The Ottoman, Safavid, and Mughal empires — Islam after the Golden Age."}, "29": {"math": "Capstone review — selecting and applying the right strategy for complex problems.", "scholar": "Al-Biruni", "openingQ": "Al-Biruni spent years learning Sanskrit so he could translate Indian mathematics. Why do some things worth doing take years?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "The hardest part of any project is finishing it.", "sci": "Science portfolio — selecting and reflecting on your three best investigations.", "ela": "Reading a piece of excellent student writing — what makes it work?", "writing": "Portfolio: your best four pieces with a written introduction.", "ss": "Islamic scholars who changed your world — a personal list."}, "30": {"math": "Capstone problem — a multi-step investigation connecting five concepts.", "scholar": "Al-Battani", "openingQ": "Al-Battani measured the solar year — the time it takes for everything to return to where it began. What returns at the end of a year of learning?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The end of one thing is always the beginning of another.", "sci": "Capstone: a scientific investigation connecting earth, life, and physical science.", "ela": "The full arc of the Islamic Golden Age — creation to transmission.", "writing": "Final essay: the Islamic Golden Age in three paragraphs.", "ss": "The Islamic Golden Age — its gifts to humanity."}}, "6": {"1": {"math": "Ratios and rates — what a ratio means, how to write one, and Al-Idrisi's use of scale.", "scholar": "Al-Idrisi", "openingQ": "What does it mean to create something that did not exist before — and how do you know it is true?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "You cannot understand something you have not made yourself.", "sci": "Introduction to Earth's systems — the four spheres and how they interact.", "ela": "The ancient world and Islam — reading about the Arabian Peninsula before the Prophet.", "writing": "Informational essay: explain the four Earth systems and how they interact.", "ss": "The ancient civilisations — Egypt, Mesopotamia, Greece, Persia — what they built and left."}, "2": {"math": "Equivalent ratios — ratio tables and double number lines. Pattern in proportional relationships.", "scholar": "Al-Biruni", "openingQ": "Why do the same mathematical patterns appear in nature, in music, and in the structure of language?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematical patterns prove that the universe was designed.", "sci": "Matter — atoms, elements, and the periodic table. What patterns govern the elements?", "ela": "The Quran and literacy — how revelation transformed the relationship between Arabs and writing.", "writing": "Reflective essay: why did the revelation 'Iqra' — Read — begin with literacy?", "ss": "The coming of Islam — how a revelation in 7th-century Arabia changed the world."}, "3": {"math": "Unit rates — price per item, speed, and the structure behind comparison.", "scholar": "Ibn Rushd", "openingQ": "What makes a structure strong — in a building, in an argument, in a community?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "The best structures are the simplest ones.", "sci": "Forces and Newton's laws — first, second, third. Structures that balance forces.", "ela": "The first Islamic scholars — why the Prophet's companions began writing things down.", "writing": "Argument: should scientific knowledge be freely shared or can it be owned?", "ss": "The first Islamic community — Makkah, Madinah, and the Hijra."}, "4": {"math": "Dividing fractions — why dividing by ½ gives double the answer. Islamic inheritance mathematics.", "scholar": "Al-Khwarizmi", "openingQ": "Is fair always equal — and can mathematics tell the difference?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Mathematics can solve any problem about fairness.", "sci": "Energy flow in ecosystems — photosynthesis and cellular respiration as opposites.", "ela": "Al-Khwarizmi and the House of Wisdom — reading the historical context.", "writing": "Historical analysis: why did Al-Khwarizmi write his algebra book for anyone, not just mathematicians?", "ss": "The early caliphate — the founding of an Islamic state."}, "5": {"math": "Fraction ÷ fraction — the keep-change-flip algorithm and why it works. Al-Kashi's precision.", "scholar": "Al-Kashi", "openingQ": "What is the difference between an approximation and the truth — and does it always matter?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "The search for perfect precision always produces more understanding than stopping at good enough.", "sci": "Scientific measurement — units of the SI system and when to use each.", "ela": "A text about numbers — how different cultures represented numbers before algebra.", "writing": "Comparative essay: how did different civilisations represent numbers before place value?", "ss": "The Abbasid Golden Age — the most productive period of intellectual history."}, "6": {"math": "Decimal operations — adding, subtracting, multiplying, dividing. Building fluency.", "scholar": "Ibn Khaldun", "openingQ": "How do you know when to trust what you read — and what would a world with no reliable knowledge look like?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "A world with no reliable knowledge would be more equal than the world we live in.", "sci": "Designing controlled experiments — independent, dependent, and controlled variables.", "ela": "Primary source: a fragment from a 9th-century Islamic text on knowledge.", "writing": "Primary source analysis: what does a 9th-century text tell us about how knowledge was valued?", "ss": "Primary source: a fragment from a 9th-century Islamic scholarly text."}, "7": {"math": "Introduction to integers — negative numbers on the number line. Observation requires a direction.", "scholar": "Ibn al-Haytham", "openingQ": "What is the difference between seeing and observing — and why does the difference matter?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "The scientific method is the only reliable path to truth.", "sci": "Ibn al-Haytham — the first controlled experiment. How we know what he did was science.", "ela": "Ibn al-Haytham adapted primary source — his description of the camera obscura.", "writing": "Scientific argument: write Ibn al-Haytham's argument as a formal essay.", "ss": "The scientific revolution and its Islamic roots — who came before Galileo?"}, "8": {"math": "Absolute value — distance from zero. Al-Battani's calculations required knowing distances, not directions.", "scholar": "Al-Battani", "openingQ": "Why is pi the same for every circle everywhere — and what does that tell us about the universe?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Mathematics is discovered, not invented.", "sci": "The solar system — planets, moons, and orbital mechanics. Al-Battani's measurements.", "ela": "The solar system in Islamic astronomy — how Al-Battani refined Ptolemy.", "writing": "Research essay: how did Islamic astronomy improve on Ptolemy?", "ss": "Islamic astronomy — the Muslim scholars who shaped our understanding of the solar system."}, "9": {"math": "Introduction to algebra — writing expressions using variables.", "scholar": "Ibn Sina", "openingQ": "What makes a living system different from a very complicated machine?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "Life is irreducibly different from chemistry.", "sci": "Cells — the basic unit of life. What do all living cells have in common?", "ela": "Ibn Sina on cells — not cells as we know them, but his account of the body's smallest units.", "writing": "Systems explanation: how do the body's systems maintain homeostasis?", "ss": "The Islamic hospital — the world's first public health system."}, "10": {"math": "Solving one-step equations — what value makes both sides equal?", "scholar": "Al-Masudi", "openingQ": "How do you measure change — and what stays constant while everything else transforms?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Everything in the universe is either changing or decaying — nothing is stable.", "sci": "Plate tectonics — how the continents move and what drives them.", "ela": "Reading tectonic plate theory — how scientists built the case over 50 years.", "writing": "Scientific history: how did Alfred Wegener's continental drift theory become accepted?", "ss": "Plate tectonics — how the theory was built and resisted."}, "11": {"math": "Writing and interpreting expressions. What does 3(x + 2) mean?", "scholar": "Hunayn ibn Ishaq", "openingQ": "What is lost and what is gained when knowledge moves from one language to another?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "The Islamic translation movement was the single most important event in the history of ideas.", "sci": "Ecosystems and biodiversity — why does variety matter?", "ela": "An ecosystem text — what happens when wolves are reintroduced to Yellowstone?", "writing": "Ecological argument: should wolves be reintroduced to habitats where they were eliminated?", "ss": "Biodiversity — the variety of life on Earth and its value."}, "12": {"math": "Introduction to inequalities — when the answer is a range, not a single value.", "scholar": "Al-Jahiz", "openingQ": "What is the natural order of things — and what happens when that order is disturbed?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Human beings are part of nature's order, not separate from it.", "sci": "Classification — the tree of life from bacteria to mammals.", "ela": "Taxonomy text — what does it mean to classify all life on Earth?", "writing": "Taxonomic essay: what is classification for and what are its limits?", "ss": "Classification — the tree of life from Al-Jahiz to Linnaeus."}, "13": {"math": "Area of triangles and quadrilaterals. Why is the area of a triangle ½ base × height?", "scholar": "Al-Ghazali", "openingQ": "What is the difference between knowing something and being wise about it?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Knowledge without wisdom is more dangerous than ignorance.", "sci": "Scientific models — what is a model for and when does it fail?", "ela": "A scientific model text — how do models fail and what do we do when they do?", "writing": "Critical evaluation: when is a model useful and when does it mislead?", "ss": "Scientific models — the geocentric model and why it lasted so long."}, "14": {"math": "Area of composite figures. Breaking complex shapes into simple ones.", "scholar": "Jabir ibn Hayyan", "openingQ": "When you give something without expecting return — what does that change about the exchange?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Chemistry is the most fundamental of the sciences.", "sci": "Chemical reactions — reactants, products, and conservation of mass.", "ela": "Jabir ibn Hayyan primary source — the first systematic chemistry notes.", "writing": "Lab report: a quantitative chemistry investigation with full documentation.", "ss": "Chemistry in Islamic scholarship — from Jabir to Lavoisier."}, "15": {"math": "Surface area — how much material to wrap a three-dimensional object?", "scholar": "Ibn al-Nafis", "openingQ": "How do you communicate something you know is true when everyone around you believes something different?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "It is a scientist's duty to communicate their findings to anyone who might be affected by them.", "sci": "Data representation — which graph type for which kind of data?", "ela": "Reading a misleading graph — what does the data actually show?", "writing": "Data literacy: rewrite a misleading graph description accurately.", "ss": "Data and democracy — how statistics shape public policy."}, "16": {"math": "Volume of rectangular prisms. Length × width × height and why.", "scholar": "Al-Tusi", "openingQ": "What cycles do you depend on that you never notice — and what would happen if they stopped?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Cycles in nature are more fundamental than straight-line change.", "sci": "Earth's water cycle — ocean currents and climate.", "ela": "The water cycle as described by Ibn Sina — his account of rain and springs.", "writing": "Ibn Sina's water cycle: analyse his account against modern understanding.", "ss": "The water cycle — Ibn Sina's account vs modern hydrology."}, "17": {"math": "Statistics — understanding variability. Why do measurements of the same thing differ?", "scholar": "Ibn Battuta", "openingQ": "What knowledge did you receive this week from someone who will never know you existed?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "Ibn Battuta's Rihla is the most important document of the medieval Islamic world.", "sci": "Islamic contributions to astronomy — Al-Tusi, Al-Battani, Al-Biruni's measurements.", "ela": "Islamic contributions to astronomy — a survey text covering five scholars.", "writing": "Scholarly survey: five Islamic contributions to astronomy in five paragraphs.", "ss": "Islamic contributions to astronomy — five scholars in one lesson."}, "18": {"math": "Measures of centre — mean, median, and which to use when.", "scholar": "Al-Kashi", "openingQ": "What did you do this week that you would have done differently if you had been fully paying attention?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "The culture of precision in Islamic scholarship was the most important factor in its success.", "sci": "Precision in science — significant figures and why they matter.", "ela": "Significant figures — why does precision in writing numbers matter?", "writing": "Precision essay: explain significant figures to someone who does not understand why they matter.", "ss": "Precision in Islamic scholarship — the culture of exact knowledge."}, "19": {"math": "Measures of spread — range and mean absolute deviation.", "scholar": "Ibn Majid", "openingQ": "Where this week did you encounter something larger than your frameworks could contain?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "The Islamic navigational tradition was indispensable to the European Age of Exploration.", "sci": "Biomes and climate — how do global temperature patterns create different environments?", "ela": "Reading about biomes — describing the Amazon rainforest.", "writing": "Descriptive essay: the Amazon rainforest — what is there and why does it matter?", "ss": "The Islamic world at its peak — from Spain to Central Asia."}, "20": {"math": "Displaying data — histograms and box plots.", "scholar": "Al-Jazari", "openingQ": "What did you receive this week that enabled you to do what you were trying to do?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Al-Jazari's Book of Mechanical Devices was the most important engineering text before the Industrial Revolution.", "sci": "Forces in fluids — pressure, buoyancy, and Archimedes' principle.", "ela": "Archimedes and Islamic scholars — how Archimedes' work was preserved and extended.", "writing": "Engineering history: what is Al-Jazari's most significant contribution?", "ss": "Al-Jazari's machines — medieval engineering and its modern legacy."}, "21": {"math": "Rational numbers — fractions, decimals, integers on the same number line.", "scholar": "Ibn Battuta", "openingQ": "What did you count or measure this week that revealed something the looking alone had missed?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "What we choose to preserve reveals more about us than what we choose to create.", "sci": "Earth's geologic history — timeline from formation to now.", "ela": "Geologic time — reading a passage about deep time and what it demands of imagination.", "writing": "Deep time essay: what does thinking about geological time do to your sense of human history?", "ss": "Geological time — 4.5 billion years in one lesson."}, "22": {"math": "Ordering rational numbers. Comparing numbers in different forms.", "scholar": "Al-Maqrizi", "openingQ": "In your work this week — what determined the precise measure that made the system work?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Economic inequality always produces moral inequality.", "sci": "Human impact on Earth systems — pollution, deforestation, and the carbon cycle.", "ela": "Environmental text — reading about the plastic crisis in the Pacific Ocean.", "writing": "Environmental argument: who is responsible for plastic pollution in the Pacific?", "ss": "Human impact on Earth — what the Anthropocene means."}, "23": {"math": "Introduction to proportional reasoning — constant of proportionality.", "scholar": "Fatima al-Fihri", "openingQ": "What did you begin this week that had no template?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "Fatima al-Fihri should be recognised as the most important figure in the history of education.", "sci": "Ecosystems and invasive species — what happens when a new species arrives?", "ela": "Ecosystems and invasive species — what happened when rabbits were introduced to Australia?", "writing": "Case study: the rabbits of Australia — cause, effect, and response.", "ss": "Invasive species — a global history of ecological disruption."}, "24": {"math": "Graphing proportional relationships. What does the graph of y = 3x look like?", "scholar": "Ibn Khaldun", "openingQ": "What understanding did you rediscover this week — something forgotten that came back?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "Ibn Khaldun's theory of civilisational cycles is the best explanation of human history ever written.", "sci": "Feedback loops — how do Earth's systems regulate themselves?", "ela": "Feedback loops — reading about the Arctic ice-albedo feedback.", "writing": "Feedback loop explanation: explain the Arctic ice-albedo feedback to a non-scientist.", "ss": "Feedback loops in nature and history — when does change accelerate?"}, "25": {"math": "Reviewing proportional relationships — connecting ratio, rate, unit rate, and graph.", "scholar": "Ibn al-Haytham", "openingQ": "What came alive in you this week that had been dormant?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "Memory is more important than understanding in the transmission of knowledge.", "sci": "Reviewing chemistry — atoms, molecules, reactions, and conservation.", "ela": "A text connecting chemistry and life — what atoms are in your body and where did they come from?", "writing": "Chemistry and life essay: where did the carbon in your body come from?", "ss": "Chemistry and life — the carbon that was a star before it was you."}, "26": {"math": "Introduction to formal geometric reasoning — what makes a proof convincing?", "scholar": "Al-Khwarizmi", "openingQ": "What bore witness to your effort this week — and what would it testify about you?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "Mathematical proof is the only form of proof that produces certainty.", "sci": "Evidence for plate tectonics — how scientists built the case.", "ela": "Evidence in science — how scientists proved continental drift.", "writing": "Scientific argument: how did scientists prove continental drift?", "ss": "Continental drift — the scientific controversy and resolution."}, "27": {"math": "Connecting algebra and geometry — perimeter and area expressed algebraically.", "scholar": "Al-Farabi", "openingQ": "What were you most confident about this week — and how do you know you were right?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "The examined life — knowing yourself — is more valuable than any external knowledge.", "sci": "Open questions in Earth science — what remains unknown.", "ela": "Open questions in science — a text about what researchers currently do not understand.", "writing": "Research question: write a scientific question you would want to investigate.", "ss": "What we do not know — the frontier of Earth science."}, "28": {"math": "Introduction to Grade 7 concepts — percent, scale, and probability.", "scholar": "Al-Idrisi", "openingQ": "What did you create this week that did not exist before?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Human creativity can produce something genuinely new — not just recombination.", "sci": "Preview of Grade 7 — life science and body systems.", "ela": "Preview reading — what is Grade 7 life science going to be about?", "writing": "Preview essay: what are the big questions in Grade 7 life science?", "ss": "Preview of Grade 7 history — life science and civilisation."}, "29": {"math": "Extended investigation — a real-world ratio and proportion problem.", "scholar": "Al-Biruni", "openingQ": "What did you have to wait for this week — and what did the waiting teach you?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Patience is the most undervalued intellectual virtue.", "sci": "Extended investigation — a multi-week data collection project completed.", "ela": "Reading scientific writing — what does a good methods section look like?", "writing": "Methods analysis: evaluate the methods section of a scientific paper.", "ss": "The scientific paper — how knowledge becomes public."}, "30": {"math": "Capstone: what does proportional thinking allow us to do that we couldn't do before?", "scholar": "Al-Battani", "openingQ": "What was the first question you carried into this year — and what question do you carry forward?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "A year of learning that raises more questions than it answers has failed.", "sci": "Capstone: connecting Earth systems, chemistry, and life science.", "ela": "A synthesis text — how Earth systems, chemistry, and life connect.", "writing": "Synthesis essay: connect Earth systems, chemistry, and life in three pages.", "ss": "Everything connects — Earth, chemistry, and life as one system."}}, "8": {"1": {"math": "Functions — what a function is, and how Al-Idrisi's maps encode functional relationships.", "scholar": "Al-Idrisi", "openingQ": "What does it mean to create something that did not exist before — and how do you know it is true?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "You cannot understand something you have not made yourself.", "sci": "Matter and atoms — the structure of the atom and its discovery.", "ela": "The atom — the story of how we found out what matter is made of.", "writing": "Scientific history: tell the story of how we discovered what atoms are made of.", "ss": "The atom in history — from Democritus to the nuclear age."}, "2": {"math": "Representing functions — tables, graphs, equations, and verbal descriptions.", "scholar": "Al-Biruni", "openingQ": "Why do the same mathematical patterns appear in nature, in music, and in the structure of language?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematical patterns prove that the universe was designed.", "sci": "Periodic table — patterns of elements by mass and reactivity.", "ela": "The periodic table — reading Mendeleev's original paper on the missing elements.", "writing": "Primary source analysis: what did Mendeleev predict and how did he know?", "ss": "Mendeleev's prediction — how a pattern predicted undiscovered elements."}, "3": {"math": "Linear functions — slope and y-intercept. What does each tell you?", "scholar": "Ibn Rushd", "openingQ": "What makes a structure strong — in a building, in an argument, in a community?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "The best structures are the simplest ones.", "sci": "Chemical bonding — ionic and covalent bonds. Structure determines behaviour.", "ela": "Chemical bonding — a text explaining why water is a liquid at room temperature.", "writing": "Molecular explanation: why is water a liquid at room temperature but oxygen a gas?", "ss": "The chemical bond and materials history — how chemistry shaped industry."}, "4": {"math": "Slope from two points — rise ÷ run. The mathematics of gradient as distribution.", "scholar": "Al-Khwarizmi", "openingQ": "Is fair always equal — and can mathematics tell the difference?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Mathematics can solve any problem about fairness.", "sci": "Chemical reactions — types and conservation of mass and energy.", "ela": "Conservation of mass — Lavoisier's experiment and why it mattered.", "writing": "Historical argument: why was Lavoisier's conservation of mass experiment revolutionary?", "ss": "Lavoisier and the French Revolution — science and politics."}, "5": {"math": "Comparing linear functions. Which is steeper? Which grows faster?", "scholar": "Al-Kashi", "openingQ": "What is the difference between an approximation and the truth — and does it always matter?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "The search for perfect precision always produces more understanding than stopping at good enough.", "sci": "Acids and bases — what determines pH? Jabir ibn Hayyan's discoveries.", "ela": "Jabir ibn Hayyan — primary source. His description of a distillation process.", "writing": "Primary source analysis: what does Jabir's distillation procedure reveal about his method?", "ss": "Jabir ibn Hayyan — the Islamic founder of chemistry."}, "6": {"math": "Systems of linear equations — two lines, one intersection.", "scholar": "Ibn Khaldun", "openingQ": "How do you know when to trust what you read — and what would a world with no reliable knowledge look like?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "A world with no reliable knowledge would be more equal than the world we live in.", "sci": "Designing chemistry experiments — controlling contamination and error.", "ela": "Experimental design in chemistry — what makes a chemistry experiment valid?", "writing": "Experimental design essay: design a valid chemistry experiment with full controls.", "ss": "Chemistry and warfare — from gunpowder to nerve agents."}, "7": {"math": "Solving systems by substitution and elimination.", "scholar": "Ibn al-Haytham", "openingQ": "What is the difference between seeing and observing — and why does the difference matter?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "The scientific method is the only reliable path to truth.", "sci": "Ibn al-Haytham's optics in detail — diffraction, refraction, and the eye.", "ela": "Ibn al-Haytham's optics — the original argument, adapted. How he proved the eye receives light.", "writing": "Scientific argument: write Ibn al-Haytham's case against Ptolemy's emission theory.", "ss": "Ibn al-Haytham — the man who invented the scientific method."}, "8": {"math": "Pythagorean theorem — a² + b² = c². Connecting algebra and geometry. Al-Battani used this for astronomy.", "scholar": "Al-Battani", "openingQ": "Why is pi the same for every circle everywhere — and what does that tell us about the universe?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "Mathematics is discovered, not invented.", "sci": "Forces — Newton's laws reviewed and extended. Gravity as an inverse-square force.", "ela": "Newton's third law — a text about rockets and why they work.", "writing": "Physics explanation: explain Newton's third law using a rocket as your example.", "ss": "The rocket — from Chinese gunpowder to space exploration."}, "9": {"math": "Applications of the Pythagorean theorem — distance in the coordinate plane.", "scholar": "Ibn Sina", "openingQ": "What makes a living system different from a very complicated machine?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "Life is irreducibly different from chemistry.", "sci": "Energy — kinetic and potential, thermal and chemical. Conservation of energy.", "ela": "Conservation of energy — a text about the energy in a falling ball.", "writing": "Energy essay: follow the energy in a falling rock from height to sound.", "ss": "The conservation of energy — from steam engines to nuclear power."}, "10": {"math": "Introduction to non-linear functions — what makes a function non-linear?", "scholar": "Al-Masudi", "openingQ": "How do you measure change — and what stays constant while everything else transforms?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Everything in the universe is either changing or decaying — nothing is stable.", "sci": "Thermal energy — heat transfer by conduction, convection, and radiation.", "ela": "Heat transfer — a text about why a metal spoon in hot coffee burns faster than a wooden one.", "writing": "Comparative analysis: why does metal feel colder than wood at the same temperature?", "ss": "The Industrial Revolution and thermal energy."}, "11": {"math": "Irrational numbers — what is √2? Why it cannot be written as a fraction.", "scholar": "Hunayn ibn Ishaq", "openingQ": "What is lost and what is gained when knowledge moves from one language to another?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "The Islamic translation movement was the single most important event in the history of ideas.", "sci": "Waves — electromagnetic spectrum from radio to gamma rays.", "ela": "The electromagnetic spectrum — a text about invisible light.", "writing": "Research essay: which part of the electromagnetic spectrum has the most impact on daily life?", "ss": "The electromagnetic spectrum and communication."}, "12": {"math": "Scientific notation — writing very large and very small numbers.", "scholar": "Al-Jahiz", "openingQ": "What is the natural order of things — and what happens when that order is disturbed?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Human beings are part of nature's order, not separate from it.", "sci": "Sound — wave properties, resonance, and acoustic design in mosques.", "ela": "Sound in Islamic architecture — how mosque acoustics were designed for the call to prayer.", "writing": "Architectural analysis: how does mosque acoustic design reflect sound physics?", "ss": "The acoustics of sacred architecture — mosques, cathedrals, and concert halls."}, "13": {"math": "Operations with numbers in scientific notation.", "scholar": "Al-Ghazali", "openingQ": "What is the difference between knowing something and being wise about it?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Knowledge without wisdom is more dangerous than ignorance.", "sci": "Scientific models in chemistry — molecular models and their limitations.", "ela": "A chemistry model — what does a molecular model tell us and what does it hide?", "writing": "Model critique: what does a molecular model tell us and what does it hide?", "ss": "Chemical models and their cultural bias."}, "14": {"math": "Geometric transformations — translation, rotation, reflection, dilation.", "scholar": "Jabir ibn Hayyan", "openingQ": "When you give something without expecting return — what does that change about the exchange?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Chemistry is the most fundamental of the sciences.", "sci": "Organic chemistry — carbon compounds and the molecules of life.", "ela": "Organic chemistry — a text about why carbon is the molecule of life.", "writing": "Biochemistry essay: why is carbon the molecule of life?", "ss": "Carbon — the element that makes life possible and threatens it."}, "15": {"math": "Congruence — when are two shapes exactly the same?", "scholar": "Ibn al-Nafis", "openingQ": "How do you communicate something you know is true when everyone around you believes something different?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "It is a scientist's duty to communicate their findings to anyone who might be affected by them.", "sci": "Science and technology — how does a solar panel work?", "ela": "Science and society — how solar panels work and why they matter.", "writing": "Policy essay: should solar panels be mandatory on new buildings?", "ss": "The solar panel — from Einstein's photoelectric effect to renewable energy."}, "16": {"math": "Similarity — when are two shapes the same shape but different size?", "scholar": "Al-Tusi", "openingQ": "What cycles do you depend on that you never notice — and what would happen if they stopped?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Cycles in nature are more fundamental than straight-line change.", "sci": "Earth's magnetic field — why does a compass point north?", "ela": "The Earth's magnetic field — a text about what would happen if it disappeared.", "writing": "Scenario writing: what would happen to Earth's biosphere without a magnetic field?", "ss": "The Earth's magnetic field and navigation throughout history."}, "17": {"math": "Angles in triangles and the exterior angle theorem.", "scholar": "Ibn Battuta", "openingQ": "What knowledge did you receive this week from someone who will never know you existed?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "Ibn Battuta's Rihla is the most important document of the medieval Islamic world.", "sci": "Islamic contributions to chemistry and optics — Jabir, Ibn al-Haytham, Al-Kindi.", "ela": "Jabir and Al-Kindi — two Islamic scholars who shaped chemistry and optics.", "writing": "Comparative biography: Jabir ibn Hayyan and Antoine Lavoisier — similarities and differences.", "ss": "Islamic contributions to chemistry and optics."}, "18": {"math": "Volume of cylinders, cones, and spheres. Al-Kashi calculated these for astronomical models.", "scholar": "Al-Kashi", "openingQ": "What did you do this week that you would have done differently if you had been fully paying attention?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "The culture of precision in Islamic scholarship was the most important factor in its success.", "sci": "Measurement in chemistry — moles, molarity, and significant figures.", "ela": "Moles — why chemists invented a very large number for very small things.", "writing": "Conceptual explanation: explain the mole to someone who thinks it is only an animal.", "ss": "The mole — how chemistry moved from observation to precision."}, "19": {"math": "Scatter plots — what does the data suggest about the relationship?", "scholar": "Ibn Majid", "openingQ": "Where this week did you encounter something larger than your frameworks could contain?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "The Islamic navigational tradition was indispensable to the European Age of Exploration.", "sci": "Environmental chemistry — what happens to plastic in the ocean?", "ela": "Plastic and the ocean — a detailed text about polymer chemistry in the environment.", "writing": "Environmental argument: should manufacturers be liable for plastic that enters the ocean?", "ss": "Plastics — the greatest material invention and the worst pollution crisis."}, "20": {"math": "Lines of best fit — modelling a trend in data.", "scholar": "Al-Jazari", "openingQ": "What did you receive this week that enabled you to do what you were trying to do?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "Al-Jazari's Book of Mechanical Devices was the most important engineering text before the Industrial Revolution.", "sci": "Newton's laws in engineering — bridges, arches, and tension.", "ela": "Engineering in the Islamic world — Al-Jazari's inventions and their modern descendants.", "writing": "Engineering analysis: which of Al-Jazari's inventions had the most lasting influence?", "ss": "Islamic engineering — Al-Jazari and the mechanical tradition."}, "21": {"math": "Two-way tables — reading data with two categorical variables.", "scholar": "Ibn Battuta", "openingQ": "What did you count or measure this week that revealed something the looking alone had missed?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "What we choose to preserve reveals more about us than what we choose to create.", "sci": "History of atomic theory — from Dalton to Bohr to quantum.", "ela": "The history of atomic theory — from Dalton to quantum, reading the story.", "writing": "History of science essay: from Dalton to Bohr — how did the atomic model change?", "ss": "The atomic age — from Rutherford to Hiroshima."}, "22": {"math": "Introduction to quadratic functions — y = x².", "scholar": "Al-Maqrizi", "openingQ": "In your work this week — what determined the precise measure that made the system work?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Economic inequality always produces moral inequality.", "sci": "Chemical reactions and the environment — combustion and the carbon cycle.", "ela": "Combustion and the carbon cycle — reading about the chemistry of climate change.", "writing": "Climate chemistry essay: explain why burning fossil fuels changes the atmosphere.", "ss": "The carbon cycle and the fossil fuel industry."}, "23": {"math": "Comparing linear, quadratic, and exponential growth.", "scholar": "Fatima al-Fihri", "openingQ": "What did you begin this week that had no template?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "Fatima al-Fihri should be recognised as the most important figure in the history of education.", "sci": "Nuclear energy — fission, fusion, and radioactive decay.", "ela": "Nuclear energy — a balanced text about the science and the politics.", "writing": "Debate essay: is nuclear energy a solution to climate change or a problem?", "ss": "Nuclear power — the history, the physics, and the politics."}, "24": {"math": "Solving quadratic equations by inspection and factoring.", "scholar": "Ibn Khaldun", "openingQ": "What understanding did you rediscover this week — something forgotten that came back?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "Ibn Khaldun's theory of civilisational cycles is the best explanation of human history ever written.", "sci": "Complex chemical systems — how do catalysts change reaction rates?", "ela": "Catalysis — reading about enzymes and industrial catalysts as the same principle.", "writing": "Conceptual essay: explain catalysis using enzymes and industrial examples.", "ss": "The chemical industry — from beneficial to polluting."}, "25": {"math": "Reviewing functions — linear, non-linear, and the difference.", "scholar": "Ibn al-Haytham", "openingQ": "What came alive in you this week that had been dormant?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "Memory is more important than understanding in the transmission of knowledge.", "sci": "Reviewing waves — connecting sound, light, and electromagnetic radiation.", "ela": "The electromagnetic spectrum across cultures — who first studied each part?", "writing": "Cultural history: who first studied each part of the electromagnetic spectrum?", "ss": "The electromagnetic spectrum in Islamic astronomy."}, "26": {"math": "Proving the Pythagorean theorem — three different proofs.", "scholar": "Al-Khwarizmi", "openingQ": "What bore witness to your effort this week — and what would it testify about you?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "Mathematical proof is the only form of proof that produces certainty.", "sci": "Building a scientific argument in chemistry — claim, evidence, reasoning.", "ela": "Scientific argument — reading the original paper proposing the ozone hole.", "writing": "Argument analysis: what made the ozone hole paper convincing to other scientists?", "ss": "The ozone layer — science, politics, and international agreement."}, "27": {"math": "Connecting algebra, geometry, and functions across the year.", "scholar": "Al-Farabi", "openingQ": "What were you most confident about this week — and how do you know you were right?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "The examined life — knowing yourself — is more valuable than any external knowledge.", "sci": "Open questions in chemistry — what we still do not understand.", "ela": "Open questions in chemistry and physics — what is dark matter?", "writing": "Research proposal: what question in physics or chemistry would you most want answered?", "ss": "Open questions in chemistry and physics."}, "28": {"math": "Introduction to high school algebra — formal structure and proof.", "scholar": "Al-Idrisi", "openingQ": "What did you create this week that did not exist before?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Human creativity can produce something genuinely new — not just recombination.", "sci": "Preview of Grade 9 — biology at the molecular level.", "ela": "Preview of Grade 9 biology — what is molecular biology?", "writing": "Preview essay: how is molecular biology different from the biology you already know?", "ss": "Preview of Grade 9 molecular biology."}, "29": {"math": "Extended investigation — modelling a real-world situation with a function.", "scholar": "Al-Biruni", "openingQ": "What did you have to wait for this week — and what did the waiting teach you?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Patience is the most undervalued intellectual virtue.", "sci": "Extended chemistry investigation — quantitative results and error analysis.", "ela": "Reading a chemistry lab report — what makes the methods section convincing?", "writing": "Methods evaluation: what makes the methods section of a chemistry paper convincing?", "ss": "Scientific publication — how chemistry research becomes knowledge."}, "30": {"math": "Capstone: functions, the Pythagorean theorem, and transformation geometry.", "scholar": "Al-Battani", "openingQ": "What was the first question you carried into this year — and what question do you carry forward?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "A year of learning that raises more questions than it answers has failed.", "sci": "Capstone: a chemistry investigation connecting matter, energy, and waves.", "ela": "A synthesis text — matter, energy, waves, and the connection between them.", "writing": "Capstone essay: connect matter, energy, and waves in one sustained argument.", "ss": "The history of matter — what chemistry has taught us about the universe."}}, "9": {"1": {"math": "Real number system — classifying, ordering, and computing. Al-Idrisi's precision required real numbers.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's map was wrong in places and still the most accurate of its time. When is a flawed creation better than no creation?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A flawed creation that exists is worth more than a perfect creation that does not.", "sci": "The cell revisited — molecular biology. What happens inside a cell every second?", "ela": "The cell as a city — a literary text about what happens inside a cell.", "writing": "Metaphor analysis: is the cell-as-city metaphor useful or misleading?", "ss": "Molecular biology and inequality — who has access to genetic medicine?"}, "2": {"math": "Properties of real numbers — commutative, associative, distributive. Patterns as algebraic laws.", "scholar": "Al-Biruni", "openingQ": "Is a pattern a property of the world, or a property of the mind that perceives it?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is discovered, not invented — its truths exist independent of human minds.", "sci": "DNA structure — the double helix and how it stores information.", "ela": "Watson and Crick's 1953 paper — one page, changing everything.", "writing": "Primary source analysis: what made Watson and Crick's 1953 paper a landmark?", "ss": "Watson, Crick, and Franklin — the history and the injustice."}, "3": {"math": "Algebraic expressions — writing, evaluating, simplifying. The structural foundation.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd believed reason and revelation share a foundation. What holds your own beliefs together?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "Reason and revelation cannot contradict each other — when they appear to, one of them is wrong.", "sci": "DNA replication — how cells copy their genetic code before dividing.", "ela": "DNA replication — reading a description of the machinery that copies three billion base pairs.", "writing": "Explanatory essay: explain DNA replication to a non-specialist.", "ss": "DNA replication and the pharmaceutical industry."}, "4": {"math": "Solving linear equations — one variable, multi-step. Al-Khwarizmi's original method.", "scholar": "Al-Khwarizmi", "openingQ": "Islamic inheritance law gives daughters half what sons receive. Al-Khwarizmi built algebra to calculate it precisely. What does precision in an unjust system produce?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Precision in an unjust system makes the injustice worse, not better.", "sci": "Protein synthesis — from DNA to RNA to protein. The central dogma.", "ela": "The central dogma — reading about how information flows in one direction only.", "writing": "Conceptual essay: why does information flow only in one direction in molecular biology?", "ss": "The central dogma and genetic determinism."}, "5": {"math": "Solving linear equations with fractions and decimals. Al-Kashi's motivation for decimal precision.", "scholar": "Al-Kashi", "openingQ": "All scientific measurement contains error. Does that mean science only produces approximations, never truth?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "All scientific measurement is approximation — therefore science never achieves truth, only usefulness.", "sci": "Enzymes — biological catalysts and the precision of metabolic pathways.", "ela": "Enzymes — reading about how the wrong shape is the right answer.", "writing": "Metaphor critique: is the lock-and-key model of enzymes the best available metaphor?", "ss": "Enzymes and biotechnology."}, "6": {"math": "Solving inequalities and graphing solution sets on a number line.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun invented the scientific study of history. What assumptions do you have to make before you can trust any source at all?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "All historical sources are biased — therefore historical truth is impossible.", "sci": "Cell division — mitosis and meiosis. When and why each occurs.", "ela": "Cell division — reading about Henrietta Lacks and the HeLa cell line.", "writing": "Ethics essay: who owns HeLa cells — Henrietta Lacks's family or the scientific community?", "ss": "HeLa cells — consent, race, and medical ethics."}, "7": {"math": "Introduction to functions — domain, range, function notation f(x).", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham said: do not trust any result until you have tested it yourself. What would it cost you to apply that principle to everything you believe?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Ibn al-Haytham's experimental method is the most important intellectual invention in human history.", "sci": "Genetics and Mendel — pedigrees, ratios, and probability.", "ela": "Mendel's original paper — the monk in the garden and what he counted.", "writing": "Primary source analysis: close reading of one paragraph from Mendel's paper.", "ss": "Mendel and the monastery — how science can happen anywhere."}, "8": {"math": "Linear functions — slope, y-intercept, standard form, slope-intercept form.", "scholar": "Al-Battani", "openingQ": "Al-Battani used circles to map the heavens. Al-Muhit surrounds all existence. Is the circle a mathematical fact, a physical reality, or a spiritual symbol — or all three at once?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "The unreasonable effectiveness of mathematics in describing the physical world requires explanation.", "sci": "Chromosomal inheritance — sex-linked traits and chromosomal disorders.", "ela": "Chromosomal inheritance — reading about the discovery of sex-linked traits.", "writing": "Historical argument: why was the discovery of sex-linked inheritance significant?", "ss": "Sex and science — the history of sex-linked trait research."}, "9": {"math": "Graphing linear equations and writing equations of lines.", "scholar": "Ibn Sina", "openingQ": "Al-Latif is the subtly kind — care that arrives before it is asked for. Is there a parallel between divine providence and the self-regulating systems of living organisms?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "There is no fundamental difference between a living organism and a very complicated machine.", "sci": "Molecular genetics — mutations, gene expression, and regulation.", "ela": "Gene regulation — reading about how genes are switched on and off.", "writing": "Regulatory genetics essay: explain how the lac operon works as a regulatory system.", "ss": "Gene regulation — the science of how identity is constructed."}, "10": {"math": "Systems of equations — graphical, substitution, elimination methods.", "scholar": "Al-Masudi", "openingQ": "Al-Halim is the forbearing — unchanged by provocation. In a world where everything changes, what is the value of constancy?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Al-Halim's forbearance in the face of change is the highest possible response to existence.", "sci": "Evolution at the molecular level — how DNA evidence supports evolution.", "ela": "Molecular evolution — reading about how DNA evidence resolved the human family tree.", "writing": "Phylogenetics essay: how did DNA evidence change the human family tree?", "ss": "Human evolution — the full story from Africa."}, "11": {"math": "Introduction to polynomial arithmetic — adding and subtracting polynomials.", "scholar": "Hunayn ibn Ishaq", "openingQ": "The Quran is untranslatable — its meaning depends on its Arabic. Hunayn translated Greek science into Arabic and saved it. What is the relationship between language and truth?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "A translation that changes the meaning to be truer to the target language is more faithful than one that preserves the words.", "sci": "Population genetics — allele frequencies and Hardy-Weinberg equilibrium.", "ela": "Hardy-Weinberg — reading the original population genetics paper, adapted.", "writing": "Mathematical biology essay: explain Hardy-Weinberg equilibrium and what violates it.", "ss": "Population genetics and human diversity."}, "12": {"math": "Multiplying polynomials — the distributive property extended. Foil as a structure.", "scholar": "Al-Jahiz", "openingQ": "Al-Ghafur covers and conceals wrongdoing. In ecology, a disturbed system tries to restore equilibrium. Is the desire for order a property of nature, or of mind?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Al-Jahiz's proto-evolutionary ideas were more advanced than the Islamic scholarly tradition gave him credit for.", "sci": "Speciation — how does one species become two?", "ela": "Speciation — reading about the cichlids of Lake Victoria.", "writing": "Speciation essay: explain the cichlid fish of Lake Victoria as a case of speciation.", "ss": "Speciation — how geography creates new species."}, "13": {"math": "Factoring polynomials — GCF, difference of squares, trinomials.", "scholar": "Al-Ghazali", "openingQ": "Al-Hakim is the all-wise. Al-Ghazali argued that Islamic scholars had confused knowledge with wisdom. What is the difference, and can a person have one without the other?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Al-Ghazali's critique of philosophy was itself philosophical — therefore his critique failed.", "sci": "Ecology — population dynamics, carrying capacity, and logistic growth.", "ela": "Ecology — reading Aldo Leopold's Sand County Almanac, an excerpt.", "writing": "Environmental ethics: analyse Leopold's land ethic — do you agree?", "ss": "Environmental ethics — from Leopold to the present."}, "14": {"math": "Quadratic equations — introduction, standard form, graphing parabolas.", "scholar": "Jabir ibn Hayyan", "openingQ": "Al-Wadud is love that gives without requiring lovability in return. Jabir built chemistry on sharing method. Is generosity in knowledge the same as generosity in love?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Jabir ibn Hayyan's systematic experimentation made him the true founder of modern science — not Galileo or Newton.", "sci": "Biochemistry of ecosystems — decomposition, the nitrogen cycle.", "ela": "The nitrogen cycle — reading about the Haber process and its consequences.", "writing": "Environmental impact essay: evaluate the consequences of the Haber process.", "ss": "The Haber process — the greatest agricultural achievement and its environmental cost."}, "15": {"math": "Solving quadratic equations by factoring and the zero-product property.", "scholar": "Ibn al-Nafis", "openingQ": "Al-Qawiyy is strength — but the Prophet ﷺ said the strongest person is not the one who wins fights but the one who controls themselves when angry. What is the strongest form of communication?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Ibn al-Nafis was morally obliged to publish his discovery of pulmonary circulation even at the risk of his life.", "sci": "Scientific literature — reading and evaluating primary research in biology.", "ela": "How to read a scientific paper — structure, claims, and red flags.", "writing": "Research literacy: evaluate a scientific paper for claim, evidence, and significance.", "ss": "Open access — should scientific research be freely available?"}, "16": {"math": "The quadratic formula. Where it comes from and why it always works.", "scholar": "Al-Tusi", "openingQ": "Al-Waliyy is the protecting friend — the guardian who sustains cycles of care invisibly. Is it possible to understand a system from the inside, while you are sustained by it?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Al-Tusi's mathematical model was more important than Copernicus's heliocentric theory.", "sci": "Evolutionary cycles — extinction and radiation events.", "ela": "Mass extinction — reading about the end-Cretaceous event and what survived.", "writing": "Mass extinction essay: what does the end-Cretaceous event tell us about resilience?", "ss": "Mass extinction events — what the geological record tells us."}, "17": {"math": "Introduction to exponential functions — y = ab^x. Growth and decay.", "scholar": "Ibn Battuta", "openingQ": "Al-Karim gives before being asked. The Islamic scholarly tradition flows through isnad chains — named people giving named people what was given to them. What do you owe to people you have never met?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The Islamic scholarly tradition was more advanced than European scholarship in every field until at least 1400 CE.", "sci": "History of genetics — from Mendel to the Human Genome Project.", "ela": "The Human Genome Project — reading about what we found and what we did not find.", "writing": "Policy essay: who should decide how CRISPR technology is used?", "ss": "The Human Genome Project — ambitions, findings, and failures."}, "18": {"math": "Comparing linear, quadratic, and exponential models. Which fits the data?", "scholar": "Al-Kashi", "openingQ": "Al-Raqib watches every act and every intention. Precision is a form of attention. What is the relationship between being watched and doing careful work?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Al-Kashi's contributions to mathematics were as significant as Al-Khwarizmi's, and the neglect of his legacy is itself a form of injustice.", "sci": "Experimental design in biology — controls, replication, and statistical significance.", "ela": "Ethics in biology — reading about CRISPR and who should decide its uses.", "writing": "Research ethics essay: was the Human Genome Project conducted ethically?", "ss": "Bioethics — how should humans use genetic technology?"}, "19": {"math": "Introduction to statistics — regression lines and correlation.", "scholar": "Ibn Majid", "openingQ": "Al-Wasi is spacious beyond all measure. Every expanding understanding requires letting go of the frame that used to contain it. What do you have to give up in order to understand something genuinely new?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Ibn Majid's guidance of Vasco da Gama was an act that damaged the Islamic world more than any Mongol invasion.", "sci": "Human population ecology — demographic transition and resource use.", "ela": "Population ecology — reading about demographic transition in different countries.", "writing": "Demographic essay: explain demographic transition theory and its limitations.", "ss": "Population growth — the most important trend in human history."}, "20": {"math": "Systems of linear inequalities — graphing solution regions.", "scholar": "Al-Jazari", "openingQ": "Al-Muqit provides the precise nourishment each thing needs to be itself fully. Is a tool that extends your capability also extending your nature — or replacing part of it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "A machine that automates a decision is fundamentally different from a machine that automates a physical task.", "sci": "Biomechanics — forces on the skeleton and muscles.", "ela": "Biomechanics — reading about how a cheetah's skeleton enables speed.", "writing": "Biomechanics analysis: what skeletal and muscular features make a cheetah fast?", "ss": "Sport science — biomechanics, performance, and fairness."}, "21": {"math": "Radicals and rational exponents — √x and x^½ are the same.", "scholar": "Ibn Battuta", "openingQ": "Al-Hasib is the reckoner — every atom accounted for. Heritage is what we choose to count. What gets lost from history when we do not measure it carefully?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The destruction of the Abbasid library by the Mongols was the single greatest loss in intellectual history.", "sci": "Conservation biology — measuring biodiversity and managing endangered species.", "ela": "Conservation — reading about the rewilding of Scotland.", "writing": "Conservation essay: argue for a specific rewilding project.", "ss": "Conservation — who gets to decide what we protect?"}, "22": {"math": "Introduction to sequences — arithmetic and geometric. Al-Khwarizmi's iterative approach.", "scholar": "Al-Maqrizi", "openingQ": "Al-Muqaddir decrees exact measures. Al-Maqrizi documented exact economic injustice. Is measurement in the service of justice the same as measurement in the service of efficiency?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Al-Maqrizi's economic analysis of the Mamluk crisis is more important to read today than any modern economics textbook.", "sci": "Environmental biology — how toxins move through food webs (bioaccumulation).", "ela": "Bioaccumulation — reading about DDT and the bald eagle.", "writing": "Environmental justice essay: who suffers most from bioaccumulation and why?", "ss": "Environmental racism — the global history of pollution and inequality."}, "23": {"math": "Introduction to probability with combinatorics — counting systematically.", "scholar": "Fatima al-Fihri", "openingQ": "Al-Mubdi originates without model or precedent. Fatima al-Fihri began al-Qarawiyyin — the oldest continuously operating university — 1200 years ago. What does it take to create an institution rather than just a building?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "The university system — which began at al-Qarawiyyin — has done more harm than good to human knowledge.", "sci": "Biotechnology — CRISPR, genetic modification, and their ethics.", "ela": "CRISPR — reading the original Jennifer Doudna paper, heavily adapted.", "writing": "Technology ethics: should CRISPR be used to eliminate inherited diseases in embryos?", "ss": "CRISPR and human nature — what should biology change?"}, "24": {"math": "Data analysis — interpreting models and their limitations.", "scholar": "Ibn Khaldun", "openingQ": "Al-Muid is the restorer — nothing truly lost, only waiting to be brought back. Is restoration the same as creation, or something different?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "The Islamic Golden Age ended because its social complexity exceeded its institutional capacity — and the same is true of every fallen civilisation.", "sci": "Systems biology — how does a cell regulate itself as a whole?", "ela": "Systems biology — reading about how a bacterium decides what to do.", "writing": "Systems biology essay: explain how a bacterium integrates environmental signals.", "ss": "Systems thinking — the philosophy behind systems biology."}, "25": {"math": "Reviewing the year — the structure of algebra as a system.", "scholar": "Ibn al-Haytham", "openingQ": "Al-Muhyi gives life not only to bodies but to hearts — through knowledge, through remembrance. What is the difference between information and living knowledge?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The Islamic tradition of oral transmission — memorisation before understanding — produced better scholars than the modern tradition of written analysis.", "sci": "Reviewing genetics — from Mendel through molecular biology.", "ela": "Review — the most important paper you read this year and why.", "writing": "Year synthesis: the paper that most changed your understanding of biology.", "ss": "Review — the biological idea that most changes your understanding of yourself."}, "26": {"math": "Proof in algebra — justifying every step with a property.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Shahid witnesses not from outside but from within the reality of what is witnessed. What is the difference between evidence and witness?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "The standard of evidence in Islamic jurisprudence is stricter than the standard of evidence in modern science.", "sci": "Evidence for evolution — the convergence of fossil, anatomical, and molecular data.", "ela": "Evolution synthesis — reading about the modern evolutionary synthesis.", "writing": "Evolutionary synthesis essay: why did the modern evolutionary synthesis require both Darwin and genetics?", "ss": "The modern evolutionary synthesis — how Darwin and Mendel were united."}, "27": {"math": "Connecting algebra, geometry, and data analysis.", "scholar": "Al-Farabi", "openingQ": "Al-Haqq is not merely accurate but the ground of all accuracy. Al-Farabi built logic as a ladder toward truth. At what point does the ladder become unnecessary?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Al-Farabi's classification of the sciences is more useful as a map of knowledge than any modern academic curriculum.", "sci": "Open questions in biology — the unsolved problems of life science.", "ela": "The unanswered questions in biology — reading about ongoing research.", "writing": "Research proposal: write a full research proposal for a biological question.", "ss": "The future of biology — what will be possible in your lifetime?"}, "28": {"math": "Introduction to Algebra II — polynomial and rational functions.", "scholar": "Al-Idrisi", "openingQ": "Al-Badi creates without precedent — the universe is not a copy of anything. Is human creativity ever genuinely original, or always recombination?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Al-Idrisi's cartography was the last moment of genuinely original Islamic geographic thinking — everything after was commentary.", "sci": "Preview of Grade 10 — chemistry at depth.", "ela": "Preview of Grade 10 chemistry.", "writing": "Preview essay: what is the difference between biology and chemistry at the molecular level?", "ss": "Preview of Grade 10 chemistry."}, "29": {"math": "Extended investigation — modelling a real-world situation algebraically.", "scholar": "Al-Biruni", "openingQ": "Al-Sabur is patient not because nothing matters, but because everything will arrive at its proper time. What is the difference between patience and passivity?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Al-Biruni's patient, lifelong accumulation of knowledge was a more valuable contribution to human understanding than any single discovery.", "sci": "Extended biological investigation — original research question, method, results.", "ela": "Scientific writing — reading and evaluating three different methods sections.", "writing": "Peer review: review a classmate's research proposal for clarity, feasibility, and significance.", "ss": "Scientific ethics — how should research be governed?"}, "30": {"math": "Capstone: an algebraic investigation connecting equations, functions, and data.", "scholar": "Al-Battani", "openingQ": "Al-Awwal and Al-Akhir — the first and the last, the boundaries within which all time exists. What question about existence do you carry that no year of learning will fully answer?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The question you cannot answer is more valuable than all the questions you can.", "sci": "Capstone: connecting molecular biology, genetics, ecology, and evolution.", "ela": "Capstone reading — a text connecting molecular biology to ecology to evolution.", "writing": "Capstone essay: connect molecular biology, genetics, ecology, and evolution in 1500 words.", "ss": "Biology and the human condition — what life science tells us about who we are."}}, "10": {"1": {"math": "Foundations of geometry — undefined terms, definitions, postulates. Al-Idrisi built maps on geometric foundations.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's map was wrong in places and still the most accurate of its time. When is a flawed creation better than no creation?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A flawed creation that exists is worth more than a perfect creation that does not.", "sci": "Atomic theory and quantum mechanics — what is an electron really doing?", "ela": "The quantum atom — reading about Bohr, Heisenberg, and the end of common sense.", "writing": "Conceptual essay: explain why quantum mechanics required a new kind of thinking.", "ss": "Quantum mechanics and certainty — what does it mean when science cannot be certain?"}, "2": {"math": "Patterns in geometry — tessellations, symmetry, and Islamic geometric art.", "scholar": "Al-Biruni", "openingQ": "Is a pattern a property of the world, or a property of the mind that perceives it?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is discovered, not invented — its truths exist independent of human minds.", "sci": "Periodic trends — why do elements in the same column behave similarly?", "ela": "The periodic table as a pattern — reading Mendeleev's story of the dream.", "writing": "History of science: tell the story of how Mendeleev predicted undiscovered elements.", "ss": "The periodic table and national identity — the naming of elements."}, "3": {"math": "Logic and proof — conditional statements, converses, contrapositives.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd believed reason and revelation share a foundation. What holds your own beliefs together?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "Reason and revelation cannot contradict each other — when they appear to, one of them is wrong.", "sci": "Chemical bonding — VSEPR theory and molecular geometry.", "ela": "Molecular geometry — reading about why the shape of a molecule determines its smell.", "writing": "Explanatory essay: how does the shape of a molecule determine its smell?", "ss": "Molecular geometry and the perfume industry."}, "4": {"math": "Segment and angle bisectors. The geometry of fair division.", "scholar": "Al-Khwarizmi", "openingQ": "Islamic inheritance law gives daughters half what sons receive. Al-Khwarizmi built algebra to calculate it precisely. What does precision in an unjust system produce?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Precision in an unjust system makes the injustice worse, not better.", "sci": "Stoichiometry — calculating quantities in chemical reactions.", "ela": "Stoichiometry — reading Lavoisier's account of burning and what he found.", "writing": "Historical argument: why was Lavoisier's conservation of mass a paradigm shift?", "ss": "Lavoisier and measurement — the politics of precision."}, "5": {"math": "Parallel and perpendicular lines. Properties and proofs.", "scholar": "Al-Kashi", "openingQ": "All scientific measurement contains error. Does that mean science only produces approximations, never truth?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "All scientific measurement is approximation — therefore science never achieves truth, only usefulness.", "sci": "Solutions — concentration, molarity, and the mathematics of dilution.", "ela": "Solutions — reading about how kidney dialysis works as applied chemistry.", "writing": "Applied chemistry essay: explain how kidney dialysis works as a chemistry problem.", "ss": "Chemistry and medicine — from aspirin to chemotherapy."}, "6": {"math": "Proving triangles congruent — SSS, SAS, ASA, AAS.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun invented the scientific study of history. What assumptions do you have to make before you can trust any source at all?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "All historical sources are biased — therefore historical truth is impossible.", "sci": "Acid-base equilibria — buffers and pH control in living systems.", "ela": "Buffers — reading about why your blood pH stays constant.", "writing": "Biochemistry essay: explain why a blood buffer is a matter of life and death.", "ss": "Acid rain — the first global atmospheric chemistry crisis."}, "7": {"math": "Triangle properties — midsegments, medians, altitudes, angle bisectors.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham said: do not trust any result until you have tested it yourself. What would it cost you to apply that principle to everything you believe?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Ibn al-Haytham's experimental method is the most important intellectual invention in human history.", "sci": "Kinetics — what determines how fast a reaction proceeds?", "ela": "Reaction rates — reading about why food goes off faster in summer.", "writing": "Kinetics essay: explain why food spoils faster in summer.", "ss": "The chemistry of fermentation — how chemistry gave civilisation alcohol, bread, and medicine."}, "8": {"math": "The circle — central angles, inscribed angles, arcs, chords. Al-Battani's astronomical geometry.", "scholar": "Al-Battani", "openingQ": "Al-Battani used circles to map the heavens. Al-Muhit surrounds all existence. Is the circle a mathematical fact, a physical reality, or a spiritual symbol — or all three at once?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "The unreasonable effectiveness of mathematics in describing the physical world requires explanation.", "sci": "Thermodynamics — enthalpy, entropy, and Gibbs free energy.", "ela": "Thermodynamics — reading Feynman on entropy: why you cannot unscramble an egg.", "writing": "Philosophy of science: what does entropy tell us about the direction of time?", "ss": "Thermodynamics and the Industrial Revolution."}, "9": {"math": "Circle theorems — tangent lines, secants, and their relationships.", "scholar": "Ibn Sina", "openingQ": "Al-Latif is the subtly kind — care that arrives before it is asked for. Is there a parallel between divine providence and the self-regulating systems of living organisms?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "There is no fundamental difference between a living organism and a very complicated machine.", "sci": "Electrochemistry — oxidation, reduction, and batteries.", "ela": "Electrochemistry — reading about how a lithium battery works.", "writing": "Technology essay: explain the chemistry of a lithium battery.", "ss": "Batteries and the energy transition."}, "10": {"math": "Transformations — translation, rotation, reflection, dilation as formal geometric functions.", "scholar": "Al-Masudi", "openingQ": "Al-Halim is the forbearing — unchanged by provocation. In a world where everything changes, what is the value of constancy?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Al-Halim's forbearance in the face of change is the highest possible response to existence.", "sci": "Nuclear chemistry — radioactive decay and half-life.", "ela": "Radioactive decay — reading about carbon dating and what it tells us.", "writing": "Radiochemistry essay: explain carbon dating and its limitations.", "ss": "Nuclear weapons and deterrence."}, "11": {"math": "Symmetry — rotational and reflective. The mathematics behind Islamic geometric patterns.", "scholar": "Hunayn ibn Ishaq", "openingQ": "The Quran is untranslatable — its meaning depends on its Arabic. Hunayn translated Greek science into Arabic and saved it. What is the relationship between language and truth?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "A translation that changes the meaning to be truer to the target language is more faithful than one that preserves the words.", "sci": "Organic chemistry — functional groups and reaction types.", "ela": "Organic chemistry — reading about how Kekulé discovered the structure of benzene in a dream.", "writing": "History of science: how did Kekulé's dream lead to the structure of benzene?", "ss": "Organic chemistry and the plastics industry."}, "12": {"math": "Congruence and similarity — formal proofs using transformations.", "scholar": "Al-Jahiz", "openingQ": "Al-Ghafur covers and conceals wrongdoing. In ecology, a disturbed system tries to restore equilibrium. Is the desire for order a property of nature, or of mind?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Al-Jahiz's proto-evolutionary ideas were more advanced than the Islamic scholarly tradition gave him credit for.", "sci": "Biochemistry — proteins, carbohydrates, lipids, and nucleic acids.", "ela": "Biochemistry — reading about how proteins fold and what happens when they do not.", "writing": "Biochemistry essay: what happens when a protein folds incorrectly?", "ss": "Prion diseases — what happens when proteins misfold."}, "13": {"math": "Triangle similarity — AA, SAS, SSS similarity. Al-Ghazali's geometric approach to proportion.", "scholar": "Al-Ghazali", "openingQ": "Al-Hakim is the all-wise. Al-Ghazali argued that Islamic scholars had confused knowledge with wisdom. What is the difference, and can a person have one without the other?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Al-Ghazali's critique of philosophy was itself philosophical — therefore his critique failed.", "sci": "Chemical analysis — spectroscopy and how we identify unknown substances.", "ela": "Spectroscopy — reading about how we know what distant stars are made of.", "writing": "Analytical essay: how does spectroscopy allow us to know what distant stars contain?", "ss": "Forensic chemistry and justice."}, "14": {"math": "Trigonometry — right triangle ratios. Sine, cosine, tangent and their origin in Al-Battani's work.", "scholar": "Jabir ibn Hayyan", "openingQ": "Al-Wadud is love that gives without requiring lovability in return. Jabir built chemistry on sharing method. Is generosity in knowledge the same as generosity in love?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Jabir ibn Hayyan's systematic experimentation made him the true founder of modern science — not Galileo or Newton.", "sci": "Green chemistry — designing reactions that produce less waste.", "ela": "Green chemistry — reading about the 12 principles and why they matter.", "writing": "Sustainability essay: evaluate the 12 principles of green chemistry.", "ss": "Green chemistry and the future of manufacturing."}, "15": {"math": "Applications of trigonometry — angle of elevation and depression.", "scholar": "Ibn al-Nafis", "openingQ": "Al-Qawiyy is strength — but the Prophet ﷺ said the strongest person is not the one who wins fights but the one who controls themselves when angry. What is the strongest form of communication?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Ibn al-Nafis was morally obliged to publish his discovery of pulmonary circulation even at the risk of his life.", "sci": "Science communication — writing a chemistry lab report to publishable standard.", "ela": "Scientific writing — reading a chemistry paper and identifying the structure.", "writing": "Writing workshop: revise and resubmit your best scientific argument from this year.", "ss": "Science communication and public trust."}, "16": {"math": "The law of sines and cosines for non-right triangles.", "scholar": "Al-Tusi", "openingQ": "Al-Waliyy is the protecting friend — the guardian who sustains cycles of care invisibly. Is it possible to understand a system from the inside, while you are sustained by it?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Al-Tusi's mathematical model was more important than Copernicus's heliocentric theory.", "sci": "Atmospheric chemistry — the ozone layer and greenhouse gases.", "ela": "Atmospheric chemistry — reading about the ozone layer and CFCs.", "writing": "Environmental chemistry essay: explain how CFCs damage the ozone layer.", "ss": "The ozone layer — the first global chemical crisis."}, "17": {"math": "Coordinate geometry — distance formula, midpoint formula, slope.", "scholar": "Ibn Battuta", "openingQ": "Al-Karim gives before being asked. The Islamic scholarly tradition flows through isnad chains — named people giving named people what was given to them. What do you owe to people you have never met?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The Islamic scholarly tradition was more advanced than European scholarship in every field until at least 1400 CE.", "sci": "Industrial chemistry — how chemicals are manufactured at scale.", "ela": "Industrial chemistry — reading about the nitrogen fertiliser industry and its consequences.", "writing": "Industrial ethics essay: should nitrogen fertiliser production continue at current scale?", "ss": "The nitrogen fertiliser industry and its consequences."}, "18": {"math": "Equations of circles in the coordinate plane. Precision in representing curves algebraically.", "scholar": "Al-Kashi", "openingQ": "Al-Raqib watches every act and every intention. Precision is a form of attention. What is the relationship between being watched and doing careful work?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Al-Kashi's contributions to mathematics were as significant as Al-Khwarizmi's, and the neglect of his legacy is itself a form of injustice.", "sci": "Analytical chemistry and precision — mass spectrometry and chromatography.", "ela": "Analytical chemistry — reading about how forensic chemistry solved a crime.", "writing": "Forensic essay: explain how forensic chemistry solved a specific case.", "ss": "Forensic chemistry and wrongful conviction."}, "19": {"math": "Area formulas — parallelogram, trapezoid, regular polygons.", "scholar": "Ibn Majid", "openingQ": "Al-Wasi is spacious beyond all measure. Every expanding understanding requires letting go of the frame that used to contain it. What do you have to give up in order to understand something genuinely new?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Ibn Majid's guidance of Vasco da Gama was an act that damaged the Islamic world more than any Mongol invasion.", "sci": "Environmental chemistry — heavy metals and persistent organic pollutants.", "ela": "Heavy metals — reading about mercury poisoning in Minamata Bay.", "writing": "Environmental justice essay: who is responsible for mercury poisoning in Minamata Bay?", "ss": "Mercury and Minamata — the cost of industrial chemistry."}, "20": {"math": "Surface area and volume of three-dimensional solids.", "scholar": "Al-Jazari", "openingQ": "Al-Muqit provides the precise nourishment each thing needs to be itself fully. Is a tool that extends your capability also extending your nature — or replacing part of it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "A machine that automates a decision is fundamentally different from a machine that automates a physical task.", "sci": "Chemical engineering — designing chemical processes with controlled flow.", "ela": "Chemical engineering — reading about how a refinery works.", "writing": "Chemical engineering essay: explain how a refinery works.", "ss": "The oil refinery — how the 20th century ran on chemistry."}, "21": {"math": "Cross-sections and solids of revolution.", "scholar": "Ibn Battuta", "openingQ": "Al-Hasib is the reckoner — every atom accounted for. Heritage is what we choose to count. What gets lost from history when we do not measure it carefully?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The destruction of the Abbasid library by the Mongols was the single greatest loss in intellectual history.", "sci": "History of chemistry — from Jabir ibn Hayyan to Lavoisier to modern synthesis.", "ela": "History of chemistry — from Jabir to Lavoisier to Curie. Reading the lineage.", "writing": "History of chemistry essay: compare the scientific methods of Jabir ibn Hayyan, Lavoisier, and Marie Curie.", "ss": "From Jabir to Curie — a history of chemistry through its practitioners."}, "22": {"math": "Introduction to vectors — directed quantities with magnitude and direction.", "scholar": "Al-Maqrizi", "openingQ": "Al-Muqaddir decrees exact measures. Al-Maqrizi documented exact economic injustice. Is measurement in the service of justice the same as measurement in the service of efficiency?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Al-Maqrizi's economic analysis of the Mamluk crisis is more important to read today than any modern economics textbook.", "sci": "Climate chemistry — the chemical reactions driving climate change.", "ela": "Climate chemistry — reading about the chemical reactions in the atmosphere.", "writing": "Climate argument: explain the chemistry of climate change to a sceptic.", "ss": "Climate chemistry — the carbon cycle and human intervention."}, "23": {"math": "Probability — geometric probability. What fraction of a target does an arrow hit?", "scholar": "Fatima al-Fihri", "openingQ": "Al-Mubdi originates without model or precedent. Fatima al-Fihri began al-Qarawiyyin — the oldest continuously operating university — 1200 years ago. What does it take to create an institution rather than just a building?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "The university system — which began at al-Qarawiyyin — has done more harm than good to human knowledge.", "sci": "Pharmaceutical chemistry — how drugs are designed and tested.", "ela": "Drug design — reading about how aspirin was discovered and how it works.", "writing": "Drug design essay: explain how aspirin was discovered and how it works.", "ss": "The opioid crisis — chemistry, medicine, and corporate responsibility."}, "24": {"math": "Conditional probability and independence.", "scholar": "Ibn Khaldun", "openingQ": "Al-Muid is the restorer — nothing truly lost, only waiting to be brought back. Is restoration the same as creation, or something different?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "The Islamic Golden Age ended because its social complexity exceeded its institutional capacity — and the same is true of every fallen civilisation.", "sci": "Complex chemical systems — non-linear reactions and oscillating chemistry.", "ela": "Non-linear chemistry — reading about the Belousov-Zhabotinsky reaction.", "writing": "Complexity essay: explain the Belousov-Zhabotinsky reaction as a system.", "ss": "Non-linear systems — when chemistry escapes control."}, "25": {"math": "Reviewing proof — what have we proven and how did we prove it?", "scholar": "Ibn al-Haytham", "openingQ": "Al-Muhyi gives life not only to bodies but to hearts — through knowledge, through remembrance. What is the difference between information and living knowledge?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The Islamic tradition of oral transmission — memorisation before understanding — produced better scholars than the modern tradition of written analysis.", "sci": "Reviewing organic chemistry — connecting structure, function, and reactivity.", "ela": "Review — the reaction that most surprised you this year and why.", "writing": "Year synthesis: the chemical reaction that most surprised you this year.", "ss": "Review — the chemical reaction that most surprised you this year."}, "26": {"math": "Writing original geometric proofs — combining theorems.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Shahid witnesses not from outside but from within the reality of what is witnessed. What is the difference between evidence and witness?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "The standard of evidence in Islamic jurisprudence is stricter than the standard of evidence in modern science.", "sci": "Evidence in chemistry — how do you prove a reaction produced what you think?", "ela": "Scientific proof in chemistry — reading about how scientists confirmed the structure of DNA using X-ray crystallography.", "writing": "Scientific argument: how did X-ray crystallography prove the structure of DNA?", "ss": "Chemistry and proof — how the structure of DNA was confirmed."}, "27": {"math": "Connecting geometry, algebra, and trigonometry.", "scholar": "Al-Farabi", "openingQ": "Al-Haqq is not merely accurate but the ground of all accuracy. Al-Farabi built logic as a ladder toward truth. At what point does the ladder become unnecessary?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Al-Farabi's classification of the sciences is more useful as a map of knowledge than any modern academic curriculum.", "sci": "Open questions in chemistry — what remains unknown at the frontier.", "ela": "Open questions — reading about what chemists are currently trying to solve.", "writing": "Research proposal: write a full chemistry research proposal.", "ss": "The future of chemistry — what will be possible in your lifetime?"}, "28": {"math": "Introduction to analytic geometry — how algebra describes geometric curves.", "scholar": "Al-Idrisi", "openingQ": "Al-Badi creates without precedent — the universe is not a copy of anything. Is human creativity ever genuinely original, or always recombination?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Al-Idrisi's cartography was the last moment of genuinely original Islamic geographic thinking — everything after was commentary.", "sci": "Preview of Grade 11 — physics at depth.", "ela": "Preview of Grade 11 physics.", "writing": "Preview essay: what is physics that is not covered by chemistry?", "ss": "Preview of Grade 11 physics."}, "29": {"math": "Extended investigation — a geometric modelling problem.", "scholar": "Al-Biruni", "openingQ": "Al-Sabur is patient not because nothing matters, but because everything will arrive at its proper time. What is the difference between patience and passivity?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Al-Biruni's patient, lifelong accumulation of knowledge was a more valuable contribution to human understanding than any single discovery.", "sci": "Extended chemistry investigation — quantitative research with full error analysis.", "ela": "Reading a quantitative chemistry paper — what does the data show?", "writing": "Quantitative analysis: evaluate the data in a chemistry paper.", "ss": "Research ethics in chemistry — who should fund scientific research?"}, "30": {"math": "Capstone: a proof-based geometric investigation.", "scholar": "Al-Battani", "openingQ": "Al-Awwal and Al-Akhir — the first and the last, the boundaries within which all time exists. What question about existence do you carry that no year of learning will fully answer?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The question you cannot answer is more valuable than all the questions you can.", "sci": "Capstone: a chemistry investigation connecting thermodynamics, kinetics, and synthesis.", "ela": "Synthesis — a text connecting thermodynamics, kinetics, and the origin of life.", "writing": "Capstone essay: connect thermodynamics, kinetics, and the origin of life.", "ss": "Chemistry and civilisation — what chemistry has made possible and what it has cost."}}, "12": {"1": {"math": "Limits — formal definition, one-sided limits. Al-Idrisi's approximations as the intuition behind limits.", "scholar": "Al-Idrisi", "openingQ": "Al-Idrisi's map was wrong in places and still the most accurate of its time. When is a flawed creation better than no creation?", "studioActivation": "[Cartography] Your world, your map: Draw a map of a place you know completely from memory. Include everything that matters to you, not just what would appear on an official map. Label it. Compare it with another student's map of the same place — what did each of you include that the other did not?", "munazaraClaim": "A flawed creation that exists is worth more than a perfect creation that does not.", "sci": "Earth as a system — all four spheres interacting. Al-Idrisi's vision of a whole Earth.", "ela": "The Anthropocene — reading about the naming of our geological epoch.", "writing": "Definition essay: what is the Anthropocene and should we accept the name?", "ss": "The Anthropocene — naming our geological epoch."}, "2": {"math": "Continuity — when functions behave predictably. Patterns in continuous functions.", "scholar": "Al-Biruni", "openingQ": "Is a pattern a property of the world, or a property of the mind that perceives it?", "studioActivation": "[Geometry] Pattern hunting: Find three patterns in the physical space around you — in tiles, in brickwork, in fabric, in a leaf. Reproduce each one precisely on paper. Then: invent a fourth pattern that does not exist in what you found, following the same underlying rule.", "munazaraClaim": "Mathematics is discovered, not invented — its truths exist independent of human minds.", "sci": "Energy on Earth — solar radiation, albedo, and the energy balance.", "ela": "Earth's energy budget — reading about how sunlight becomes everything.", "writing": "Explanatory essay: explain Earth's energy budget to a non-specialist.", "ss": "Civilisation and energy — the history of human energy use."}, "3": {"math": "The derivative — formal definition as a limit. The instantaneous rate of change.", "scholar": "Ibn Rushd", "openingQ": "Ibn Rushd believed reason and revelation share a foundation. What holds your own beliefs together?", "studioActivation": "[Architecture] Build a load-bearing structure: Using only paper and tape, build the tallest structure that can support a book. Document every design decision: what failed, what you changed, and why. The structure must be explained, not just built — write one sentence for each choice you made.", "munazaraClaim": "Reason and revelation cannot contradict each other — when they appear to, one of them is wrong.", "sci": "Biogeochemical cycles — carbon, nitrogen, phosphorus, and their human disruption.", "ela": "The carbon cycle — reading about how fast humans are changing a cycle that took millions of years.", "writing": "Argument essay: what is the single most important intervention to slow carbon accumulation?", "ss": "The carbon cycle — how humans disrupted a 400-million-year system."}, "4": {"math": "Derivative rules — power, product, quotient. Building a toolkit for computation.", "scholar": "Al-Khwarizmi", "openingQ": "Islamic inheritance law gives daughters half what sons receive. Al-Khwarizmi built algebra to calculate it precisely. What does precision in an unjust system produce?", "studioActivation": "[Geometry] The mathematics of fair sharing: Using compass and straightedge, divide a circle into equal parts — first halves, then thirds, then sixths. Without measuring, how do you know the parts are equal? Document the method. Connect to Al-Khwarizmi: this is the geometry behind Islamic inheritance mathematics.", "munazaraClaim": "Precision in an unjust system makes the injustice worse, not better.", "sci": "Population biology — carrying capacity, resource limits, and sustainability.", "ela": "Population biology — reading about the demographic transition and what drives it.", "writing": "Demographic essay: explain demographic transition theory and its limits.", "ss": "Population growth — the most consequential trend in human history."}, "5": {"math": "Chain rule — derivative of a composition. Al-Kashi's precision extended to complex calculations.", "scholar": "Al-Kashi", "openingQ": "All scientific measurement contains error. Does that mean science only produces approximations, never truth?", "studioActivation": "[Astronomy] Measure the same thing five ways: Choose one object. Measure it using five different methods or tools. Record every measurement and its source of error. Calculate the mean. Write: what does the spread of your measurements tell you about the difference between precision and accuracy?", "munazaraClaim": "All scientific measurement is approximation — therefore science never achieves truth, only usefulness.", "sci": "Atmospheric science — climate modelling and its uncertainties.", "ela": "Climate modelling — reading about how climate models work and what they cannot predict.", "writing": "Critical analysis: what can climate models predict and what can they not?", "ss": "Climate science — the history of how we understood climate change."}, "6": {"math": "Implicit differentiation and related rates.", "scholar": "Ibn Khaldun", "openingQ": "Ibn Khaldun invented the scientific study of history. What assumptions do you have to make before you can trust any source at all?", "studioActivation": "[Calligraphy] The art of the question: Write the opening question for this week in your best handwriting — or attempt Arabic calligraphy. The goal is not beautiful letters but letters written with full attention. A calligrapher's principle: if your mind is not present, the pen knows. Reflect on what happened when your attention wandered.", "munazaraClaim": "All historical sources are biased — therefore historical truth is impossible.", "sci": "Experimental design at scale — how do scientists study the whole Earth?", "ela": "Systems ecology — reading about the work of Eugene Odum, the first ecosystem ecologist.", "writing": "Scientific biography: who was Eugene Odum and why does he matter?", "ss": "Ecology — the science of relationships."}, "7": {"math": "Applications of differentiation — critical points, maxima, minima. Ibn al-Haytham's optimisation of light paths.", "scholar": "Ibn al-Haytham", "openingQ": "Ibn al-Haytham said: do not trust any result until you have tested it yourself. What would it cost you to apply that principle to everything you believe?", "studioActivation": "[Optics] Build a camera obscura: Build a pinhole camera using a cardboard box or tube. Observe what it projects. Document: is the image right-side up or inverted? What does this tell you about how light travels? This is exactly the experiment Ibn al-Haytham performed in his darkened room in 1011 CE.", "munazaraClaim": "Ibn al-Haytham's experimental method is the most important intellectual invention in human history.", "sci": "Scientific method in environmental science — observational studies vs experiments.", "ela": "The scientific method in environmental science — reading about long-term ecological research.", "writing": "Research design essay: how would you design a long-term ecological study?", "ss": "Environmental research — the long view."}, "8": {"math": "Curve sketching — using derivatives to understand function behaviour. Al-Battani's orbital curves.", "scholar": "Al-Battani", "openingQ": "Al-Battani used circles to map the heavens. Al-Muhit surrounds all existence. Is the circle a mathematical fact, a physical reality, or a spiritual symbol — or all three at once?", "studioActivation": "[Astronomy] The compass and the circle: Using compass and straightedge only: construct a circle, inscribe a regular hexagon, then a twelve-pointed star. Measure the circumference with string and compare to 2πr. Document the method Al-Battani would have used. What is the relationship between the geometry of the circle and the ratio pi?", "munazaraClaim": "The unreasonable effectiveness of mathematics in describing the physical world requires explanation.", "sci": "Planetary science — what do other planets tell us about Earth? Al-Battani's comparative astronomy.", "ela": "Planetary comparison — reading about Venus as a cautionary tale.", "writing": "Comparative essay: what does Venus teach us about Earth's future?", "ss": "Planetary science — what other planets teach us about Earth."}, "9": {"math": "Optimisation problems — finding the maximum or minimum of a real-world quantity.", "scholar": "Ibn Sina", "openingQ": "Al-Latif is the subtly kind — care that arrives before it is asked for. Is there a parallel between divine providence and the self-regulating systems of living organisms?", "studioActivation": "[Pharmacy] A living system in miniature: Set up a terrarium, a germination experiment, or a water ecosystem in a jar. Document the system's components and their relationships. Over three days, observe and record one change per day. Write: what would Ibn Sina say is the difference between this system and the container it lives in?", "munazaraClaim": "There is no fundamental difference between a living organism and a very complicated machine.", "sci": "Conservation biology — ecosystem services and their value.", "ela": "Ecosystem services — reading about the economics of clean water.", "writing": "Policy essay: how should ecosystem services be valued in economic terms?", "ss": "Ecosystem services — what nature provides and how we value it."}, "10": {"math": "Mean Value Theorem — a continuous function must achieve its average rate of change somewhere.", "scholar": "Al-Masudi", "openingQ": "Al-Halim is the forbearing — unchanged by provocation. In a world where everything changes, what is the value of constancy?", "studioActivation": "[Natural History] Document change: Choose one thing in the natural world that changes across the week — a plant, the sky at a fixed time, shadow length, temperature. Measure and record it every day. At the end: what stayed constant? What changed? Al-Masudi travelled 30 countries to answer this question. You have the same question in a smaller frame.", "munazaraClaim": "Al-Halim's forbearance in the face of change is the highest possible response to existence.", "sci": "Oceanography — ocean acidification and its consequences.", "ela": "Ocean acidification — reading about what happens to coral when pH drops 0.1.", "writing": "Science journalism: write a feature article on ocean acidification.", "ss": "Ocean acidification — the second CO2 crisis."}, "11": {"math": "Antiderivatives — undoing the derivative. Al-Tusi's treatment of inverse operations.", "scholar": "Hunayn ibn Ishaq", "openingQ": "The Quran is untranslatable — its meaning depends on its Arabic. Hunayn translated Greek science into Arabic and saved it. What is the relationship between language and truth?", "studioActivation": "[Calligraphy] Translate without words: Take a concept from this week's mathematics or science. Represent it first in words, then in a diagram, then in a geometric form, then in a physical model (however small). Hunayn ibn Ishaq said translation is not about words — it is about ideas. Which of your four representations is truest to the idea?", "munazaraClaim": "A translation that changes the meaning to be truer to the target language is more faithful than one that preserves the words.", "sci": "Environmental policy — how scientific evidence becomes law.", "ela": "Environmental policy — reading about how the Montreal Protocol banned CFCs.", "writing": "Policy analysis: how did the Montreal Protocol succeed and what can it teach us?", "ss": "The Montreal Protocol — the most successful environmental treaty."}, "12": {"math": "Definite integral — area under a curve as a limit of sums.", "scholar": "Al-Jahiz", "openingQ": "Al-Ghafur covers and conceals wrongdoing. In ecology, a disturbed system tries to restore equilibrium. Is the desire for order a property of nature, or of mind?", "studioActivation": "[Natural History] Your own classification system: Collect 20 natural objects or images. Create your own classification system from first principles — do not use the categories you already know. Justify every category boundary. Then: look up how Al-Jahiz classified similar objects. Where does your system agree? Where does it diverge, and why?", "munazaraClaim": "Al-Jahiz's proto-evolutionary ideas were more advanced than the Islamic scholarly tradition gave him credit for.", "sci": "Taxonomy of environmental problems — classifying types of environmental damage.", "ela": "Classification of environmental crises — reading about the nine planetary boundaries.", "writing": "Classification essay: explain the nine planetary boundaries and how close we are to each.", "ss": "Planetary boundaries — how close are we?"}, "13": {"math": "Fundamental Theorem of Calculus — the connection between differentiation and integration.", "scholar": "Al-Ghazali", "openingQ": "Al-Hakim is the all-wise. Al-Ghazali argued that Islamic scholars had confused knowledge with wisdom. What is the difference, and can a person have one without the other?", "studioActivation": "[Architecture] Structure that embodies wisdom: Design (on paper) a space for thinking — a room, a garden, a corner. What does it include? What does it exclude? What does its structure say about what you believe good thinking requires? Al-Ghazali left Baghdad's greatest institution to seek truth in a simpler place. What did he know about space and thought?", "munazaraClaim": "Al-Ghazali's critique of philosophy was itself philosophical — therefore his critique failed.", "sci": "Risk assessment — how do we make decisions under scientific uncertainty?", "ela": "Precautionary principle — reading about when to act before you are certain.", "writing": "Ethics essay: when should we act on incomplete evidence?", "ss": "The precautionary principle — when to act before certainty."}, "14": {"math": "Integration by substitution — the reverse chain rule.", "scholar": "Jabir ibn Hayyan", "openingQ": "Al-Wadud is love that gives without requiring lovability in return. Jabir built chemistry on sharing method. Is generosity in knowledge the same as generosity in love?", "studioActivation": "[Pharmacy] Observable reactions: Combine at least three safe household materials and record what happens: colour change, temperature change, gas production, texture change, smell. Document each combination like Jabir ibn Hayyan would: materials, quantities, procedure, result. Which changes were reversible? Which were not? Jabir distinguished them 1200 years ago.", "munazaraClaim": "Jabir ibn Hayyan's systematic experimentation made him the true founder of modern science — not Galileo or Newton.", "sci": "Green chemistry and sustainable engineering — designing with the whole system in mind.", "ela": "Biomimicry — reading about designs inspired by the natural world.", "writing": "Design essay: choose one example of biomimicry and explain what it borrows from nature.", "ss": "Biomimicry — learning from 3.8 billion years of evolution."}, "15": {"math": "Area between curves — integration as a tool for precise comparison.", "scholar": "Ibn al-Nafis", "openingQ": "Al-Qawiyy is strength — but the Prophet ﷺ said the strongest person is not the one who wins fights but the one who controls themselves when angry. What is the strongest form of communication?", "studioActivation": "[Calligraphy] Communicate without shared language: You must communicate a scientific concept to someone who does not share your language. You may use diagrams, symbols, mathematical notation, and objects — but no words in any language. Create the artefact. Test it: can another student decode your meaning? Ibn al-Nafis made his discovery legible to anyone who studied the body — language independent.", "munazaraClaim": "Ibn al-Nafis was morally obliged to publish his discovery of pulmonary circulation even at the risk of his life.", "sci": "Science communication — communicating environmental risk to non-specialists.", "ela": "Science communication — reading about how to communicate risk without lying.", "writing": "Science communication essay: how do you communicate risk without creating false certainty?", "ss": "Science communication — how environmental risk becomes public knowledge."}, "16": {"math": "Volumes of revolution — rotating a curve to create a three-dimensional solid.", "scholar": "Al-Tusi", "openingQ": "Al-Waliyy is the protecting friend — the guardian who sustains cycles of care invisibly. Is it possible to understand a system from the inside, while you are sustained by it?", "studioActivation": "[Astronomy] Model the Tusi couple: Using two circles of the right proportional sizes — one rolling inside the other — demonstrate the Tusi couple: two circular motions producing linear motion. Build it from card and a pin, or model it digitally. Write one paragraph: what does this tell us about the relationship between simple motion and complex motion?", "munazaraClaim": "Al-Tusi's mathematical model was more important than Copernicus's heliocentric theory.", "sci": "Earth's climate history — ice cores, pollen, and what the past tells us about the future.", "ela": "Ice cores — reading about what 800,000 years of climate data looks like.", "writing": "Deep time essay: what does 800,000 years of climate data reveal?", "ss": "Palaeoclimatology — reading the deep past for the near future."}, "17": {"math": "Introduction to differential equations — equations relating a function to its derivative.", "scholar": "Ibn Battuta", "openingQ": "Al-Karim gives before being asked. The Islamic scholarly tradition flows through isnad chains — named people giving named people what was given to them. What do you owe to people you have never met?", "studioActivation": "[Cartography] Map the knowledge journey: Create a map — not of a place, but of the knowledge you have received this year. Each scholar is a city. The connections between them are roads. The knowledge you carry is the journey. Ibn Battuta mapped geography; you are mapping intellectual inheritance. What does your map reveal about where you have been?", "munazaraClaim": "The Islamic scholarly tradition was more advanced than European scholarship in every field until at least 1400 CE.", "sci": "Islamic environmental ethics — the concept of khalifa and stewardship of the Earth.", "ela": "Khalifa — reading Islamic environmental ethics. What does it mean to be a steward?", "writing": "Islamic ethics essay: what does khalifa mean and what does it demand of us?", "ss": "Khalifa — Islamic environmental stewardship as a framework."}, "18": {"math": "Numerical methods — when analytic solutions are impossible. Al-Kashi's iterative computation.", "scholar": "Al-Kashi", "openingQ": "Al-Raqib watches every act and every intention. Precision is a form of attention. What is the relationship between being watched and doing careful work?", "studioActivation": "[Astronomy] Precision construction: Using compass and straightedge, construct a regular polygon with as many sides as you can manage — aiming for 12 or more. Measure each side. Calculate the maximum error as a percentage of the mean. Document every step. Al-Kashi would have written this up as a formal proof of method. So should you.", "munazaraClaim": "Al-Kashi's contributions to mathematics were as significant as Al-Khwarizmi's, and the neglect of his legacy is itself a form of injustice.", "sci": "Measurement at scale — remote sensing and satellite data in environmental science.", "ela": "Remote sensing — reading about how satellites measure ice sheets.", "writing": "Technology essay: how do satellites measure ice sheets?", "ss": "Remote sensing — the technology of planetary observation."}, "19": {"math": "Exponential growth and decay — differential equations with applications.", "scholar": "Ibn Majid", "openingQ": "Al-Wasi is spacious beyond all measure. Every expanding understanding requires letting go of the frame that used to contain it. What do you have to give up in order to understand something genuinely new?", "studioActivation": "[Cartography] Map an unknown territory: Choose a space you know very well but have never mapped — your room, a garden, a route you walk daily. Map it from memory first. Then survey it and measure. Overlay the two maps. Where was memory accurate? Where did it compress, expand, or omit? Ibn Majid navigated by instruments — but he always knew where he was before he started.", "munazaraClaim": "Ibn Majid's guidance of Vasco da Gama was an act that damaged the Islamic world more than any Mongol invasion.", "sci": "Human geography and environment — where people live and why.", "ela": "Environmental justice — reading about who bears the cost of pollution.", "writing": "Environmental justice essay: who bears the burden of pollution and why?", "ss": "Environmental justice — the global geography of environmental burden."}, "20": {"math": "Introduction to series — the sum of infinitely many terms.", "scholar": "Al-Jazari", "openingQ": "Al-Muqit provides the precise nourishment each thing needs to be itself fully. Is a tool that extends your capability also extending your nature — or replacing part of it?", "studioActivation": "[Engineering] Build a redirecting machine: Build a device — from any available materials — that redirects force: a lever, a pulley, a ramp, a waterwheel, a crank. The device must visibly change the direction or magnitude of a force. Document the mechanical principle. Write: which of Al-Jazari's 50 devices uses this same principle?", "munazaraClaim": "A machine that automates a decision is fundamentally different from a machine that automates a physical task.", "sci": "Renewable energy — physics, engineering, and economics of the energy transition.", "ela": "Renewable energy — reading about the energy transition in Denmark.", "writing": "Case study: how did Denmark achieve 50% renewable energy?", "ss": "The energy transition — how fast is it happening and is it fast enough?"}, "21": {"math": "Taylor series — approximating functions with polynomials.", "scholar": "Ibn Battuta", "openingQ": "Al-Hasib is the reckoner — every atom accounted for. Heritage is what we choose to count. What gets lost from history when we do not measure it carefully?", "studioActivation": "[Architecture] Archive this year: Create an archive of your year in the studio — select one object or image from each discipline you worked in. Arrange them. Write a label for each. An archive is not a collection: it is an argument about what matters. Ibn Battuta's Rihla was an archive of a world. Yours is an archive of a year. What is the argument yours makes?", "munazaraClaim": "The destruction of the Abbasid library by the Mongols was the single greatest loss in intellectual history.", "sci": "Biodiversity and evolution — the sixth mass extinction in geological context.", "ela": "The sixth mass extinction — reading Elizabeth Kolbert on what we are losing.", "writing": "Book review: write a critical review of an Elizabeth Kolbert chapter.", "ss": "The sixth mass extinction — what we are losing and what it means."}, "22": {"math": "Introduction to multi-variable calculus — functions of two variables.", "scholar": "Al-Maqrizi", "openingQ": "Al-Muqaddir decrees exact measures. Al-Maqrizi documented exact economic injustice. Is measurement in the service of justice the same as measurement in the service of efficiency?", "studioActivation": "[Geometry] The geometry of justice: Design a system for distributing something fairly among an unequal group — more to those who need more. Represent it geometrically: equal shares as equal areas, unequal shares as unequal areas that still total the whole. Al-Maqrizi documented economic injustice numerically. You are making it visible.", "munazaraClaim": "Al-Maqrizi's economic analysis of the Mamluk crisis is more important to read today than any modern economics textbook.", "sci": "Environmental justice — who bears the burden of environmental damage?", "ela": "Environmental racism — reading about Cancer Alley in Louisiana.", "writing": "Investigative essay: what is happening in Cancer Alley and who is responsible?", "ss": "Environmental racism — a global history."}, "23": {"math": "Partial derivatives — how a function changes in one direction while the other is held fixed.", "scholar": "Fatima al-Fihri", "openingQ": "Al-Mubdi originates without model or precedent. Fatima al-Fihri began al-Qarawiyyin — the oldest continuously operating university — 1200 years ago. What does it take to create an institution rather than just a building?", "studioActivation": "[Engineering] Build from no instructions: You will be given materials and one constraint: the object must be structurally self-supporting. No other instructions. Document every decision as you make it — you are writing the instructions for this object as you go. Fatima al-Fihri had no blueprint for a university. She built one anyway. What did you have to invent?", "munazaraClaim": "The university system — which began at al-Qarawiyyin — has done more harm than good to human knowledge.", "sci": "Geoengineering — proposed interventions and their risks.", "ela": "Geoengineering — reading a debate between two scientists who disagree.", "writing": "Debate essay: should geoengineering be researched, piloted, or banned?", "ss": "Geoengineering — last resort or dangerous gamble?"}, "24": {"math": "Introduction to linear algebra — vectors, matrices, and linear transformations.", "scholar": "Ibn Khaldun", "openingQ": "Al-Muid is the restorer — nothing truly lost, only waiting to be brought back. Is restoration the same as creation, or something different?", "studioActivation": "[Natural History] Restore something: Take something broken, incomplete, or disordered — a torn diagram, an unfinished model, a scattered collection. Restore it. Then: document not just what you did but what you had to understand about the original to restore it. Ibn Khaldun said civilisations are restored only by people who understand what they were. This is practice for that.", "munazaraClaim": "The Islamic Golden Age ended because its social complexity exceeded its institutional capacity — and the same is true of every fallen civilisation.", "sci": "Complex systems and tipping points — when does a slow change become a sudden shift?", "ela": "Tipping points — reading about the West Antarctic ice sheet.", "writing": "Tipping point essay: explain the West Antarctic ice sheet tipping point.", "ss": "Tipping points — the non-linear dynamics of the Earth system."}, "25": {"math": "Reviewing the year — the unity of calculus: limits, derivatives, and integrals.", "scholar": "Ibn al-Haytham", "openingQ": "Al-Muhyi gives life not only to bodies but to hearts — through knowledge, through remembrance. What is the difference between information and living knowledge?", "studioActivation": "[Calligraphy] Teach through making: Make something — a diagram, a model, a geometric form — that teaches a concept from this year without using words. Then sit with a student younger than you and use only your made object to explain the concept. Write: what did you understand better after trying to teach it?", "munazaraClaim": "The Islamic tradition of oral transmission — memorisation before understanding — produced better scholars than the modern tradition of written analysis.", "sci": "Reviewing Earth systems — connecting all spheres and their human disruptions.", "ela": "Review — the environmental text that most changed your thinking.", "writing": "Year synthesis: the text that most changed your thinking this year.", "ss": "Review — the environmental argument that most changed your thinking."}, "26": {"math": "The Fundamental Theorem revisited — why it is the most important theorem in calculus.", "scholar": "Al-Khwarizmi", "openingQ": "Al-Shahid witnesses not from outside but from within the reality of what is witnessed. What is the difference between evidence and witness?", "studioActivation": "[Geometry] Physical proof: Choose a geometric theorem and prove it physically — not on paper, but in space. Use string, objects, or your own body. Document the proof with photographs or drawings. Al-Khwarizmi said algebra is geometry in another form. Can you find the geometric version of an algebraic proof you know?", "munazaraClaim": "The standard of evidence in Islamic jurisprudence is stricter than the standard of evidence in modern science.", "sci": "Evidence and proof in environmental science — how we know climate is changing.", "ela": "Climate evidence — reading the IPCC report summary for policymakers.", "writing": "Policy brief: write a 500-word policy brief based on the IPCC report.", "ss": "The IPCC — how international scientific consensus is built."}, "27": {"math": "Connecting calculus, algebra, geometry, and the history of mathematics.", "scholar": "Al-Farabi", "openingQ": "Al-Haqq is not merely accurate but the ground of all accuracy. Al-Farabi built logic as a ladder toward truth. At what point does the ladder become unnecessary?", "studioActivation": "[Optics] Light and truth: Create an optical illusion — a drawing, an arrangement of mirrors, or a shadow that misleads the eye. Then explain why it works. Al-Farabi built logic as a tool for finding what is true underneath appearances. Your illusion is the appearance. Write: what does the physics of your illusion tell us about the difference between appearance and reality?", "munazaraClaim": "Al-Farabi's classification of the sciences is more useful as a map of knowledge than any modern academic curriculum.", "sci": "Open questions — what environmental scientists do not yet know.", "ela": "Open questions — reading about what environmental scientists are currently investigating.", "writing": "Research proposal: write a full environmental research proposal.", "ss": "The future — what environmental science tells us about the next 50 years."}, "28": {"math": "Introduction to higher mathematics — what comes after calculus?", "scholar": "Al-Idrisi", "openingQ": "Al-Badi creates without precedent — the universe is not a copy of anything. Is human creativity ever genuinely original, or always recombination?", "studioActivation": "[Calligraphy] Create a new symbol: Invent a symbol — a single mark — that represents one idea from this year that you think matters. It must be legible (someone else should be able to read what it means from your explanation) and original (not a modification of an existing symbol). Al-Idrisi invented new cartographic symbols. Al-Badi creates without precedent. What does your symbol say?", "munazaraClaim": "Al-Idrisi's cartography was the last moment of genuinely original Islamic geographic thinking — everything after was commentary.", "sci": "Capstone preparation — defining an environmental investigation question.", "ela": "Capstone preparation — reading exemplary environmental research.", "writing": "Capstone preparation: outline your environmental investigation.", "ss": "Capstone preparation — research question and methodology."}, "29": {"math": "Extended investigation — modelling a real-world phenomenon using calculus.", "scholar": "Al-Biruni", "openingQ": "Al-Sabur is patient not because nothing matters, but because everything will arrive at its proper time. What is the difference between patience and passivity?", "studioActivation": "[Architecture] Complete an unfinished project: Return to a project from earlier this year that you did not finish or did not do as well as you wanted. Complete it now. Document what is different this time — what do you understand now that you did not then? Al-Biruni spent years completing what he began. Patience is not waiting — it is continuing.", "munazaraClaim": "Al-Biruni's patient, lifelong accumulation of knowledge was a more valuable contribution to human understanding than any single discovery.", "sci": "Capstone research — conducting and analysing an original environmental investigation.", "ela": "Capstone research — reading sources and building an argument.", "writing": "Capstone draft: write the methods and preliminary findings of your investigation.", "ss": "Capstone research — findings and analysis."}, "30": {"math": "Capstone: a complete mathematical investigation connecting limits, derivatives, integrals, and interpretation.", "scholar": "Al-Battani", "openingQ": "Al-Awwal and Al-Akhir — the first and the last, the boundaries within which all time exists. What question about existence do you carry that no year of learning will fully answer?", "studioActivation": "[Astronomy] The year as a circle: Create a visual representation of this year — circular, like a year. Place on it the scholars you encountered, the concepts you learned, the moments that changed your understanding. Where does the year end? Where does it begin? Al-Battani measured the year as the time it takes a point to return to itself. What returns in you?", "munazaraClaim": "The question you cannot answer is more valuable than all the questions you can.", "sci": "Capstone presentation — sharing findings and proposing a response.", "ela": "Final reading — a text about hope and action in the face of environmental crisis.", "writing": "Capstone final: a complete environmental investigation with recommendations.", "ss": "Capstone conclusion — what you found and what it means."}}};
